window.__D("text/sefer-hasichot-rayatz/c011",{"p":[[4301620475,"או שהם בעצמם יודעים מחלתם, ובאים אל הרופא לבקש רפואה, ומהם אשר מצב בריאותם הרוחני נוגע להם בפנימיותם עד דחיקא דמוחא וליבא, ובוכים במר נפשם מגודל הצער בפרטי עניניהם, ומטים אזן קשבת לדבר הרפואות, אבל לעשות עניני הרפואה אינם עושים בחשבם אשר היותם אצל רופא וידיעת הסמני מרפא מספיק.\nאבל באמת הנה טועים הם טעות גמור, כמו החולה בגוף שחושב דמאחר דהסמי מרפא הנם אתו עמו בבית, או גם עומדים לנגד עיניו ומסתכל בהם, וכבר הי' אצל הרופא פעמיים ושלש צריך להתרפאות. ולא זה שאינו מתרפא אלא עוד החולי משתרש ומתישן, אשר כן הוא גם בחולה הנפש, אשר מזה שהי' אצל הרופא, וגם קנה הסמי מרפא והנם אתו עמו בבית, אשר מזה הנה לא זה שלא יתרפא, אלא עוד החולי משתרש ומתישן.\n* * *\nוהנה בחולי הגוף אנו רואין אשר ישנם ר\"ל חולים כאלו אשר לא זו בלבד אשר אינם יודעים כי חולים הם, אלא טועים בעצמם כי בריאים המה. ובהם עוד חולים כאלו אשר חושבים אשר הבריאים הם החולים, והם — החולים הללו — הם הבריאים.\nוהנה זהו על פי רוב בחולי הרוח ר\"ל שאינם יודעים כי חולים המה; ובפרט אלו החולים המרודים החושבים כי הבריאים הם החולים. אשר שניהם כאחד אינם מחפשים אחרי דרכי הרפואה, ומהם גם המנגדים לעניני הרפואה, בטעם כי בריאים הם. ובתוכם ישנם חכמים מחוכמים בעלי המצאה בעניניהם ובעלי כשרון בדיבור והדומה בשאר החושים.\nעיקר מחלתם של חולי הרוח הוא ההזי' והדמיון. להאחד נדמה שהוא ראש העדה והעיר, להשני נדמה שהוא חכם המדינה, ולהשלישי הזי' אחרת, וכולם המה כ\"כ טרודים בעניני הדמיון אשר אין להם זמן לאכול ולישן, ואם באים לרפאותם טוענים כי הם בריאים.\nחולי הדמיון וההזי' הוא בחולי הנפש עוד יותר מכמו בחולי הגוף, ר\"ל. והם עוד מסוכנים יותר. כי חולי הגוף הנה עפ\"י רוב יש מי שדואג עבורם. לא כן בבעלי דמיון וההזי' בחולי הנפש, שהם עזובים לנפשם מבלי דואג להם, ומחלתם ר\"ל מתגברת עליהם משתרשת ומתישנת, הולכים ומתנוונים מזמן לזמן.\n* * *\nאמנם האור עצמי דתורת החסידות יכול הוא לרפאות כל נגע וכל מחלה. אבל לזה הרי בהכרח להשתמש בהסמי מרפא כפי חוקי ספרי תורת החסידות, אשר הן המה דברי הרב. כי דברי הרב כאשר הם נחזרים כמו שנאמרו מפי הרב, הנה כחם אתם עמם לרפאות את כל מיני חולים ולהעמידם בקרן אורה.\n* * *\nהחפץ למלאות תעודתו בחיים בחיי עדת החסידים ואנשי מעשה, ולקיים החוב המוטל עלינו כולנו כאחד, כאמור להאיר לבותיהם של ישראל, ולהאיר בתיהם של ישראל באור התורה ועבודת הבורא ית', הנה צריך להשתדל בכל מיני השתדלות, לעורר לקבוע עתים לתורת החסידות ברבים, בספר ובעל פה, ובהתנאי האמור לשמור דברי הרב, רק זעיר שם זעיר שם הנה לעת מן העתים רשאי הוא הלומד והחוזר ברבים לבאר ולהסביר מהנאמר במקום אחר.\nולכל לראש ללמוד וכן לחזור מאמרי חסידות שמבואר בהם עניני התבוננות באחדות הוי'. ובענין עבודה שבלב"],[4301620476,"בתיקון המדות, אהבת ישראל, הרבצת תורה ויראת שמים והדומה — שהן המה הפרוזדור דהיכל תורת החסידות.\nאחד הענינים הנחוצים ביותר הוא לקבוע זמני המועדות כמו בשבת מברכין, ובכל המועדים לשמחה ויומא דפגרא צריכים להשתמש בהם לקובעם להתועדות — אַ פאַרבריינגען — אשר איש את רעהו יעוררו בכל עניני דרכי החסידות. וכולם יחדיו יושלבו בשאיפה אחת להאחז באילנא דחייא היא היא תורת החסידות המחי' נפש ממש."],[4301620477,"<h3>ח\"י אלול תש\"ח</h3>\nא. אין דער מצוה פון מעשר איז פאַראַן כמה ענינים: מעשר תבואה, מעשר בהמה, מעשר כספים. די מצוה פון מעשר איז אַנדערש פון אַלע מצוות, וואָס מעשר איז דער ענין פון עשירות, עשר בשביל שתתעשר<sup data-n=\"1407\">1</sup>. הגם אין אַלע מצוות איז דאָ דער ענין פון עשירות.\nדער ענין פון עשירות איז נוסף על הקרן, וואָס קרן איז נשמה נר ה' — די נשמה ווי זי איז למעלה, וע\"י ירידת הנשמה למטה איז דאָ די עשירות, שפועל תוספות בהנשמה למעלה, שמדריגת ה­יחידה שבנשמה פועלת תוספות באצילות העליון. הגם אצילות איז דאָך עשירות — אצילות איז דאָך האצלה והפרשה<sup data-n=\"1408\">2</sup>, אָבער דורך די ירידה ווערט אַן עלי' ויתרון באצילות העליון באור העצמי.\nב. חסידות לערנט דעם ענין פון קיצור, וואָס קיצור איז תוכן, און תוכן איז פועל — אַז יעדער ענין ווי הויך ער זאָל ניט זיין זאָל אַראָפּקומען אין פועל. וואָס פועל איז, אַז די פעולה זאָל פועל זיין אין דעם פועל. ווי מען רעדט אין דעם ענין פון עשי' לעילא<sup data-n=\"1409\">3</sup>, אַז עשי' איז פועל אַ יתרון אין דעם לעילא.\nג. ס'איז שווער צו ריידן בארוכה, בפרט יעצט וואָס עס איז אַ זמן פון מעהר טאָן.\nנאָר בכלל איז דאָס אַ המשך פון י\"ב תמוז, ווי מען האָט גערעדט<sup data-n=\"1410\">4</sup> אַז מען דאַרף טאָן מיט זיך און מיט יענעם. ביי יענעם דאַרף מען אָנהויבן פון דעם טוב און וואָס עס פעלט וועט נתמלא ווערן, און ביי זיך דאַרף מען אָנהויבן פון וואָס עס פעלט, גוט דאַרף דאָך זיין — אָבער עס איז פאַראַן גוט און עס איז פאַראַן בעסער<sup data-n=\"1411\">5</sup>.\nד. עס איז דאָך היינט ח\"י אלול, זאָל דער אויבערשטער געבן אַז עס זאָל זיין דער \"אני לדודי ודודי לי\"<sup data-n=\"1412\">6</sup> און \"דודי לי ואני לו\"<sup data-n=\"1413\">7</sup>, ווי דער בעל שם הקדוש האָט עס מפרש געווען און דער אַלטער רבי האָט עס ממשיך געווען.\nה. דער אויבערשטער זאָל געבן עס זאָל זיין אַ התעוררות פנימי אויף טאָן אין עבודה שבלב אין האַרץ און מיט דער האַרץ, עס זאָל זיין אַ כתיבה וחתימה טובה אַ שנה טובה ומתוקה בגשמיות וברוחניות.",[["1407","1","פ' ראה יד, כב. שבת קיט, א. תענית ט, א."],["1408","2","ראה פרדס שער טז (שער אבי\"ע) פ\"א. תו\"א בראשית ג, א. המשך תער\"ב ח\"א ע' יא. סה\"מ תש\"ג ע' 131. ה'שי\"ת ע' 112. ובכ\"מ."],["1409","3","זוהר ח\"ג קח, ב. ח\"א קטו, א."],["1410","4","שיחת י\"ב תמוז שנה זו סעיף מ (לעיל ע' 252 ואילך)."],["1411","5","להעיר מפתגם אדמו\"ר מהר\"ש: צי אַז גוט איז גוט, איז בעסער ניט בעסער? גוט איז גוט, און בעסער איז בעסער. — אגרות­-קודש ח\"ד ע' שמ. ח\"י ע' יג. חי\"ד ע' תלו."],["1412","6","שה\"ש ו, ג."],["1413","7","שם ב, טז."]]],[4301620478,"<h3>י\"ט אלול תש\"ח<sup data-n=\"1414\">1</sup></h3>\nכ\"ק אדמו\"ר שליט\"א שאל: מה למדתם?\nואמר כ\"ק אדמו\"ר שליט\"א: העיקר אינו הלימוד אלא דער אויסלערנען.\nאויף תורה שטייט<sup data-n=\"1415\">2</sup> \"כי טוב סחרה כו'\", תורה איז די בעסטע סחורה.\nוואָס האָט איר איינגעהאַנדלט? וואָס נעמט איר מיט זיך? איך האָב גערעדט מיט דעם ראש הישיבה, האָט ער מיר געזאָגט אַז איר האָט געהאָרעוועט, איר האָט געוואָלט האָרעווען, אָבער וואָס האָט איר זיך אויסגעלערנט? אַז איר קומט אַהיים, פרעגט מען וואָס האָט איהר געהאַנדעלט; זייענדיק אין דער היים דאַרפט איהר דאָרטן טאָן, טאָן מיט זיך און טאָן מיט יענעם, מאַכן יענער זאָל אויך לערנען.\nאיר דאַרפט צונויפקלייבן קליינע קינדער, און די וואָס זיינען שייך צו פאָרן אין ישיבות — דאַרף מען זעען זיי זאָלן פאָרן אין ישיבות; די וואָס זיינען דערצו ניט שייך, דאַרפן זיי דאָרטן לערנען.\nפאָרט געזונטערהייט. דער אויבער­שטער זאָל אייך געבען אַ כתיבה וחתימה טובה, אויך די עלטערן מיט זייער פאַמיליע, זיי זאָלן האָבן פון אייך נחת; און אַ שנה טובה ומתוקה.\nאיר וועט דאָך מסתמא לאָזן וויסן אַז איר וועט קומען געזונטערהייט.",[["1414","1","יחידות של האחים זאַיאָנץ (מבראַזיל)."],["1415","2","פיוט \"שישו ושמחו בשמחת תורה\". וראה גם שיחת ה' תשרי ה'שי\"ת (לקמן ע' 344)."]]],[4301620479,"<h3>כ\"ג אלול תש\"ח<sup data-n=\"1416\">1</sup></h3>\nווען מען פאָרט אַהיים פון אַ מקום תורה, דאַרף מען זען מיטבריינגען \"סחורה\"<sup data-n=\"1417\">2</sup>, מען דאַרף זען אַז די עלטערן זאָלן האָבן אַ נחת רוח.\nאיך האָב אַ באַריכט פון דיר אַז דו האָסט זיך גענומען צום לערנען, דער אויבערשטער זאָל העלפן אַז דו זאָלסט זיין אַ חסיד.",[["1416","1","יחידות של הת' חיים אהרן קופּערמאַן."],["1417","2","ראה גם יחידות י\"ט אלול שנה זו."]]],[4301620480,"<h3>ערב ר\"ה תש\"ט<sup data-n=\"1418\">1</sup></h3>\n<h4>אחרי התרת נדרים, ואחרי קריאת הפ\"נ הכלליים</h4>\nהשי\"ת ימלא משאלות לבבכם לטובה לשנה טובה ומתוקה.\nאין מאַיינע יומן שריפטין האָב איך אין אייניגע צייטען פאַרצייכינט דעם סדר זמנים — לפי שנותיי — דעם אופן החינוך ווי הוד כ\"ק אאמו\"ר הרה\"ק האָט מיך מחנך גיועהן.\nדער סדר פון ערב ר\"ה באַ הוד כ\"ק אאמו\"ר הרה\"ק איז גיועהן אַ מסודר — אַלע יאָהרין אין אַ זמן מדויק. ווי אַלע הנהגות וואָס זאַיינען מוגבלים אין אַ זמן מדויק, וואָס דאָס פלעגט אונז אַלעמען די וואָס האָבין געלייגט די ריכטיקע אויפמערקזאַמקייט אויף יעדער הנהגה אין יעדער צייט,\nבאַ מיר און באַ די מקורבים וואָס האָבין גיזונטע אויגען אויף זעהן און פאַר­שטיין וואָס מען זעהט, און האָבין גיזונטע עווערין הערען דעם אינער­ליכען מיין פון דעם קלא פנימי פון דביקות און שפיכות הנפש און געגועים עצמיים.\nדער סדר פון ערב ר\"ה באַ הוד כ\"ק אאמו\"ר הרה\"ק איז געוועהן — ווי אַלע עניני עבודה — אויפשטיין 12 אַזייגער באַנאַכט, און פלעגט לערנען זיינע שיעורים פון ערב ר\"ה, נוסף אויף די שיעורים אין נגלה, אין קבלה, חסידות, וואָס די קביעות איז געווען אַלעמאָל, הן ר\"ה, יוהכ\"פ, מועדים<sup data-n=\"1419\">2</sup>, האָט ער געהאַט די שיעורים פון ערב ר\"ה.\nמיט 52 יאָהר פריער, ערב ר\"ה האָט הוד כ\"ק אאמו\"ר הרה\"ק מיר אַריינ­גערופען צו זיך אין צימער, בין איך אין דעם זמן הקבוע פאַר מיר ביחוד [אַריינ­געגאַנגען], און לאחר וואָס ער האָט מיר געזאָגט דאָס וואָס עס איז נוגע מיר ביחוד האָט הוד כ\"ק אאמו\"ר הרה\"ק מיך מכבד גיועהן מיט אַ קירוב פנימי און האָט מיר געזאָגט:\nכ\"ק הרה\"ק הרל\"י מבאַרדיטשוב, דער באַרדיטשובער רב, האָט אין איינע פון די זמנים ערב ר\"ה פאַרנאַכט פאַר מעריב געזאָגט:\nרבש\"ע, ווי איז דאָס גישיקט אַז איך לוי יצחק מבאַרדיטשוב זאָל דאַרפען ביי דיר בעטען פאַר דיינע בני יחידים, איך בין אויך אַ טאַטע, וועל איך וואַרטען ביז וואַנען מען וועט קומען בעטען פאַר מיינע קינדער? איך ווינטש זיי כל טוב בכל עת ובכל שעה<sup data-n=\"1420\">3</sup>. אַלע אידען זיינען דאָך דיינע בני יחידים, יעדער איד איז אַ בן יחיד, דו ביזט דאָך דער אמת'ר חכם, דער אמת'ר חסדן, איז וואָס פאַר אַ פנים וועל איך האָבען און פאַר אַ שטות וועט דאָס זיין, אַז איך זאָל קומען דיר בעטען פאַר דיינע קינדער, בני יחידים, גיב זיי אַליין מידך המלאה הפתוחה והקדושה אַ השפעה מרובה אין אַלע זייערע ענינים בגשמיות וברוחניות. כן יהי רצון, אמן ואמן.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט מסיים גיועהן: אַ נשמה אין גוף, איז דאַרף זיין אין דעם סדר פון בקשה, מען בעדאַרף",[["1418","1","שיחה זו — הועתק מכי\"ק רבינו, ומהנחת אחד השומעים בתוס' הגהות מרבינו."],["1419","2","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 219."],["1420","3","ראה גם שיחת שמע\"צ ושמח\"ת תרצ\"ד סי\"ז."]]],[4301620481,"בעטען באַ דער זיסען גוטען טאַטען וואָס אין הימל, און דער טאַטע גיט בני חייא מזונא אין אַ אופן פון רויחא.\nדער אויבערשטער זאָל ממלא זיין אַלע אונזערע, אייערע און אַלע אידענ'ס בקשות, דאָס וואָס מיר אַלע און כל ישראל בעטען. און השי\"ת זאָל אונז און כל ישראל געבין שכל וויסען וואָס צו בעטען, זאָל געבען אונז וכלל ישראל אַ שנה טובה ומתוקה בגשמיות וברוחניות.\nאח\"כ בירך הרש\"ל בשם כל אנ\"ש את כ\"ק אדמו\"ר שליט\"א וענה:\nאַה, שוין צייט זוכה צו זיין צו ביאת המשיח, עס איז שוין זייער פינסטער, שוין צייט עס זאָל ווערען אויף אַ אמת ליכטיג."],[4301620482,"<h3>קודם שנכנסו המסובין בליל א' [דר\"ה תש\"ט]<sup data-n=\"1421\">1</sup></h3>\nבליל א' — וכן ביום א' — איז דאָ אַ זהירות אַף דבור<sup data-n=\"1422\">2</sup>. קרה והצ\"צ דבר בליל א' דר\"ה אַף מחליש זיין ניקאָלאַיען<sup data-n=\"1423\">3</sup>. ווען אונזערע רייד וואָלטען געהאַט אַ פעולה וואָלטען געדאַרפט רעדען אַ גאַנצע נאַכט. — (על השאלה: אודות מי? ענה:) ניט אַף אידען. באַ אידען, זיינע ז' תחתונות איז דאָך שטות. ג\"ר איז חכמה. ז\"ת — שטות.",[["1421","1","הועתק מכי\"ק כ\"ק אדמו\"ר נשיא דורנו."],["1422","2","ראה לעיל ע' 159. וש\"נ."],["1423","3","ראה גם רשימת רבינו בספר השיחות תורת שלום ע' 80­79. ע' 260 (בהוצאת קה\"ת, תשנ\"ג). ספר השיחות תרפ\"ח­תרצ\"א ע' 83."]]],[4301620483,"<h3>קודם שנכנסו המסובין בליל ב' [דר\"ה תש\"ט]<sup data-n=\"1424\">1</sup></h3>\nליובאַוויטש איז געווען מסוגל צו אַזוינע טעג. די גאַנצע שטעטעל געווען נאָר דאָס.\nהנני זוכר<sup data-n=\"1425\">2</sup> ויום א' דר\"ה הי' התוקע הרז\"א (בעל תוקע נפלא, מריע מ\"ב טרומיטין בתרועה<sup data-n=\"1426\">3</sup>), ויום ב' — זלמנ­סאָן<sup data-n=\"1427\">4</sup>. אח\"כ, כמדומה משנת תרנ\"ד ביום ב' הי' אדנ\"ע אומר הפסוקים ומקריא והתוקע הי' ר' זלמן אָרשער<sup data-n=\"1428\">5</sup>.\nראיתי שופר בליוב'<sup data-n=\"1429\">6</sup> שאמרו עליו שהי' של המהר\"ל מפראָג ונסדק וחתכו חלק גדול ממנו<sup data-n=\"1430\">7</sup>. וכשראיתיו הי' אורכו ארשין<sup data-n=\"1431\">8</sup> לערך<sup data-n=\"1432\">9</sup>.",[["1424","1","הועתק מכי\"ק כ\"ק אדמו\"ר נשיא דורנו."],["1425","2","ראה גם רשימת היומן — תשרי תרצ\"ג (\"רשימות\" חוברת יד ע' 5): \"זוכר אני ואדנ\"ע לא תקע, וביום א' תקע רז\"א, ביום ב' חיים זלמנזאָהן\". ובספר השיחות תש\"ה ע' 10: \"אין יאָר תרמ\"ח דעם צווייטן טאָג ר\"ה האָט הוד כ\"ק אאמו\"ר הרה\"ק מסדר געווען די תקיעות. דעם ערשטן טאָג האָט מסדר געווען די תקיעות דודי הרז\"א. דער בעל תוקע איז געווען ר' חיים\"."],["1426","3","ראה — בנוגע אדמו\"ר מהר\"ש — ספר השיחות תרפ\"ח­תרצ\"א ע' 144. תש\"א ע' 28. תש\"ד ע' 136. רשימת היומן — יום ב' דר\"ה תרצ\"ה (\"רשימות\" חוברת קיג ע' 14)."],["1427","4","ר' חיים בן הרלוי\"צ זלמנזאָהן חתן אדמו\"ר הצ\"צ (ראה לעיל ע' 63)."],["1428","5","ראה אודותו — ספר השיחות תש\"ד ע' 60 ואילך."],["1429","6","בליובאַוויטש."],["1430","7","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 253. תש\"ה ע' 11. רשימת היומן שבהערה 3."],["1431","8","\"ארשין\" הוא לערך 71 סנטימטר."],["1432","9","ברשימה שבהערה 3: \"אני ראיתי כשנחתך קצתו (מפני שנסדק), והי' איזה וערשאק פחות מ­1 ארשין\" (היינו קרוב למטר אחד)."]]],[4301620484,"<h3>ליל ב' דר\"ה תש\"ט בסעודה<sup data-n=\"1433\">1</sup></h3>\nא. די עבודה אין בית המקדש ביום כיפורים איז גיועהן נאָר דורך דעם כהן גדול אַליין נאָך אַ געויסער רגילות הכנה וואָס עס איז גיועהן מסודר פון בית דין.\nדער זמן פון התחלת העבודה אין בית המקדש ביום כיפורים איז גיועהן מסודר אַז אַלע זאַכין איז גיטאָהן גיואָרין נאָר דורך דעם כהן גדול על פי בית דין דורך אַ ספּעציעלע ממונה וואָס ער האָט גיהאַט דעם טיטול סגן כהן גדול<sup data-n=\"1434\">2</sup>.\nצו דעם זמן פון התחלת העבודה אין בית המקדש פלעגט דער סגן כהן גדול הייסען אַז מען זאָהל גיין אויף דעם בעשטימטען הויכע אָרט<sup data-n=\"1435\">3</sup> וואָס איז גיועהן אין בית המקדש זעהן צי עס איז געקומען די בעשטימטע צייט וואָס מען בעדאַרף אָנהויבין די עבודת הקרבנות. פלעגט דער ממונה זאָגין<sup data-n=\"1436\">4</sup>: צאו וראו אם הגיע זמן השחיטה — גייט אויף דעם ספּעציעלען הויכע אָרט וואָס עס איז גיועהן אין מקדש — אם הגיע זמן השחיטה — צי עס איז שיים צייט וואָס מען דאַרף בריינגען דעם קרבן תמיד — די וואָס זיינען גישטאַנען נידעריקער פלעגין פרעגין באַ דעם וואָס איז געשטאַנען אין דער הויך, אם האיר פני כל המזרח עד שבחברון — צי עס איז בעלויכטין דער מזרח ביז חברון, ווייל צוליב דערמאָהנען זכות אבות דערמאָנט מען חברון<sup data-n=\"1437\">5</sup>.\nפון דעם סדר עבודה פאַרשטייען מיר צוויי ענינים א) אַז זכות אבות איז אַ הקדמה און התחלה אין עבודה, ב) און בכדי מען זאָהל ניט האָבען קיין טעות אין עניני עבודה בעדאַרפמען בכל עת ובכל זמן בעטען רחמי שמים אַז הוד כ\"ק אבותנו רבותנו הקדושים וואָס זאַיינען אין היכלי שמים<sup data-n=\"1438\">6</sup> זאָהלין מעורר זיין רחמי שמים פאַר אונז אַלע זייערע מקושרים און זייערע בני בית זאָהלין זיין גיזונד און האָבין פרנסה בהרחבה, זיי זאָהלין בהרחבה ובהצלחה דורכפירין די שליחות פון ירידת נשמתם למטה אין גוף.\nב. הגם אַז במשך השנים האָט מען געויס מעהרער מאָהל גירעהט און דער­ציילט, און אין געויסע ענינים מבאר גיועהן די מנהגי הוד כ\"ק אאמו\"ר הרה\"ק אין אַלע מועדי השנה, דאָך איז לבד דעם זכות און ענג ותועלת פרטי וואָס איך האָב אין דעם דערמאָהנען דעם סדר זמנים, איז די הזכרות און דער לייענען וואָס מען לייענט די אַלע שריפטען אין יעדער אָרט ברבים אָדער ביחידות אַ געויסע הזכרה — דערמאָנונג — וואָס איז מגיע אין די היכלות הקדש פון הוד כ\"ק אבותינו רבותינו הקדושים, און עס בריינגט, בעזרתו יתברך אַ שפע ברכה בגשמיות וברוחניות.\nג. דעם ערשטין מעת לעת ר\"ה פון נאָך ליכט בענטשין ביז נאָך דעם ערשטין מאמר חסידות וואָס הוד כ\"ק אאמו\"ר הרה\"ק זאָגט דעם ערשטין טאָג ר\"ה נאָך תפלת ערבית פון דעם צווייטין נאַכט<sup data-n=\"1439\">7</sup>,",[["1433","1","שיחה זו — הועתק מכי\"ק רבינו, ומהנחת אחד השומעים בתוס' הגהות מרבינו ומכ\"ק אדמו\"ר נשיא דורנו."],["1434","2","ראה משנה יומא כח, א וברש\"י שם — ד\"ה אמר להם הממונה."],["1435","3","ראה משנה יומא שם וברש\"י ד\"ה צאו וראו."],["1436","4","משנה יומא שם."],["1437","5","ירושלמי יומא פ\"ג ה\"א."],["1438","6","ראה גם ספר השיחות תש\"ה ע' 4."],["1439","7","ראה גם שיחת ליל ב' דר\"ה תש\"ח (לעיל ע' 160)."]]],[4301620485,"האָט הוד כ\"ק אאמו\"ר הרה\"ק גיועהן נזהר עפּעס ריידין אַ חוץ גאָר דריגענדע זאַכין<sup data-n=\"1440\">8</sup>, אויך דאָס פלעגט הוד כ\"ק אאמו\"ר זאָגין זייער קורץ און בשפה רכה.\nווי אין דער רוב מצות איז פאַראַן עשה ולא תעשה, איז באַ הוד כ\"ק אאמו\"ר הרה\"ק גיועהן אין דעם ענין פון התחלת הדיבור אין דער התחלה פון שנה. די עשה איז גיוען אָנהייבען דעם דיבור פון יאָהר מיט דעם דיבור פון חסידות<sup data-n=\"1439\">7</sup>, און דער לא תעשה איז די זהירות אין גאָרנישט ריידין אין ענינים וואָס זיינען בלתי נצרכים ביותר.\nד. די פתיחת הדיבור אין אַ חב\"ד חסידות'ר התועדות פאַרבריינגען בע­דאַרף זיין אין און מיט אַ חב\"ד חסידות תורה און עבודה וואָרט.\nדער נושא ותוכן פון דעם ריידין דעם עבודה וואָרט, ניט נאָהר סתם גירעהט, אָדער געוואונשען זיך. עס איז דאָ אַ שיטה פון רעדען, צי יע טאָן אָדער ניט טאָן, מ'רעדט. עס איז דאָ אַ שיטה פון ווינשען זיך, צי ער איז יע ווערט אָדער ניט ווערט, — ער איז דאָך דאָ און די זאַך איז אויך דאָ, ווינשט ער זיך. וואָס באמת דאַרף זיין אַזוי, ווייל דער וועל פון אַ אידען נעמט זיך פון נשמה און נשמה קען צוקומען צו די העכסטע מדריגות. דער רבי — אדמו\"ר הזקן — האָט אויפגעטאָן, אַז עס דאַרף זיין אַ כלי, וואָס אַ כלי האָט אַ תוך<sup data-n=\"1442\">9</sup>. אַ גרויסע שיסעל איז ניט די גרויסקייט אין די חיצוניות הכלי, נאָר אין דעם תוך, — אַ גרייסער תוך.\nאַה, אין חב\"ד איז יעדער ענין מיט אַ מדידה עצמית און מדידה פנימית.\nדער צירוף פון אַלטען רבין און דער בעש\"ט איז, — דער בעש\"ט האָט אויפגעטאָן, אַז יעדער דבר פעוט און יעדער דבר קטן איז דאָס אַ הוראה אויף אלקות, דער אַלטער רבי האָט אַריינגי­שטעלט דורך תורת חסידות חב\"ד ווי יעדער תנועה קטנה אין און דורך עבודת החסידות איז אַ שליבה אין דעם סולם העלי' עד רום המעלות.\nה. יחזקאל הנביא איז גיועהן אַ גלות נביא, ווי חז\"ל זאָגין<sup data-n=\"1443\">10</sup> אויף דעם פסוק הי'ה הי' דבר ה' וגו'<sup data-n=\"1444\">11</sup>. יחזקאל האָט מגלה און ממשיך [גיועהן] גילוי אלקות אין גלות, ער האָט די גלות פאַרשקלאַפטע אונד עניות אויסגעמאַטערטע ערקלערט די טיפסטע עניני אלקות פון מעשה מרכבה.\nו. דער טאַטע, איז אונזער חסידי חב\"ד'ישר יחזקאל הנביא. מיט זאיינע מאמרי חסידות איז ער מגלה מיט הש­כלה ביאורים מעשה מרכבה אונד מעשה בראשית, מיט די קונטרסי עבודה און שיחות ערמעגליכט ער אַז יעדער איינער ווי קליין אין ידיעה והשגה ער זאָל ניט זיין, זאָהל ער לפי ערכו קאָהנען שטאַיי­גין אויף די שליבות פון דעם סולם העלי'.\nז. עס איז אַ סדר מסודר באַ נשיאי חב\"ד אין סדר הנהגה פון ערב ר\"ה, אַז",[["1440","8","ראה ספר השיחות תש\"ד ע' 3 ע\"ד הנהגת כ\"ק אדמו\"ר מהורש\"ב נ\"ע: \"פון שנת תרל\"ה האָט ער אויף זיך מקבל געווען ניט צו רעדען דעם ערשטען טאָג ר\"ה ביז נאָכ'ן מאמר — שהי' בליל ב' דר\"ה — דאָס איז געווען אַ ענין פרטי, נאָכדעם אַז ער האָט אויף זיך מקבל געווען די נשיאות פלעגט ער זיך אויך אַזוי פירען. דעם צווייטן טאָג ר\"ה פלעגט ער שוין יאָ רעדן, אָבער זייער ווייניק, עס איז נאָר געווען אַראָפּ דער ניט\". וראה גם שיחת ליל א' דר\"ה תש\"ח (לעיל ע' 159)."],["1439","7","ראה גם שיחת ליל ב' דר\"ה תש\"ח (לעיל ע' 160)."],["1442","9","ראה שיחת יום ב' דר\"ה שנה זו (לקמן ע' 276)."],["1443","10","ראה מו\"ק כה, א."],["1444","11","יחזקאל א, ג."]]],[4301620486,"נאָך דער טיף האַרציקע יאָהרליכע גיזעגינס מנחה זאָגט מען ביז זמן פון תפלת ערבית מזמורי תהלים, און די צוויי מעת לעת איז מען מרבה אין אמירת תהלים<sup data-n=\"1445\">12</sup>.\nח. אין יאָהר תרמ\"ט ר\"ה, האָט דער טאַטע מיר געהייסען זאָגען תהלים. דער טאַטע איז ניט געווען צופרידען פון מיין עברי זאָגען<sup data-n=\"1446\">13</sup>, דאָס איז געווען מצד מיין חזרת משניות בע\"פ שנעל, פלעג איך מבליע זיין אַסך הברות. האָט דער טאַטע מיר דאַמאָלסט געזאָגט:\nפון יעדער תורה אָדער תפלה וואָרט וואָס אַ איד זאָגט ווערט באַשאַפן אַ מלאך<sup data-n=\"1447\">14</sup>. עס זיינען פאַראַן שלום עליכם מלאכים, וואָס ווערען באַשאַפן פון שלום עליכם וואָס מען זאָגט פרייטאָג צו­נאַכטס, עס זיינען פאַראַן שחרית מל­אכים, מנחה מלאכים, מעריב מלאכים, און מלאכים וואָס ווערען באַשאַפן פון קר\"ש פאָרן שלאָף. פון יעדער תפלה ווערט אַ גאַנצע מחנה מלאכים, וואָס יעדע מחנה קלייבט אויס אַ שליח וועמען מען שיקט אַראָפּ צו היטען דעם מענטשן וואו ער גייט און שטייט.\nאין סדר המלוכה וואָס דער עיקר אונד דער זעלבשטענדיקער אונד ערשטער פיהרער איז דער קיסר, און דער קיסר איז מסדר אַלע מלוכה לאַייט פון דעם ערשטין מיניסט[ע]ר ביז דעם סאטסקע.\nדאָ אין ליובאַוויטש — זאָגט מיר דער טאַטע — איז דער גאַנצע פראייטעלס­טער — מלוכה­פירער דער פריסטאָוו, אָבער דער אמת'ר פאַר ועמען אַלע מענטשין פון דער גאַנצער מדינה האָבין מורא איז דער קיסר, און ניכר איז זאַיין שטאַרקייט אַלעס דעם קיסר'ס אַ שליח איז די קליידונג זאיינע וואָס דאָס באַ­ווייסט אַז ער דורך זיין שליחות בעזיצט ער דעם קיסר'ס קראַפט.\nיעדער איינער פון די אַלע מלוכה פקידים טראָגט אַ צייכענונג פון דעם מלך וואָס עס בעצייכנט זאַיין<sup data-n=\"1448\">15</sup> וואָס ער פאַרנעמט אין דער מלוכה. באַ דעם העכערען איז דאָס אַ גילדענע, באַ די נידעריגערע איז דאָס אַ זילבערנע, מעשענע, בלייענע, ביז באַ דעם סאטסקער איז דאָס אַ בלעכענע, אָבער אַלץ קומט פון דער מלוכה.\nאידין זיינען בני מלכים<sup data-n=\"1449\">16</sup>, גיט מען יעדען שלוחים פון מלך צו היטען איהם, איינער גיט מען העכערע שלוחים, דעם אַנדערען גיט מען נידעריגערע שלוחים, אָבער זיי זיינען אַלע פון מלך. היינט שטעל זיך פאָר: אפי' אַז די שלוחים פון מלוכה פיהרען אַ מענטשן אין \"פריזאָן\"<sup data-n=\"1450\">17</sup> דאַרף מען דאָך אויך האָבען פאַר זיי דרך ארץ, אַ כל שכן אַז די שלוחים זיינען געשיקט געוואָרען אויף אַ שמירה, צו היטען דעם מענטשן. היינט וואָס פאַר אַ פנים וועט ער האָבען אַז ער וועט פּאַטשען די שלוחים. אַז מען היפט איבער אַ וואָרט גיט מען אַ פּאַטש דעם מלאך, אַז מען איז מבליע הברות גיט מען אַ שאַר דעם מלאך.\nדעם טאַטין'ס מוסר רייד, האָבין מיך זייער דערנומען. אַז איך בין גיקומען צו זיך אין צימער, האָב איך שטאַרק גיוויינט, ניט גיקאָנט זעך בערואיקין.",[["1445","12","ראה סה\"מ תרצ\"ז ע' 310. אגרות­-קודש ח\"א ע' תכה. ח\"ד ע' קלב. ע' תטז."],["1446","13","ראה גם אגרות­-קודש ח\"י ע' תה."],["1447","14","חדא\"ג מהרש\"א מכות י, ב. וראה אבות פ\"ד מי\"א ובמפרשים שם. וראה גם שיחת יום אחש\"פ שנה זו (לקמן ע' 323). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 308."],["1448","15","כ\"ה בכי\"ק. ואוצ\"ל: זיין אַמט."],["1449","16","שבת סז, א."],["1450","17","בית האסורים."]]],[4301620487,"אין דעם איז אַריינגעקומען די מאַמע, אַ בן יחיד בין איך דאָך געווען, איז זי אַריינגעגאַנגען צום טאַטען און גע­פרעגט, וואָס האָט ער מיר אַזוינס גע­זאָגט, וואָס איך קען זיך ניט בערואיקין.\nהאָט דער טאַטע גיזאָגט:\nנשקשה, די טרערען וועלען אַריינ­געהן אין אַ אינעווייניג און בלייבען אויף שטענדיג.\n(וסיים כ\"ק אדמו\"ר שליט\"א:)\nאָט דאָס איז הדרכה, אָט דאָס איז חסידישער חינוך, אָפּגעבען זיך מיט אַ קטן שבקטנים ווי מיט אַ גדול שבגדולים, אָט דאָס איז אהבת האָב אל הבן, אַריינ­געבען כחות אין אַ נער קטן אַז ער זאָל דאָס האָבען אויך צו זיבעציג יאָהר.\nמהנהגות בית רבי<sup data-n=\"1451\">18</sup>\nא. בליל א' כשנכנסו הקרואים לה­שולחן, אמר כ\"ק אדמו\"ר שליט\"א לכל אחד: גוט יו\"ט, לשנה טובה תכתב ותחתם.\nב. אכילת התפוח לאחר אכילת המוציא<sup data-n=\"1452\">19</sup>.\nג. אכילת פרי של \"שהחינו\" קודם נט\"י לסעודה. וכ\"ק אד\"ש בירך ע\"ז מיד — קודם נט\"י — ברכה מעין שלש<sup data-n=\"1453\">20</sup>.\nד. בירך — ועל הכוס<sup data-n=\"1453\">20</sup> — בסעודות ליל א' דר\"ה ויום ב' דר\"ה.\nה. בשני הימים — כ\"ק אד\"ש מפטיר, ואמירת למנצח, מן המיצר, הפסוקים, ברכות (מקריא רק ע\"י הוראה באצבע ולא בדיבור<sup data-n=\"1455\">21</sup>) ושלשת הפסוקים שאחרי התקיעות. — פתיחת הסידור לתקיעות ג\"כ תחת הטלית.",[["1451","18","עם הוספות בכי\"ק כ\"ק אדמו\"ר נשיא דורנו."],["1452","19","ראה לעיל ע' 158. וש\"נ."],["1453","20","ראה לעיל ע' 159. וש\"נ."],["1453","20","ראה לעיל ע' 159. וש\"נ."],["1455","21","ראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 139. וש\"נ. תש\"ד ע' 3. תש\"ה ע' 3."]]],[4301620488,"<h3>יום ב' דר\"ה תש\"ט בסעודה<sup data-n=\"1456\">1</sup></h3>\nא. אין חסידות זיינען פאַראַן ד' דרגות: תורת החסידות, עבודת (מדות) החסידות, דרכי החסידים, און ניגוני חסידים. בתורת וידיעת החסידות אין החסרון כ\"כ אם אין מבין הענין היטב היום יש לקוות שירחם השי\"ת ויבין הענין למחר, וכן הוא בענין המדות; אבל דרכי החסידים חסרים עתה, מען נעמט אַלץ חיצוניות. מען האָט געמאַכט אַ פוילישן חב\"ד; מען שטופּט זיך, מען רייסט זיך, און מען מיינט אַז דאָס איז חסידות. באמת — מען דאַרף דאָס ניט אַזויפיל מפרסם זיין — איז די שולד מצד המשפיעים, וואָס מען גיט זיך ניט אָפּ צו לערנען די יונגעלייט די דרכי החסידים; וואָס איז די וואונדער אויף זיי, זיי האָבן דאָך ניט געזען ווי עס דאַרף זיין. אַמאָ­ליקע זקני החסידים פלעגן האָרעווען אויף יונגעלייט מער ווי זיי האָבן געהאָ­רעוועט אויף חסידות.\nב. דער אַלטער רבי האָט אויפגעטאָן אַז עס דאַרף זיין כלים. דער עיקר פון אַ כלי איז דער תוך, ניט דער אַרום<sup data-n=\"1457\">2</sup>. די דפנות דאַרפן זיין דינע, זיי דאַרפן זיין שטאַרקע אָבער דינע דפנות.",[["1456","1","ברשימת השיחה כותב המניח: \"רשימה קצרה, רק נקודות, כי לא זכינו לשמוע היטב\", \"הענינים המובאים כאן אינם על הסדר שאמרם כ\"ק אד\"ש ויש בהם מוקדם ומאוחר\"."],["1457","2","ראה שיחת ליל ב' דר\"ה שנה זו (לעיל ע' 274)."]]],[4301620489,"ג. דעם ליובאַוויטש שבליובאַוויטש האָט מען געבראַכט אַהער.\nד. (איזה מהמסובים התחילו להזכיר על ענינים וסדרים שונים שהיו בליובאַ­וויטש, והזכירו משנת תרס\"ו שמח\"ת, שכ\"ק אדמו\"ר נ\"ע אמר אז<sup data-n=\"1458\">3</sup> המאמר ד\"ה כי נער ישראל ואוהבהו<sup data-n=\"1459\">4</sup>. ואמר כ\"ק אדמו\"ר שליט\"א:) דער טאַטע האָט דאַ­מאָלסט געזאָגט פאַרען מאמר: איך וועל זאָגן אַ ענין וואָס האָט זיך באַ מיר יעצט אָפּגעלייגט<sup data-n=\"1460\">5</sup>, ובחשאי אמר: וואָס נשמה האָט גענומען פון חי'. ובהמאמר פירש: נער ישראל ואוהבהו<sup data-n=\"1461\">6</sup>, ואהבהו וואָס איך — הקב\"ה — האָב אַריינגעגעבען אַ אהבה אין ישראל.\nה. ברור הדבר, אַז יעדערער וואָס דערמאָנט זיך דעם ציור פון ליובאַוויטש ווי דער רבי האָט געזאָגט חסידות, און איז זיך מצייר ווי דער רבי האָט דאַ­מאָלסט אויסגעזען, און ווי דער חסיד האָט געהערט און ווי ער האָט דאַן אויסגעזען, און ווי עס האָט אויסגעזען בשעת מען האָט גע'חזר'ט דעם רבי'נס אַ מאמר אָדער אַ שיחה — איז ברור הדבר אַז עס וועט באַ אים נתגלה ווערן דער פנימיות הנשמה, סיי ביי דעם דער­ציילער און סיי ביי דעם הערער.\nו. הרה\"ח ר' הלל פּאַריטשער<sup data-n=\"1462\">7</sup> האָט זוכה געווען צו אַ כיבוד פנימי פון די רביים. בכלל איז אויף יעדער פון די חסידים הגדולים געווען אַ בעזונדער טיטול, אָבער פאַר ר' הלל'ן איז באַ די רביים געווען אַ בעזונדער הדרת. — עס איז שווער צו זאָגן דעם וואָרט \"הדרת הכבוד\", ווייל ר' הלל האָט געהאָרעוועט אויף אנשים פשוטים. ער האָט מגלה געווען די יחידה שבנפש באַ די אנשים פשוטים.\nז. עס איז דאָ גאָר אַן אַלטער וואָרט: עס זיינען פאַראַן דריי העדרים: העדר העבודה, העדר הידיעה און העדר ההשגה. באמת איז דאָס אַלץ תלוי אין העדר העבודה, און אַז עס איז דאָ עבודה, איז דאַמאָלסט פאַראַן ידיעה, און די ידיעה קומט דאַן אַראָפּ אין השגה.",[["1458","3","ביום שמח\"ת תרס\"ו — בעת הסעודה בבית הרבנית רבקה."],["1459","4","נדפס בהוספות להמשך תרס\"ו (ע' תקעד ואילך — בהוצאת תנש\"א ושלאח\"ז)."],["1460","5","ראה גם שיחת ש\"פ בראשית תשי\"ב. יום שמחת תורה תשט\"ז."],["1461","6","הושע יא, א."],["1462","7","ראה אודותו לעיל ע' 29. וש\"נ."]]],[4301620490,"<h3>ד' תשרי תש\"ט</h3>\nגעהאָפט האָט מען, זיין אין ארץ ישראל די ימים טובים, ווייל די תקוה פון יעדן אידן איז דאָך זיין אין ארץ ישראל, אין דער אמת'ע ארץ ישראל.\nאַלע אידן זיינען אמת'ע.\nדער ראָגאַטשאָווער גאון<sup data-n=\"1463\">1</sup> האָט גע­זאָגט: קיינער האָט באַ אונז ניט צוגענו­מען ארץ ישראל, און קיינער וועט אונז ניט געבן ארץ ישראל<sup data-n=\"1464\">2</sup>.\nארץ ישראל איז אונזערע, קיינער האָט באַ אונז זי קיינמאָל ניט צוגענומען. זי איז ארץ ישראל, נאָר דער טאַטע האָט אָפּגעשמיסן די קינדער. און אַז דער",[["1463","1","ראה אודותו — ספר השיחות תרפ\"ה ע' 70 הערה 7."],["1464","2","להעיר מספר השיחות תרפ\"ז ע' 169."]]],[4301620491,"קינד דערפילט דעם שמיץ און זאָגט: טאַטע מיר ווילן טאָן וואָס דו ווילסט נאָר עס איז פאַראַן דער יעניגער וואָס דערלאָזט ניט, טאָ נעם עם צו, וועסטו זעהן וואָס פאַר אַ גוטע זיסע קינדער מיר זיינען.\nהשי\"ת זאָל געבן אַלעמען אַ חתימה טובה, אַז מען זאָל קומען אין ארץ ישראל געזונטערהייט, מיט משיח'ן צוזאַמען.\nעל הודעת מר קרעמער אודות אסיפתם ע\"ד התועדות וביקש ברכה ע\"ז — היתה המענה של כ\"ק אדמו\"ר שליט\"א:\nאַז אידן טוען אין אַ ענין פון צדקה און בפרט אויף אַ ענין פון תורה, ובפרטי פרטיות אַ רבים, העלפט דער אויבער­שטער.\nהשי\"ת זאָל געבן יעדן איינעם וב\"ב בפרט אַ חתימה און אַ גמר טוב, און אַ שנה טובה מתוקה, אַ אמת'ע זיסע. און מען זאָל זיך זעהן אין דערהיים."],[4301620492,"<h3>ערב יוהכ\"פ אחר כיסוי הדם תש\"ט<sup data-n=\"1465\">1</sup></h3>\n(אמר כ\"ק אדמו\"ר:) דער זמן פון שחיטת הכפרות איז ווען עס ווערט טאָג<sup data-n=\"1466\">2</sup>. היינו, אַז די פינסטערניש גייט אַוועק און עס הויבט אָן ווערען ליכטיג. די פינסטערניש איז דאָך שוין אַריינ­געגעסען זיך אידן אין די ביינער, וואָס פאַרטאָג ווערט שטאַרק פינסטער<sup data-n=\"1467\">3</sup>, וואָ­רים אפילו אין אַ ליכטיגע נאַכט ווערט אויך פאַרטאָג פינסטער. וואָס אַ ליכטיגע נאַכט איז אויך נאַכט. דער אויבערשטער זאָל העלפען אַז ס'זאָל ווערען אור (והדגיש תיבת אור) באמת.",[["1465","1","נדפס בסה\"מ תש\"ט ע' לח. ושם ע' כו: השיחה היא מערב יוהכ\"פ שנת תש\"ט בחדרו, אחרי כיסוי הדם של ה\"כפרה\"."],["1466","2","סידור אדה\"ז — סדר כפרות."],["1467","3","ראה מדרש תהלים כב, א [ד]. מאמרי אדה\"ז אתהלך לאזניא ס\"ע קג. אוה\"ת במדבר ע' מד. שיחת שמע\"צ ושמח\"ת תרצ\"ד סי\"ב."]]],[4301620493,"<h3>ליל א' דחג הסוכות תש\"ט בסעודה</h3>\nא. כ\"ק<sup data-n=\"1468\">1</sup> אדמו\"ר שליט\"א פנה לה­רמ\"ד, ובקשו לנגן, ואמר הנ\"ל: איך קען נאָר פרייליכע ניגונים, עס איז דאָך היינט זמן שמחתינו. ואמר כ\"ק אדמו\"ר שליט\"א: פון דעם ענן הקטורת פון יום כפור ווערט סוכות שמחה<sup data-n=\"1469\">2</sup>.\nב. עס<sup data-n=\"1470\">3</sup> זיינען דאָ פערשידענע ניגונים, פאַראַן נאַרישע ניגונים, עד\"מ ער קלאַפט מיט די פיס און פּאַטשט מיט די הענט, אָבער עס איז גאָר ניט, ס'איז אָהן אַ תוך, און עס איז פאַראַן פנימיות­דיגע ניגונים, ע\"ד ר\"מ הוה מנגן בכל מיני ניגונא<sup data-n=\"1471\">4</sup>.",[["1468","1","בהנחה אחרת: ההכנות להסעודה התארכו, ואמר כ\"ק אדמו\"ר שליט\"א: ס'איז אַ שאָד די צייט, מען דאַרף זאָגן אַ ניגון."],["1469","2","ראה לעיל ע' 169."],["1470","3","בהנחה אחרת: הרמ\"ד שר ובאמצע פסק. ואמר כ\"ק אדמו\"ר שליט\"א: מען דאַרף אויס­שווענקען דעם פידעל."],["1471","4","ראה רע\"מ בזוהר ח\"ב קיד, סע\"ב. ח\"ג קט, א. מאמרי אדה\"ז: תקס\"ב ח\"ב ע' שמב; מארז\"ל ע' נב. מאמרי אדמו\"ר האמצעי: שערי תשובה ח\"א לה, ג. ח\"ב פח, ד; דרושי חתונה ח\"א ע' רלז; קונטרסים ע' סו."]]],[4301620494,"עס איז דאָ שמחת הקול, שמחת הלב, צעקת הקול, און צעקת הלב. שמחת הקול איז חיצוניות, כנ\"ל, די איבעריגע דריי דרגות, דאָס איז די עבודה פון ר\"ה יוכ\"פ און סוכות. סוכות איז שמחת הלב, עס קען זיין אַז אין שמחת הלב זאָל אויך זיין דער צעקת הלב, אָבער דערצו דאַרף מען לערנען אַ פולע חסידות<sup data-n=\"1472\">5</sup>.\nג. (א' מהמסובים תיקן את הקערה שהעמידו לפני כ\"ק אד\"ש, ושאל אם הוא רוצה כך<sup data-n=\"1473\">6</sup>, וענה לו כ\"ק אדמו\"ר שליט\"א:) וואָס איז שייך אַ וועל אין אַ ענין פון חיצוניות?\nד. אין יאָהר תרנ\"ט זיצענדיק די ערשטע נאַכט אין סוכה האָט כ\"ק אאמו\"ר גערעדט אַ שמועס באריכות, וואָס דער קוטב הענין איז געווען אַז עס איז פאַראַן עבודת המוח און עבודת המדות, מדות אָהן מוחין איז גאָר ניט, און מוחין אָהן מדות איז גאָר ניט. אין עבודת המוח איז אויך דאָ מדות נאָר דער הפרש איז צי עילאה גבר אָדער תתאה גבר.\nדער רבי — כ\"ק אדמו\"ר הזקן — איז געווען עבודת המוח, דער בערדיטשע­ווער רב איז געווען עבודת המדות. ביידע זיינען געווען בעלי השכלה און ביידע זיינען געווען בעלי מדות, נאָר דער הפרש איז געווען צי תתאה גבר אָדער עילאה גבר.\nעס איז ידוע אַז דער באַרדיטשעווער פלעגט די ערשטע נאַכט סוכות וואַרטען אַ גאַנצע נאַכט עס זאָל שוין ווערן טאָג — שיוכל לברך על הלולב — און פלעגט אַרויס שיקען אַלע וויילע דעם משרת זעהן אויב עס איז שוין טאָג. דער אַלטער רבי פלעגט ניט וואַרטען אויף טאָג, נאָר אַז עס איז שוין געוואָרען טאָג האָט ער דערהערט.. .\n(וסיים כ\"ק אדמו\"ר שליט\"א:) אַה, דער עיקר החסידות איז לעבן מיט אַ וואָרט. איך דערמאָן זיך ווי מיר האָבען געהערט דעם וואָרט פון טאַטען.\nעס איז דאָך ידוע דער סיפור<sup data-n=\"1474\">7</sup>, אַז ביי דעם בעש\"ט — בעת תפלת קבלת שבת — פלעגען זיך די ציגען אויפשטעלען \"דובאם\" (שהגביהו רגליהם שמלפנים).\nדאָס איז אַ ציור, ווי מיר האָבען דעמאָלסט געהערט דעם וואָרט פון טאַטען, טאַקע ציגען אָבער אויפגע­הויבען. כי, הלא בעזים יש פנים ואחור אלא כשהולכים כרגיל אז הכל בשוה, משא\"כ כשמגביהים את רגליהם שלפני­הם, אז ניכר הפנים שבהם.",[["1472","5","בהנחה אחרת: ס'איז דאָ עבודת החסידות און ס'איז דאָ השכלת החסידות. עבודת החסידות איז אַז מען דאַרף לעבן מיט אַ וואָרט, און דער גאַנצער ענין פון השכלת החסידות איז אַריינ­צוגעבן אַ הטעמה — אַ געשמאַק — אין מדות."],["1473","6","בהנחה אחרת: בעת שהביאו הדגים הי' קערה בתוך קערה שלא ישפך, ושאל א' אם כ\"ק אדמו\"ר חפץ שיקחו קערה אחת."],["1474","7","ראה שיחת שמח\"ת שנה זו (לקמן ע' 284). ד\"ה הנה ישכיל עבדי תשל\"ב (סה\"מ תשל\"ב ע' 154). ועוד."]]],[4301620495,"<h3>יום שבת קודש, חול המועד סוכות תש\"ט בסעודה</h3>\nא. אין יעדער זאַך איז דאָ אַ שיעור — אַ מדה, שיעור ומספר. אָבער אין שמחת יו\"ט איז ניטאָ קיין שיעור, וויילע שמחת יו\"ט איז למעלה מן השיעור. אפילו אין קרבנות איז דאָ אַ מספר. אָבער אין שלמים — שלמי שמחה, איז ניטאָ קיין שיעור.\nב. (אחד מהמסובים לקח כוס וביקש את חבירו שיצוק לתוכו יין מן הבקבוק לאמר לחיים, ואמר כ\"ק אדמו\"ר שליט\"א:)\nאַז מען דאַרף האָבען כלים פרטיים, רעדט זיך אין חסידות, דאָס דאַרף מען האָבען. אָבער בעטען יענעם אַריינגיסען, וועגען דעם איז ניטאָ. אַריינגיסען אין די כלי דאַרף מען אַליין. אויב מען קען ניט אַליין אַריינגיסען, דאַרף מען אונטער­שטעלען די כלי לקבלה אויף אַ אָרט וואו עס גיסט זיך.\nג. דער היינטיגער מאמר — ד\"ה ושאבתם מים בששון<sup data-n=\"1475\">1</sup> — איז משמח און צוברעכט. ער איז משמח — וואָס חסידות רעדט אַזעלכע הויכע טיפע ענינים פאַר אַלעמען. וואָס דאָס האָט זיך אָנגעהויבען פון די צייט ווען דער רבי, הוד כ\"ק אדמו\"ר הזקן, איז געקומען פון מעז­ריטש, וואו מען האָט אים געזאָגט ווער ער איז און וואָס ער דאַרף אויפטאָן בעולם<sup data-n=\"1476\">2</sup>, און האָט אָנגעהויבען מקרב זיין אנשים פשוטים. וואָס אנשים פשוטים איז באַ זיי דאָ אַ מעלה מעהר פון די יודעי תורה, די בעלי הבנה והשגה. די בעלי הבנה נעמען נאָר אויף וויפעל זיי זיינען מכיל<sup data-n=\"1477\">3</sup>, און זיי זיינען שוין צופרידען מיט דעם וואָס זיי האָבען גענומען. משא\"כ די אנשים פשוטים נעמען ניט מיט ידיעה, און זיי האָבען אַ שטאַרקע תשוקה אויף נעמען נאָך און נאָך מעהר.\nדי רביים האָבן מקנה געווען באַ חסידים אַז פרוץ איז מרובה על העומד, אין דעם ניט וויסען דערהערען מער ווי אין דעם וויסען.\nדי הפלאת הענינים וואָס רעדט זיך אין דעם היינטיגען מאמר, האָט די ביידע ענינים וכו'. וואָס באמת איז דער גאַנצער מאמר בלויז נקודות, בלויז נקודות פון די ענינים. אין יעדער ענין איז דאָך דאָ די נקודה, נאָכדעם דער תוכן, דער ביאור און דער הסבר, און נאָכדעם דער קיצור פון די ענינים. אָבער אין דעם מאמר איז די קשיא בלויז אַ נקודה, ביז דעם אויספיהר איז אויך מעהר ניט ווי אַ נקודה, נאָר עס איז דאָ אַ נקודה עצמיות און אַ נקודה ווי זי איז כולל ג' ענינים.\nדער עונג פון וויסען דעקט ניט דעם צער פון ניט וויסען. דאָס איז אַלץ אין ענין הידיעה פון חסידות. פאַר מדות חסידות, דאַרף מען אַוועקגעבען די העמד.\nד. דער טאַטע האָט אַמאָל פאַרבראַכט אין סוכה און גערעדט וועגען דעם ענין: חיצוניות שבעליון נעשה פנימי לתחתון<sup data-n=\"1478\">4</sup>. האָט ער געפרעגט: ווי אַזוי ווערט דאָס פון חיצוניות — פנימי, און וואָס איז דאָס פאַר אַ פנימי וועלכע ווערט פון חיצו­ניות, און וואָס איז דער חיצוניות פון",[["1475","1","נדפס בסה\"מ תש\"ט ע' נה ואילך."],["1476","2","ראה גם לעיל ס\"ע 150 ואילך."],["1477","3","נוסח אחר: זיי זיינען זיך מכין."],["1478","4","ראה עץ חיים שער יד (שער או\"א) פ\"ט. לקו\"ת שלח מא, ג. סה\"מ עטר\"ת ע' שכו. ה'ש\"ת ע' 24. ובכ\"מ."]]],[4301620496,"דעם פנימי? האָט ער געזאָגט אַ ביאור אויף דעם, ווי דער אַלטער רבי איז אַמאָל געזעסען אין סוכה און דערמאָנט דעם מגיד און דערציילט וואָס דער בעש\"ט האָט איבערגעגעבען דעם מגיד.\nדאָס האָט דער טאַטע געהערט זייענדיג אויף יחידות ביי דעם זיידען הוד כ\"ק אדמו\"ר מהר\"ש, וואָס ער האָט געהערט פון הוד כ\"ק אאזמו\"ר הצמח צדק, און האָט אויסגעפיהרט: דאָס האָט געמאַכט ליכטיג און וואַרעם לדורי דורות.\nה. (כ\"ק אדמו\"ר שליט\"א בירך ברהמ\"ז על הכוס ואחרי ברהמ\"ז לא שתה הכוס רק ציוה ליצוק הכוס יין לתוך הבקבוק מלא יין און גיין אין סוכה — שבחצר — להתוועד בהתוועדות חסידים. ואמר:) אין די איצטיגע צייט איז וויין אַ דבר יקר, יעדער טראָפּען דאַרף ברענגען אַ תועלת אין עבודה."],[4301620497,"<h3>ליל שמח\"ת קודם הקפות תש\"ט</h3>\nא. שמחת תורה רעדט מען נאָר בלויז ווערטער, דער פירוש וביאור דערהערט די עצם הנשמה.\nשמחת תורה — איז די נידעריגסטע דרגא דערהערט די העכסטע און די העכסטע איז זיך מתלבש אין די נידע­ריגסטע.\nאין יעדער זאַך איז דאָ אַ פירוש, ביאור והסבר. אויף דעם קידוש פון שמח\"ת האָבען מיר אַמאָהל געהערט, אַז דאָס איז לעילא מכל הפירושים, דער \"ולעילא\" פון נעילה (חסידים זאָגען דאָך ניט \"לעילא ולעילא\" — נאָר בלויז צו נעילה<sup data-n=\"1479\">1</sup>) דערהערט זיך אין דעם קידוש פון שמח\"ת.\nאַזוי ביי קידוש איז דאָך דאָ אַ מוציא און אַ יוצא, וואָס דער מוציא דאַרף מכוין זיין מוציא זיין, און דער יוצא דאַרף מכוין זיין לצאת, דאָס מיינט אַז ביידע דאַרפען האָבען דעת, אָבער קידוש פון שמח\"ת איז העכער דערפון, יעדער דאַרף נעמען דעם סידור און זאָגען די ווערטער פון קידוש און מאַכען שהחיינו אויף די תורה<sup data-n=\"1480\">2</sup>, דער שהחיינו פון קידוש פון שמחת תורה איז אויף תורה<sup data-n=\"1481\">3</sup>.\nב. תורת החסידות חב\"ד לייגט אַריין אַ פינגער אין מויל. מען דאַרף ניט האָבען יגיעה ועבודה, בלויז אויף השגה והבנה, עבודה ויגיעה דאַרף מען האָבען אויף דעם בפועל. עיקר העבודה איז מדות חסידות<sup data-n=\"1482\">4</sup>, און אַז עס איז דאָ מדות חסידות פאַרשטייט מען תורת החסידות, און אַז עס איז דאָ תורת החסידות, איז שוים דאַמאָלסט די מדות חסידות גאָר אַנדערע.",[["1479","1","ראה ספר השיחות תרפ\"ח­תרצ\"א ע' 140 (וש\"נ): כל עשי\"ת בקדיש \"לעילא\". בנעילה \"לעילא ולעילא\"."],["1480","2","ראה שיחת שמח\"ת תש\"ד — בקידוש הלילה (ספר השיחות תש\"ד ע' 32):\nאחד המסובים הציע להעומדים מסביב השולחן שאחד מהם יאמר קידוש ויוציא את האחרים, ואמר אדמו\"ר:\nדער \"שהחיינו\" וואס מען מאכט אין קידוש שמח\"ת, איז דאָס אויף תורה און ביי תורה איז ניטא דער ענין פון מוציא זיין, והלואי שכל אחד יפקיע את עצמו."],["1481","3","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 14. וש\"נ. שם ע' 196."],["1482","4","ראה גם לעיל ע' 112. ע' 117"]]],[4301620498,"ג. מען האָט אַמאָל גערעדט<sup data-n=\"1483\">5</sup> אַז שמחת תורה דאַרף מען אָנהויבען פאַ­נאַנדערפעקלען די פּעקלאַך וואָס מען האָט איינגעקויפט. שמח\"ת איז דאָך דער סיום העבודה פון חדשי אלול ותשרי, וואָס דאָס אַלעס דערהערט זיך אין שמע\"צ ושמח\"ת. אַזוי ווי אַ סוחר וואָס פאָהרט אויף אַ יריד און גיט אויס זיין גאַנצע געלט, און פאַרמשכונ'ט זיך אויף פרעמדע געלט אויף איינצוקויפען וואָס מעהר סחורה; נאָכדעם אַז ער קומט אַהיים, פּאַקט ער אויס די פּעקלאַך און לייגט פאַנאַנדער די סחורה, זעהן וואָס ער האָט איינגעקויפט. אַזוי איז אויך אין חדשי אלול ר\"ה יוכ\"פ און סוכות האָט מען איינגעקויפט אַסאַך סחורה; שמחת תורה דאַרף מען אָנהויבען פאַנאַנדערפּאַקען די פּעקלאַך, אָבער מען דאַרף מאַכען אַ חשבון ווי האָט מען אויסגעצאָהלט פאַר די סחורה פון פאַראַיאָהרען, מיט וואָס פאַר אַ חשבון קומט מען ווייטער נעמען, וואָס פאַר אַ פנים האָט מען פאַר זיך אַליין.\nד. חסידות חב\"ד מאָנט ניט אַז מען זאָל טאָהן אין תיקון העולם, נאָר טאָהן מיט זיך אַליין, מען דאַרף זיך קענען מיט די מעלות און חסרונות<sup data-n=\"1484\">6</sup>. מען דאַרף ניט מעלים זיין די מעלות עצמו, אויב מען הערט ניט אָן די בהירות פון די מעלה, דערהערט מען ניט די שאַרפקייט פון די חסרונות. נאָר דער חילוק איז פון וואַנען מען הויבט אָן: פאַראַן אַזעלכע וועלכע הויבן אָן פון די מעלה און בלייבן דערביי, ממילא ווערט ער מער יש און מער גס, ביז אַ נפש היפה קען ניט שטיין אין זיינע ד' אמות.\nס'קען זיין אַז איך רעד אַביסל צו האַסטיג, אָבער עס איז טוטוויי די האַרץ.\nאידן! עס קלינגט אין מיינע אויערן, האַרץ און מוח די ווערטער וועלכע איך האָב מיט אַ פולע יאָרן צוריק געהערט, וועגן דעם יוקר און געשמאַק פון יעדן אידן, פון אַ איש פשוט. וואָס דאָס וואָס דער אַלטער רבי האָט גענומען אין מעזריטש<sup data-n=\"1485\">7</sup>, וואָס לבד די גילוים וואָס מען האָט אים דאָרט מגלה געווען, ווער ער איז און וואָס ער איז און וואָס ער דאַרף אופטאָן אין עולם — האָט מען אויך מגלה געווען, צו דערהערן דער עילוי פון אַ איש פשוט, נאָר מען מוז דאָך רעדען דעם אמת.\nאיך רעד ניט וועגן דעם כלל חסידים, נאָר וועגן פרטים. פאַראַן אַזעלכע וואָס אַז מען רעדט מעלות מיינט ער אַז מען מיינט אים. חסרונות מאַכט ניט אויס, אויב ער מיינט זיך, חסרונות פעלט ב\"ה ניט, אָבער מעלות. . .\nוואו איז די קביעות עתים לתורה, קביעות עתים לתפלה באריכות. אויף תירוצים איז יעדער איינער אַ גרויסער.\nשמח\"ת איז אַ זמן צו מאַכן אַ החלטה אויף אַראָפּצובריינגען בפועל.\nה. הזמן קצר והמלאכה מרובה<sup data-n=\"1486\">8</sup>. וויל איך אייך איבערגעבן אַ קורצן וואָרט פון טאַטן.\nמיין נשמה — זאָגט דער טאַטע — איז אַראָפּגעקומען אויף צו מאַכן דעם מטה און ליכטיג מאַכן דעם מטה.\nבאמת איז דאָס אַזוי אין אַלע נשמות, נאָר דער חילוק איז פון אַ נשמה פרטית צו אַ נשמה כללית. מיין נשמה איז",[["1483","5","ראה גם שיחת ליל שמח\"ת תש\"ז (לעיל ע' 74)."],["1484","6","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 114. וש\"נ."],["1485","7","ראה שיחת יום א דחה\"פ תש\"ו (לעיל ע' 28. וש\"נ)."],["1486","8","ראה אבות פ\"ב מט\"ו."]]],[4301620499,"אַראָפּגעקומען מחנך זיין — אידן — און ממלא זיין. אַז עס איז געקומען אַ געוויסער זמן (כ\"ק אאמו\"ר אמר לי מתי הי' הזמן. אבל לא אוכל לגלות ברבים) — זאָגט מיר ווייטער דער טאַטע — בין איך געווען אויף יחידות ביי דעם טאַטן (הוא כ\"ק אאזמו\"ר מהר\"ש). זאָגט מיר דער טאַטע (כ\"ק אדמו\"ר מהר\"ש לכ\"ק אאמו\"ר) דו ווייסט נאָך וואָס דיין נשמה איז אַראָפּגעקומען דאָ למטה? דאָס איז בכלל אַ נשמה און בפרט אַ נשמה. . .\nאַז איך האָב דאָס דערהערט פון טאַטן — ממשיך כ\"ק אאמו\"ר — האָט מיר אָנגעחאַפּט אַ שטעכעניס ביז די פּיאַטעס פון די פיס — ומאז נחלה כ\"ק אאמו\"ר בגופו מה שסבל מזה כל ימי חייו — נאָכדעם האָב איך אָנגעהויבן לערנען שו\"ע מיט אַלע יש אומרים'ס און יש מחמירים'ס און האָב דאָס איינגילערנט מיט די אברי הגוף<sup data-n=\"1487\">9</sup>. און אַ משך זמן שפּעטער האָב איך פאַרשטאַנען אַז מען דאַרף טאָן מיט זיך, און ניט אין תיקון העולם; און זיך מזכך גיווען. ביז וואַנען אַז איך האָב געקראָגן אַ נמיכות רוח און אַ דרך ארץ פאַר זיך אַליין.\nהשכלה איז אַ פּעטאַקל<sup data-n=\"1488\">10</sup> ניט ווערט — ועשה תנועת צרידה באצבעותיו כמו שהי' רגיל לעשות —. אָבער עבודה איז אַ פולער הויפן — ועשה תנועה בידיו מלא חפניו — מיט גאָלדענע מטבעות. די גאַנצע השכלה איז נאָר צוליב עבודה, עבודה מיינט דערהערן: דערהערן אַ געשמאַק אין אַ אידן, אַ געשמאַק אין תורה, אַ געשמאַק אין מצוות, וואָס דעמאָלסט דערהערט מען אַ געשמאַק אין פנימיות העצמות.\nאַ נשמה כללית איז, אַז וואָס מען הערט און וואָס מען זעהט איז דאָס אַ גילוי מלמעלה<sup data-n=\"1489\">11</sup>.\nאַה! אַז מען וואָלט האָבן אַ ציור אין אַ נשמה וואָס זי טוט אין ג\"ע התחתון, אין ג\"ע העליון, אין די כ\"ד שעות היום, אין ימות החול, שבת יו\"ט און ר\"ח. די וועלכע לערנען פנימיות התורה ווייסן דאָס, אָבער מען דאַרף האָבען אַ ציור אין דעם.\nאפילו אין דער פינסטערע ביטערע קאַלטע אַמעריקא, לעבט מען מיט די זכרונות. מען דאַרף טאַקע ניט וועלן די יסורים, אָבער זיי זיינען מזכך.\nו. עס איז פאַראַן אַ דרך המלך, אַ שאָסיי, וואָס אויף דעם דרך המלך שטעלט מען אַוועק סימנים, פאסטא­ווייעס, וואָס זיי ווייזן וויפל מען איז שוין אָפּגעפאָרען און וויפיל מען דאַרף נאָך פאָרן. אויך ווייזן זיי דעם וועג: אויב דו ווילסט פאָרן דאָרט דאַרפסטו פאָרן דורך די וועג; און אויב דו ווילסט פאָרן ערגעץ אַנדערש וואו, דאַרפסטו פאָרן דורך דער אַנדער וועג. אַמאָל זאָגן זיי אויך אַ דרך קצרה, אָבער דער עיקר וואָס זיי ווייזן ווי צו פאָרן. די פאסטאווייעס נייטן ניט דעם מענטשן, נאָר זיי ווייזן אָן דעם ריכטיגן וועג וואוהין צו גיין.\nדער טאַטע האָט מייסד געווען תומכי-תמימים, ווי ער האָט געזאָגט און אויך געשריבען אין דעם ערשטען בריף<sup data-n=\"1490\">12</sup>, ניט צו מאַכען אַ ישיבה פאַר זיך,",[["1487","9","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 98. וש\"נ."],["1488","10","שם מטבע קטנה ברוסיא."],["1489","11","בא' הרשימות כ' המניח: כמדומה ששייך לעיל מה ששמע בעת היחידות אצל אדמו\"ר מהר\"ש."],["1490","12","קונטרס עץ החיים פרק כב. וראה לעיל ע' 166. וש\"נ."]]],[4301620500,"און בלויז צו קענען לערנען. דער טאַטע האָט מייסד גיווען תומכי-תמימים אויף צו מאַכען פאסטאוואייעס. די תמימים זיינען די פאסטאוואייעס<sup data-n=\"1491\">13</sup>, וואו זיי זיינען, דאַרפען זיי ווייזען דעם וועג; קיינעם ניט מכריח זיין, נאָר בלויז מורה זיין דעם דרך — וואו איז דער גוטער ריכטיגער וועג.\nאיך וויל יעצט ריידן צו די פאסטא­ווייעס, צו די תמימים: איר דאַרפט וויסן וואָס פאַר אַ כחות מען האָט אייך געגעבן, איר זאָלט אויסניצן די כחות. אַ אמירה פון אַ צדיק איז אַ נתינת כח, און בפרט אַז ער — דער צדיק — האָט זיך מוסר נפש גיווען אויף דעם. מען האָט אייך אנגיגלויבט דעם גושפנקא דמלכא, על דרך ווי אַ נאָטאָריוס, וואָס לייגט די חתימה, און קיינער קען נאָך דעם ניט משנה זיין; מיט וואָס איז זיין כח שטאַרקער פאַר אַ אַנדערן, נאָר מיט דעם וואָס ער האָט די גושפנקא דמלכא. אַזוי איז אויך איר תמימים, איר האָט די גושפנקא דמלכא, דאַרפט איר דאָס אויסניצן אין אייער עבודה, יעדער אויף זיין אָרט.\nעס איז אָבער פאַראַן דער קלוגינ­קער, אָט דער נוכל — יצה\"ר ונה\"ב — וואָס ער שאַרפט די ציינער איינצובייסן יעדערן לפי ערכו. דעם מיט השכלה, דעם מיט עבודה (מדות). אָבער דער אַלטער רבי האָט אויפגעטאָן אַז חסידים זאָלען זיין חכמים מחוכמים — דער­שמעקן זיי וואו דער עכבר ליגט, אַמאָל דאַכט זיך אַז עס שמעקט פון יענעם און באמת שמעקט גאָר פון זיך אַליין.\nשמחת תורה פּאַקט מען פאַנאַנדער די פּעקלאַך<sup data-n=\"1483\">5</sup>, אויב מען האָט נאָך ניט אויסגעניצט די סחורה פון פריערדיגן יאָר, קען מען דאָס אויך אַריינוואַרפן אין פרישן פּעקל.\nז. דער אויבערשטער זאָל געבן אַ שנת עבודה במנוחה. דער אויבערשטער זאָל אַראָפּנעמען אַלע מניעות ועיכובים אויף עבודה בפועל.",[["1491","13","ראה גם לקמן ע' 285."],["1483","5","ראה גם שיחת ליל שמח\"ת תש\"ז (לעיל ע' 74)."]]],[4301620501,"<h3>יום שמח\"ת בסעודה תש\"ט<sup data-n=\"1493\">1</sup></h3>\nא. אין דעם זמן ווען דער בעש\"ט נ\"ע איז געוועזען אַ נסתר, איז זיין הנהגה אויך געוועזן ווי אַ נסתר. די מעלת רוממות והפלאת נשמת הבעש\"ט האָבען דערהערט אפילו ציגן, זיי האָבן זיך אויפגעשטעלט אויף די אונטערשטע פיס, און די אויבערשטע פיס האָבען זיי געהאַלטן אין די הויך בקומה זקופה ווי אַ אדם<sup data-n=\"1494\">2</sup>. דער בעש\"ט האָט ממשיך געוועזן אין זיי ווי מצד זייער שרש ווי זיי זיינען למעלה, אָבער למטה זיינען זיי געבליבן ציגן, חאָטש בעל­שם'סקע ציגן וואָס באַ זיי איז געוועזן אַ הבדל פון חצי התחתון ביז חצי העליון, און עס האָט זיך דער­הערט באַ זיי מעלת העליון על התחתון, ניט ווי באַ אַנדערע וואָס באַ זיי איז דער תחתון גלייך ווי דער עליון — אָבער דאָך ציגן.\nלאחר התגלות פון דעם בעש\"ט: א) האָט זיך אָנגעהערט די מעלת האדם לגבי ציגן. ב) עס איז נתגלה געוואָרן די מעלה פון די אנשים פשוטים; ווייל אין יענעם זמן האָט זיך זייער אָנגעזען די",[["1493","1","בכי\"ק כ\"ק אדמו\"ר נשיא דורנו על הגליון: \"אינו מוגה\"."],["1494","2","ראה גם שיחת ליל א' דחה\"ס שנה זו (לעיל ע' 279)."]]],[4301620502,"מופלגי תורה — די יודעי תורה, און אַ איש פשוט איז גאָר קיין מציאות ניט געוועזען, מ'האָט זיך מיט איהם ניט גע­רעכענט, דער איש פשוט איז געוועזען אַ מובדל, און דער בעש\"ט האָט מגלה געווען די מעלה פון אנשים פשוטים.\nוואס אַזוי איז אויך געוועזן די שיטה פון אַלטן רבי'ן נ\"ע ביז ער איז געקומען קיין מעזריטש — זיין אַ מובדל פון אנשים פשוטים — ווען דער אַלטער רבי איז גע­קומען דאָס ערשטע מאָל קיין מעזריטש, לבד זאת וואָס דער מגיד האָט אים מגלה געווען ווער ער איז און וואָס ער איז און וואָס שליחות נשמתו איז בזה העולם, האָט ער אים געזאָגט אַז די שיטה איז קיין שיטה ניט<sup data-n=\"1495\">3</sup>.\nדער אַלטער רבי האָט געהאַט פון דעם אַ צער פנימי, און פון דעם קראַנק געוואָרען בגופו,\nדער אַלטער רבי וואָס זיין נשמה איז געוועזן אַ נשמה דאצילות עצמו, און דאָ למטה האָט זי מאיר געוועזן באַ אים דער תוקף עוז ווי למעלה<sup data-n=\"1496\">4</sup> — האָט געהאַט פון דעם אַ צער פנימי.\nהגם ער איז געוועזען אַ גיבור — איז ער קראַנק געוואָרן, וכידוע המעשה מהתולעים — בהחוטם — וואָס די רופאים האָבן געזאָגט אַז דאָס איז פון אַ טיפן צער<sup data-n=\"1497\">5</sup>.\nדער צער איז געווען אַ כפול ומשו­לש, פון זיך און פון די תלמידים, ווייל די תלמידים האָבן מרגיש געווען יעדע תנו­עה. און האָט בעדאַרפן אַ סאַך האָרעווען אַריינצוברענגן די שיטה; און בלויז דער קירוב<sup data-n=\"1498\">6</sup> האָט אים געגעבן כח דאָס דורכ­צוטראָגן.\nב. מען האָט שוין נעכטן גערעדט<sup data-n=\"1499\">7</sup> וואָס כ\"ק אאמו\"ר נ\"ע האָט געזאָגט, אַז ער האָט געמאַכט תומכי-תמימים אַז די תלמידים זאָלען זיין פאסטאוואייעס. פאסטאוואייעס זיינען געמאַכט געוואָרן צו ווייזן דעם וועג. תמימים דאַרפן ווייזן דעם וועג, מ'זאָל ניט זיין קיין תועה בדרך החיים. עס איז דאָ דרך החיים און חיי החיים, תמימים דאַרפן ווייזן פאַר אַלעמען דעם דרך פון חיי החיים, מ'זאָל ניט זיין קיין תועה בדרך.\nתמימים! איר טאָרט ח\"ו ניט פאַרנאַכ­לעסיגן די כחות וואָס מ'האָט אייך געגעבן. מען זאָגט צו זיך: מי אני ומה אני — ווער בין איך וואָס בין איך, און באמת איז ער טאַקע ניט קיין \"מי\" און מכש\"כ קיין \"מה\", ווייל ער איז דאָך אַ יש. נאָר אַז מ'האָט אים אַוועקגעשטעלט האָט ער כחות דערצו.\nאַז מען שטייט אויף דער פּאָסטן, איז יש לו על מי לסמוך; און אַז מען גייט אַוועק פון פּאָסטן<sup data-n=\"1500\">8</sup>, איז ער אַ מתחייב בנפשו.\nביים טאַטן — כ\"ק אאמו\"ר הרה\"ק — פלעגט זיין אַ אויסשפּראַך: מ'דאַרף זיך נעמען דאָ ראבאטי. מ'דאַרף זיך ניט",[["1495","3","ראה גם שיחת יום א' דחה\"פ תש\"ו. שיחת ליל שמח\"ת שנה זו (לעיל ע' 28. ע' 252)."],["1496","4","ראה לעיל ע' ס\"ע 150 ואילך. וש\"נ."],["1497","5","ראה שיחת כ כסלו תרצ\"ג סי\"ז: \"ידוע המעשה שרבינו הגדול הי' לו מחלה בחוטמו, אַז עס פלעגט באַ אים פון צייט צו צייט אַרויספאַלן שטיקליך פלייש, ואמרו על זה הרופאים אַז דאָס נעמט זעך פון אַ שטאַרקע טיפע ביינקעניש צו אַ זאַך, והוא ענין נכספה וגם כלתה נפשי\"."],["1498","6","ברשימת השיחה יש כאן מקום חלק. ואוצ\"ל: מהרב המגיד."],["1499","7","לעיל ס\"ע 283 ואילך."],["1500","8","נוסחא אחרת: אַז מען פאַרנאַכלעסיגט דעם פּאָסטן."]]],[4301620503,"פאַרלאָזען אויף דעם וואָס מען גיט מלמעלה; אַז מען האָרעוועט אַליין, העלפט דאָס.\nג. אמר: לחיים! דער אויבערשטער זאָל געבן חיים גשמיים, חיים רוחניים. דער אויבערשטער זאָל געבן אַ שנה ברוכה, עס זאָל ניט זיין קיינע מניעות אויף בריאות, פרנסה, נחת פון בני בית אין עבודה רוחנית.\nד. איך האָב שוין עטלעכע מאָל דער­ציילט<sup data-n=\"1501\">9</sup> אַז דער טאַטע — כ\"ק אאמו\"ר הרה\"ק — האָט מיט מיר געלערנט דעם סידור, איך מיין ניט איצטער דעם סידור מיט'ן פירוש פון אדמו\"ר הזקן — דאָס איז אַ באַזונדער זאַך — נאָר פשוט דעם פירוש המלות פון סידור.\nווען ער איז צוגעקומען וואו עס שטייט<sup data-n=\"1502\">10</sup>: \"לשמיני עצרת ולשמחת תורה\" דאַרף מען זאָגן \"ביום השמיני עצרת\" — האָט ער געפרעגט: וויבאַלד עס שטייט דאָך בפירוש \"ביום השמיני עצרת\" איז דאָך מובן אַז דאָס איז (אויך) אויף שמיני עצרת, און נאָך וואָס דאַרף שטיין בע­פאָר: \"לשמיני עצרת\"?\nהאָט ער געטייטשט:\nביום השמיני, שמיני מלשון שמן — פעט<sup data-n=\"1503\">11</sup>, דעם טאָג וואָס איז שמן מיט אַ סאַך אורות וגילוים, דאָס איז עצרת, תהי' לכם איז שמחת תורה.\nנאָך אַ פשט: ביום השמיני עצרת לשון קליטה, דאָס דערהערט זיך אין תהי' לכם, וואָס דאָס איז שמחת תורה.\nנאָך אַ פשט: ביום השמיני איז שמיני עצרת, עצרת שמחת תורה, תהי' לכם אין אַ גאַנץ יאָר.\nשמחת תורה איז די עבודה פון קלאַפּן מיט די פיס און קלאַפּען מיט די הענט, און אַ גאַנץ יאָהר איז די עבודה קלאַפּן (אַרבעטן) מיט'ן קאָפּ, ניט בלויז עפענען דעם מאמר, נאָר אַריינקלאַפּן דעם מאמר אין קאָפּ.\nה. עס איז דאָ אור באל\"ף און עור בעי\"ן<sup data-n=\"1504\">12</sup>.. .\nו. אַ חסידישע פאַרבריינגען איז אַלעס בהתיישבות אָן התגלות המדות, אויב יאָ איז אַלעס אין זיך.\nז. החג יש לו תשלומין כל שבעה<sup data-n=\"1505\">13</sup>, אין ליובאַוויטש דליובאַוויטש פלעגט מען פאַרבריינגען נאָך שמח\"ת אַלע נאַכט ביז ראש חודש. איך געדענק ווען איך בין נאָך געוועזען אַ קינד האָט מיך דער טאַטע מיטגענומען אין קליינעם זאַל צום פאַרבריינגען, די מאַמע האָט געמאָנט: ער דאַרף דאָך שלאָפן. ואמר<sup data-n=\"1506\">14</sup>: זאָל ער דאָרט שלאָפן, אַז ער וועט עלטער ווערן וועט זיך אים ניט וועלן שלאָפן<sup data-n=\"1507\">15</sup>. (ואמר כ\"ק אדמו\"ר שליט\"א:) מ'דאַרף ציילן די ווערטער. (ואמר עוד:) דאָ איז מען אביסל פאַרוואָגלט.\nח. (אמר:) מ'דאַרף זיך מכין זיין צו זינגען דעם ניגון של אדמו\"ר הזקן בן ד' הבבות, די הכנה איז זינגען אַ ניגון קודם לזה (וצוה לכפול בבא הרביעית ארבעה פעמים).",[["1501","9","ראה שיחת י\"ב תמוז תש\"ז (לעיל ע' 140)."],["1502","10","בתפלת המוסף."],["1503","11","ראה סה\"מ תרצ\"ו ע' 41. וש\"נ."],["1504","12","ראה ב\"ר פ\"כ, יב. או\"ת להה\"מ ס\"פ בראשית. מאמרי אדה\"ז פרשיות ח\"א ע' מה. ע' נ. סהמ\"צ להצ\"צ ח, סע\"א. ועוד."],["1505","13","ראה ר\"ה ד, ב."],["1506","14","כ\"ק אדמו\"ר מהורש\"ב."],["1507","15","ראה גם שיחת ליל ב' דחה\"ס תש\"ז (לעיל ע' 67). וש\"נ."]]],[4301620504,"<h3>שיחה<sup data-n=\"1508\">1</sup> </h3>\n<b>[ד' כסלו בערב, בהיכל כ\"ק אדמו\"ר שליט\"א<sup data-n=\"1509\">2</sup>]</b>\nהוד כ\"ק אדמו\"ר הזקן האָט מקבל גיווען מכ\"ק אביו ומכ\"ק דודו הר\"ר יוסף יצחק כמה עניני תורה ועבודה וסדרי הנהגה של מורנו הבעש\"ט בחול ובשבת קודש ובמועדי השנה.\nמורנו הבעש\"ט זאָגט:\nיעדער איד קומט אויף דעם עולם הזה החומרי מיט אַ געוויסע שליחות פון תורה אור, תורה ליכט. און מיט אָט דער שליחות פון תורה ומצות גייט ער אום און פאָרט אַרום, הן באַ זיך אין שטאָט און הן וואוהין און באַ וואָס פאַר אַ געלעגענ­הייט ער פאָרט, מיט אַ שליחות פון תורה ויראת שמים און מחזק זיין מוסדות התורה.\nהחזקת התורה וחינוך הכשר איז דער עמוד האור וואָס בעלייכט דעם חשך פון דער גראָבער חומריות'דיקער וועלט און בריינגט צום אמת'ן תכלית צוליעב וועלכען די נשמה איז אַראָפּגעקומען אין דער חומריות'דיקער קאַלטער וועלט.\n* * *\nרבנים, שוחטים, ראשי ישיבות און עלטערע בני תורה שאקלען מיט די קעפּ אויף דעם מצב הלא טוב, און פאַראַן ביניהם וואָס זיינען יוצא ידי חובתם נאָר מיט אַ בעדויער­קרעכץ: וואָס זאָל מען טאָן?\nאון מיט דעם קרעכץ מיינען זיי אַז זיי זיינען שוין יוצא ידי חובתם בדרכי עבודה.\nבאמת זיינען זיי גאָר די חייבים אין אָט דער געשאַפענער רוחניות­קעלט.\nדי חברה קרעכצער אויף דעם מצב השפל פון תורה בכלל און עבודה בדרכי החסידות בפרט, בעדאַרפן קרעכצען אויף זייער אייגענעם מצב הרוחני.\nדי איצטיקע חסידישע בעלי עבודה האָבן פאַרגעסן דעם אמת'ן עבודה \"א\" (אלף) וואָס איז מקובל באַ חסידים פון קדמונים: ווייניקער געקרעכצעט און מער געטאָן.\n* * *\nאַז מען זאָגט יענעם דעם אמת דערהערט ער.\nמען דאַרף זאָגן דעם אמת אָן אַ ווערטל, ווייל ווען מען זאָגט מיט אַ ווערטל, נעמט דאָס יענער אויך אָן ווי אַ ווערטל, אָבער ווען מען זאָגט יענעם דעם אמת ווירקט דאָס.\nשאלה: דאַרף מען דאָך האַלטן ביים אמת?\nמענה: אַ ודאי בעדאַרף מען האַלטן ביים אמת. נאָר דערצו מוז מען אויך וויסען אין יעדען איינצעלנען פאַל ווער עס זאָגט דאָס די תביעה, צי דער יצר טוב צי דער יצר הרע<sup data-n=\"1510\">3</sup>. ער — דער יצר הרע — איז דאָך אַ ערום פון והנחש הי'",[["1508","1","מרשימת אחד השומעים. נדפס עם הערה מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ תש\"ט ע' 71."],["1509","2","בהעתק המזכירות: הרב ר' שלמה אהרן שי' קאַזאַרנובסקי מספר מהשתתפותו בחגיגה השנתית של ישיבת אחי­תמימים ליובאַוויטש בעיר ספרינגפיעלד ואת אשר נאם מר מאָריס קאַטץ. אח\"כ אמר כ\"ק אדמו\"ר שליט\"א [ההמשך בפנים]."],["1510","3","זע די שיחה פון פסח תש\"ג אות למ\"ד [ספר השיחות תש\"ג ס\"ע 66 ואילך]. היום יום [כ\"ג סיון] ע' סד."]]],[4301620505,"ערום<sup data-n=\"1511\">4</sup>, דאָס הייסט — שקרן. איינעם מאַכט ער זאָל זיך האַלטן קליין, און איינעם פאַרקערט ער זאָל זיך האַלטן גרויס. און מיט פאַרשידענע תחבולות לאָזט ער ניט צוקומען צום אמת.\nמען דאַרף יענעם זאָגען דעם אמת, מען דאַרף זיך ניט זידלען, אָבער דעם אמת דאַרף מען זאָגן, און ער דערהערט.",[["1511","4","בראשית ג, א."]]],[4301620506,"<h3>כסלו תש\"ט<sup data-n=\"1512\">1</sup></h3>\nיו\"ד כסלו תרס\"ג הי' התוועדות אצל אמי זקנתי<sup data-n=\"1513\">2</sup>, ולא הרשו להבחורים מה\"זאַל\" להיכנס לההתוועדות. כמה עלטערע בחורים (בערל לאַדיער ועוד) עמדו מאחורי הדלת ושמעו וואָרט — כי יוסף מרדכי<sup data-n=\"1514\">3</sup> האָט זיי ניט באַמערקט. בכלל — ההתוועדויות של יו\"ד כסלו היו קצרות<sup data-n=\"1515\">4</sup>, ואמר אז כ\"ק אאמו\"ר: שוין צייט אַרויסגיין פון חדר, אַז מ'איז אין חדר איז מען אַ בולע, אַז מ'גייט אַרויס דאַרף מען מגלה זיין דעם טוב און מכחד זיין דעם רע, מאַכן עם פאַר אַ טוב תקיף.",[["1512","1","הרמ\"ש שי' הי' ביחידות אצל כ\"ק אדמו\"ר שליט\"א קודם ההתוועדות, וסיפר כ\"ק אדמו\"ר שליט\"א: [ההמשך בפנים]."],["1513","2","ראה אודותה לעיל ע' 14. וש\"נ."],["1514","3","המשרת. — ראה אודותו לעיל ע' 233. וש\"נ."],["1515","4","ראה גם רשימת היומן — ט' כסלו תרצ\"ג (\"רשימות\" חוברת סט ע' 6)."]]],[4301620507,"<h3>י\"ט כסלו תש\"ט<sup data-n=\"1516\">1</sup></h3>\nא. חסידות<sup data-n=\"1517\">2</sup> איז אַריינטראָגען סדר אין בלתי סדר און מאַכען פון בלי סדר אַ סדר.\nבנוסחא אחרת: מאַכען אַ סדר אין בלי סדר<sup data-n=\"1518\">3</sup>.",[["1516","1","\"אַ טייל פון די רייד פון כ\"ק אדמו\"ר שליט\"א, י\"ט כסלו ה'תש\"ט — לויט אַ פאַרצייכנונג פון די הערער — אַרויסגעגעבען צו י\"ט כסלו ה'תש\"י\" — נדפס עם מ\"מ והערות כ\"ק אדמו\"ר נשיא דורנו בסה\"מ ה'שי\"ת ע' 102 ואילך.\nוראה מכתב רבינו מי\"ט כסלו תש\"ט (אגרות­-קודש ח\"י ע' מא): \"אשר רשות הכניסה לההתועדות היום אי\"ה ניתן רק להתלמידים הקשישים הבחורים הלומדים חסידות ועוסקים בעבודת התפלה\"."],["1517","2","[בהנחה בלתי מוגה: נשפך קעלעשיק משקה על השולחן, ואמר כ\"ק אדמו\"ר שליט\"א: זאָל זיך גיסן משקה.\nנכנסו איזו רבנים מכובדים להמסיבה לאחרי שכבר ישבו כולם אצל השולחן, ואמר אחד להביא אַ פּאָר \"טשערס\", ואמר כ\"ק אדמו\"ר שליט\"א: מ'דאַרף מער ווי אַ פּאָר.\nואמר: דאָס איז חסידישער סדר [ההמשך בפנים]."],["1518","3","ראה אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' ריט: ולסיים בעיון בדברי הרב, ולהראות עד כמה וכמה יש לדייק גם בתיבות שנראות רק כפל לשון לחזק הענין. . חסידות איז אַריינטראָגן סדר אין בלתי סדר, און מאַכן פון בלי סדר אַ סדר, בנ\"א: מאַכן אַ סדר אין בלי סדר. ולכאורה כהנ\"ל הוא כפל הענין במילות שונות.\nויובן בהקדם, ובקיצור נמרץ: סדר ובל\"ס זהו תקון ותהו, ואח\"כ — תומ\"צ וגוף וענינים הגשמיים שהם תערובות טו\"ר, והדגיש הבעש\"ט וביאר זה אדה\"ז, שהעבודה צ\"ל לא בגדר סיגוף ודחי' כ\"א בדרך בירור ועלי'. כידוע פי' הבעש\"ט עה\"פ כי תראה חמור (היום יום [כח שבט] ע' כ\"ג). וכמובן כהנ\"ל צ\"ל נעשה, ע\"פ דרישת תורת החב\"ד, לאט לאט ולא בדרך מקיף (יעוין קונטרס העבודה בסופו).\nוזוהי ההוראה בשיחה הנ\"ל הדרגות בהעבודה ע\"פ חסידות: א) אַריינטראָגן סדר אין בל\"ס, בתחלת העבודה הם עדיין ב' דברים נפרדים, אלא שממשיך גילוי נה\"א בנה\"ב ונה\"ב שותק. ב) מאַכן פון בלי סדר אַ סדר, אֵין בל\"ס כ\"א סדר בלבד, נה\"ב מתפללת ולומדת אחר נפה\"א המקריא אותה, אבל לא בא עדיין לורב תבואות דכח שור, אבל התכלית הוא, וזהו נוסחא אחרת לגמרי: ג) מאַכן אַ סדר אין בל\"ס. שישנם המעלות דשני הענינים גם יחד, אורות מרובים דתהו בכלים מרובים דתקון.\nוראה סד\"ה כי עמך הסליחה תש\"ט בענין תשובת הגדר ומשקל. ואכמ\"ל]."]]],[4301620508,"ב. מען מאַכט אַ טעות, מען מיינט אַז אין חב\"ד קען זיין מער סדר ווי אין מדות, דער אמת איז אַז דער עיקר הסדר איז אין מדות ווייל עיקר המוחין איז בשביל המדות.\nהגם אַ בעל מוחין איז אַ ערנסטער, ער גייט ערנסט, ער שטייט ערנסט, ער איז אויסגערעכענט — און אַ בעל מדות איז אַ בהול, דאָך דער עיקר הסדר איז אין מדות, כללות המוחין איז בשביל המדות, און גילוי המוחין איז אין מדות. דער עיקר איז מדות.\nג. עס איז פאַראַן אַ אַלטער וואָרט און במשך הדורות איז אין דעם וואָרט געזאָגט געוואָרן אַפולע ביאורים.\nדי גמרא זאָגט<sup data-n=\"1519\">4</sup> מדת חסידות שנו כאן. לכאורה שנו איז דאָך לערנען, איז דאָך דאָס מוחין ניט מדות. נאָר דער עיקר פון לערנען איז בשביל מדות חסידות<sup data-n=\"1520\">5</sup>. שנו איז לשון שינון, שאַרף, עס דאַרף זיין שאַרפע מדות.\nעס איז דאָ מהיכי­תיתי'דיגע מדות, ער איז אַ איש טוב מהיכי תיתי, ער טוט אַ טובה מהיכי תיתי.\nעס דאַרף זיין שאַרפע מדות, שאַרף הייסט אַז עס שנייט מלפניו ומלאחריו.\nד. עס קען זיין אַ למדן מופלג, ער זאָגט חידושים אין תורה, ווען ער איז נאָך געווען אַ אינגעל און דער זיידע האָט איהם פאַרהערט האָט ער געזאָגט אַ שאַרפען תוספות מיט אַ קנאַק, און איצטער האָט ער תלמידים וואָס די קטנים שבהם ווערען פאַררעכנט אין עולם הלומדים. אָבער וואָס האָט ער זיך אויסגעלערנט, צי האָט ער זיך אויסגע­לערנט דאַוונען.\nה. אין דאַוונען איז דאָ פאַר'ן דאַוונען און נאָכן דאַוונען. דאַוונען איז ניט אָפּגעדאַוונט — נאָר דאַוונען.\nמ'דאַרף דאַוונען.\nו. (אמר לש. פ.<sup data-n=\"1521\">6</sup>:) דו פאָרסט זעהן די גלות אידען; באמת זיינען מיר אַלע אין גלות, און אין אַ שטאַרקען גלות. גלות איז שינה<sup data-n=\"1522\">7</sup>. אין שלאָף חלום'ט זיך, עס איז אַ זיסער חלום, אַ גוטער חלום, אָבער אַז מען חאַפּט זיך אויף, זעהט מען אַז עס איז תהו ובהו, פּוסט און וויסט.\nמען מיינט אַז מען האָט כסף וזהב, מלבושי כבוד, אָבער עס איז לא דובים ולא יער, די געלט גייט אַוועק אויף מסים וארנוניות. און אַז ער חאַפּט זיך, זעהט ער אַז ער האָט אַ גרויסע לאָך.\nמען מיינט אַז עס איז אַ זיסער חלום, אָבער באמת איז דאָס אַ ביטערער חלום.",[["1519","4","שבת קכ, א. ב\"מ נב, ב. חולין קלז, א."],["1520","5","[ראה גם שיחת ליל שש\"פ תש\"ז (לעיל ע' 117)."],["1521","6","ר' חיים שלמה פאלמער שנסע לאה\"ק בתור אחד מראשי ועד \"קרן הצלה\" — ראה אגרות­-קודש ח\"י ע' מ. וש\"נ]."],["1522","7","תו\"א פ' וישב ד\"ה שיר המעלות. שם סד\"ה ואלה שמות. מאמרי פורים ש\"ת ותש\"ח, ובכ\"מ."]]],[4301620509,"דאָ איז אַ טומאַן<sup data-n=\"1523\">8</sup>. מ'ווערט פאַרטו­מאַנעוועט — פאַרטשאַדעט, אפילו אַ איד<sup data-n=\"1524\">9</sup> וואָס ווייס ווי מדאַרף זיין, אַז ער קומט דאָ אַהער ווערט ער פאַרטשאַדעט.\nאַמאָל פלעגט מען זאָגען אַ וואָרט: אין דער הינער­פּלעט, אָבער עס קלאַפּט נאָך אַ לעבעדיגער אָדער.\nפאָר געזונד און קום געזונד, זאָלסט איבערגעבען וואָס האָסטו דאָרט געזען, און זאָלסט זעהן די מעלה פון יעדען אידען, און זאָלסט מצליח זיין אין פדיון שבויים.\nז. אַי, פאַר וואָס דאַווענט מען ניט.\nמען מיינט אַז מען איז יוצא מיט דעם וואָס מען איז אַ חסיד. ווער רעדט נאָך אַז ער לאָזט אַ מאָהל אַ טרער, וואָס מלאך מיכאל חאַפּט אויף די טרער און ברענגט זי למעלה, אַי, אַ מציאה, אַ אידישער טרער.\nער איז דאָך אַ בן עולם הבא, וואונ­דערט ער זיך פאַרוואָס מלמעלה איז מען איהם ניט מגלה חידושי תורה, די וועלט זאָל וויסען פון איהם, עס וואָלט דאָך געוועזען אַ חיזוק התורה.\nער ווייסט ווער ער איז. וואָס ער איז ווייסט ער ניט, זיין דעת דערגייט ניט צו דעם, אָבער ווער ער איז ווייסט ער, ער איז שוין ביי זיך אַ פאַרטיגער, אָבער באמת האַלט ער ביי דער התחלה אויך ניט.\nאון דער חשבון דאַרף זיין ביי קריאת שמע שעל המטה, און אין דערפריה דאַרף ער אויפשטיין גאָר אַ אַנדערער<sup data-n=\"1525\">10</sup>.\nאַי, אַן אַמאָליגער חסידישער דאַוו­נער!\nח. אַ סאָלדאַט אַז ער גייט אין פאחאד לערנט מען אים טראָגען אַ ראניעץ, דער ראניעץ איז אַ מועט המחזיק את המרובה, פון אַלע מינים כלי זין, און אַז ער גייט, גייט ער מיט אַ מאַרש, מיט שמחה.\nדער סאָלדאַט גייט דאָך אויף מסירת נפש, אָט איז ער פאַראַן און אָט ווערט ער ניט, — אָבער ער גייט מיט אַ מאַרש<sup data-n=\"1526\">11</sup>.\nאויב עם האַרט — האַרט עם ניט פאַר זיך, עם האַרט נאָר צוויי זאַכען: ער זאָל זיך ניט מאַטערען און געבען אַ חיזוק דעם שונא; און דער תועלת הרבים, ניט גורם זיין אַ נפילת הרוח און פחד ביי זיינע חברים.\nדער ראניעץ איז דאַוונען. און עס איז ידוע דעם זיידענס מאמר<sup data-n=\"1527\">12</sup> אויף די חמשה כלי זין ווי זיי זיינען אין דאַוו­נען<sup data-n=\"1528\">13</sup>.\nט. פון די ערשטע תורות וואָס דער רבי האָט געזאָגט פאַר זיינע תלמידים צוריק­קומענדיג פון מעזריטש, וואָס עס איז בקבלה אַז דער וואָרט איז אַ פנימיות­נשמה'דיג וואָרט<sup data-n=\"1529\">14</sup>:\nהקדמה:\nווען דער רבי איז צוריקגעקומען פון מעזריטש האָט ער בעדאַרפט האָבען אַ",[["1523","8","[ראה גם שיחת ליל א' דחה\"ש שנה זו (לקמן ע' 329)."],["1524","9","בהנחה בלתי מוגה: אפילו אַ רוסישער איד."],["1525","10","ראה גם לעיל ע' 5."],["1526","11","ראה לעיל ע' 122. וש\"נ."],["1527","12","ד\"ה לא יצא האיש לא בסייף כו' תרל\"ב (סה\"מ תרל\"ב ח\"א ע' נב ואילך)]."],["1528","13","ראה ג\"כ ד\"ה ת\"ר נ\"ח תרנ\"ט. קובץ מכתבי כ\"ק אדמו\"ר נ\"ע מכתב א [אגרות­-קודש אדמו\"ר מהורש\"ב ח\"א ע' כד."],["1529","14","עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620510,"התנצלות פאַר זיינע תלמידים פאַר דעם שינוי הדרך.\nכידוע אַז יעמולט זיינען די בני תורה געוועזען מובדל פון אנשים פשוטים, מ'האָט געהאַט אַ אייגען מנין, און מ'האָט זיי ניט צוגעלאָזט צום עמוד אפילו ביי אַ יא\"צ<sup data-n=\"1530\">15</sup>. קומענדיק אָבער פון מעזריטש האָט דער רבי משנה געווען דעם דרך<sup data-n=\"1531\">16</sup>.\nדי תלמידים פון אַלטען רבין האָט מען ניט געקענט אָפּקומען מיט זיי מיט פשט'לאַך. זיי האָבען געוואוסט, חב\"ד איז חב\"ד, חג\"ת איז חג\"ת.\nהאָט דער רבי זיי געזאָגט אַ תורה פון מגיד בשם הבעש\"ט:\nקל וחומר וגזירה שווה<sup data-n=\"1532\">17</sup>. קל וחומר מיינט אַז אַ דבר קל זאָל זיין חמור. גזירה שווה — אַ גלייכער שניט. דאָס קען נאָר זיין אלא אם כן קבלה מרבו ורבו מרבו הלכה למשה מסיני<sup data-n=\"1533\">18</sup>.\nהלכה למשה מסיני, משה האָט ניט געוואָלט אַוועקגיין פון סיני אין וועלט. הגם משה האָט זיך געקענט ספראַווען מיט זיין גוף, אָבער ער האָט ניט גע­וואָלט אַוועקגיין מסיני. משה איז חכמה. חכמה דאצילות בעלייתה אל הכתר, וויל זי ניט זיין די ערשטע ספירה, אָבער מצד פנימיות החכמה ווען זי איז עולה אין פנימיות הכתר דערהערט מען די כוונה פנימיות אַז דער עיקר איז דאָ למטה. —\nדאָס איז הלכה למשה מסיני, הלכה לשון מוליך<sup data-n=\"1534\">19</sup>, ער האָט מוליך געווען משה'ן ער זאָל וועלען אַוועקגיין מסיני למטה. ביז ולא ידע איש את קבורתו<sup data-n=\"1535\">20</sup>, וואו משה האָט באַהאַלטען זיין גוף, אַז ער האָט עולה געווען אין פנימיות החכמה<sup data-n=\"1536\">21</sup>.\nי. לא מיבעי אַז עס דאַרף זיין מדות טובות, מדות חסידות — אטו בשופטני עסקינן; נאָר עס דאַרף זיין אהבת ישראל, אהבת התורה און אהבת השם, וואָס די דריי זיינען געשלאָסען צוזאַמען איינע אין איינע.\nעס איז פאַראַן אַ סדר פון מלמעלה למטה און פון מלמטה למעלה: אַז מען האָט האָלט אַ אידען האָט מען האָלט תורה, און אַז מען האָט האָלט תורה האָט מען אהבת השם<sup data-n=\"1537\">22</sup>. אַז עס איז דאָ אהבת השם האָט ער אהבת התורה, און אַז ער האָט אהבת התורה האָט ער אהבת ישראל<sup data-n=\"1538\">23</sup>.\nדאָס דאַרף זיין ביי יעדען לפי ערכו, און דורך דעם איז די עלי' אין עולם. עס איז דאָך מוצב ארצה, ער שטייט ניט אין דער לופטען. דער תכלית איז דאָ למטה, און וראשו מגיע השמימה<sup data-n=\"1539\">24</sup>.\nיא. איך ווייס ניט צי עס זיינען דאָ חילוקים פון אַ חסיד'דישען מוהל און אַ עולם'שען, אָבער דער ומלתם את ערלת",[["1530","15","ברשימת השומעים נוסף: ווי אין ליובאַוויטש דוד גורארי', כמעשה הידוע."],["1531","16","ראה גם לעיל ע' 28. וש\"נ."],["1532","17","ברייתא דרבי ישמעאל (הקדמה לתורת כהנים)."],["1533","18","רש\"י סוכה יא, ב — ד\"ה לא ילפינן. וראה רש\"י פסחים סו, א ד\"ה וכי מאחר וד\"ה הכי קאמר."],["1534","19","ראה ערוך ערך הלך. אוה\"ת יתרו ע' תתצו."],["1535","20","ברכה לד, ו]."],["1536","21","להעיר ממרז\"ל (סוטה יד, א) לעליונים כו' לתחתונים כו' ונתבאר בלקו\"ת במדבר ד\"ה מעט תוספות ביאור על ענין וספרתם [יב, א]. סד\"ה כי ישאלך בנך ש\"ת [סה\"מ ה'ש\"ת ע' 49."],["1537","22","ראה לעיל ע' 149]."],["1538","23","להעיר ממרז\"ל (זח\"ג עג, א) תלת דרגין אינון מתקשראן דא בדא קוב\"ה אורייתא וישראל."],["1539","24","[ויצא כח, יב."]]],[4301620511,"לבבכם<sup data-n=\"1540\">25</sup> דאָס פעלט ביי אַלע, ביי חב\"ד, ביי חג\"ת. דעם קלוגינקען דאַרף מען אינגאַנצען מדחה זיין. אפילו דעם נפש הבהמית, ער איז דאָך אַ בעל מוחין, דאַרף מען מברר זיין.\nיב. עס איז ידוע אַז ביי אַ שמחה פון אַ צדיק, קומען אַלע נשמות אין זיין היכל זיך משמח זיין. מ'האָט געהערט אין דעם ענינים, אָבער ניט אַלעס קען מען איבערגעבען, ווייל מען איז מוכה אין חיצוניות.\nיג. דער אויבערשטער זאָל העלפען מזאָל דערהערען די כוונה פנימיות פון חסידות.\nיד. מיר זיינען שוין אויסגעמושטירט ניט צו מאַכען קיין פּאַראַדקעס, אָבער מ'קען זיך ניט פרייען מיט פאַלשע ישועות און טרייסטען מיט פאַלשע נחמות. מען דאַרף זיך ציען צום אמת.\nמען דאַרף קיין זאַך ניט מבטל זיין, און מ'טאָר ח\"ו קיינעם ניט מדחה זיין.\nמדאַרף ניט זיין אַראָפּגעפאַלען. דער אויבערשטער זאָל העלפען עס זאָל נתגלה ווערען דער גילוי חיות פנימי פון משיח, ער זאָל אונז פירען צום אמת בגו\"ר.\nטו. דער אויבערשטער זאָל העלפען, יעדערער זאָל האָבען נחת פון זיך, נחת פון קינדער, פון כלל ישראל, יעדער איינער און זיינע בני בית — בגשמיות וברוחניות. יעמאָלט וועט דער אויבער­שטער זעהן וואָס אידען קענען אויפטאָן.\nטז. (מרוב הדוחק והצפיפות דחפו את השולחן אשר ישב אצלו כ\"ק אדמו\"ר שליט\"א, ואמר אחד: שטופּט ניט דעם טיש. ואמר כ\"ק אדמו\"ר שליט\"א:) אידען מאַכען מיר ניט ענג. איך האָב זיך אויסגעהאָדעוועט אויף אידישע און חסיד'ישע שווייס.\nטו\"ב. (צוה לנגן אַ הקדמה ניגון צום רבינס ניגון, ואח\"כ את הניגון דד' בבות<sup data-n=\"1541\">26</sup>, ובמתינות, והבבא הד' ג' פעמים, ובין פעם לפעם לעשות הפסקה. אח\"כ צוה לנגן את הניגון ניע זשוריטצע חלאָפצי<sup data-n=\"1542\">27</sup>. כשסיימו לנגן אמר<sup data-n=\"1543\">28</sup>:) זייט אַלע געזונד, אַ גוטען יום טוב.",[["1540","25","עקב י, טז. וראה תניא אגה\"ק ס\"ד (קה, ב)]."],["1541","26","ראה אודותו בספר הניגונים [חלק א] ניגון א."],["1542","27","ראה אודותו בספר הניגונים [שם] ניגון קיא."],["1543","28","[בהנחה בלתי מוגה: הזהיר אשר התלמידים הקטנים לא ישתו יי\"ש]."]]],[4301620512,"<h3>שיחה<sup data-n=\"1544\">1</sup></h3>\nזאָגן אַ שיעור קבוע תהלים בהת­עוררות בכי איז זייער נויטיק פאַר יעדער אידן בכלל, און בפרט פאַר דעם וואָס איז יודע מצבו הפרטי און עס דערנעמט די האַרץ, איז אַ קאַפּיטל תהלים מיט אינערליכע תמימות­טרערן אַ געוויסע רפואה. וכמאמר דמעות מכבסות<sup data-n=\"1545\">2</sup>, וכמבואר בדרך החיים בסדרי הבעל תשובה.\nחז\"ל אומרים<sup data-n=\"1546\">3</sup> גדולה תשובה שמביאה רפואה לעולם. דער עולם הזה החומרי איז אַ חולה און אַ חולה דאַרף נעמען סמי רפואה.\nאין נעמען אַ רפואה<sup data-n=\"1547\">4</sup> איז פאַראַן אַ געוויסער סדר וויפיעל צו נעמען און ווען צו נעמען. דער זמן און די כמות מוזן שטאַרק אָפּגעהיט ווערן און דאַן העלפט די רפואה.\nאַלע ווייסן אַז אַ רפואה נעמט מען טראָפּענסווייז, ניט גלעזערווייז. דער וואָס טרינקט אַ רפואה גלעזערווייז איז דאָס אַ סימן אויף דער גרויסער חולאת, וענינו ברוחניות הוא אַז מען מוז וויסן אַז דער נה\"ב האָט אַ יד אין דעם.\n* * *\nאין משך פון די איבער הונדערט און פינף און זיבעציק יאָר, תקל\"ב — תש\"ח, פון דער אמת גליקליכער צייט, זינט הוד כ\"ק רבינו הזקן האָט בחסדו ית' מייסד געווען דעם דרך הקודש פון חסידות חב\"ד, האָט מען אָנגעצייכנט די אופני הדרכה והנהגה ווי אַזוי מען בעדאַרף און מען קען שטייגן אויף דעם סולם חסידות חב\"ד.\nדער סולם חסידות חב\"ד האָט פיעל טרעפּ.\nדער באָדן אויף וועלכן דער חב\"ד סולם שטייט איז די חב\"ד חסידישע היים. באַ די חסידישע טאַטע מאַמעס, וואָס באַ יעדער געלעגענהייט האָבן זיי דערציילט זייערע קינדער וואָס זיי האָבן געזעהען און געהערט אין זייערע עלטערנס היימען.\nדאן קומען די חדרים טרעפּ, וואָס דער חב\"ד­חסידישער מחונך שטייגט משליבה לשליבה אין די חדרים וישיבות, און אין אָט דעם חינוך זמן הויבט זיך אָן דער זמן וואָס דער אור פון לימוד התורה און דער חושך פון גאוה וישות זיינען משמשים בערבוביא און כל תלמיד ותלמיד ווערט מושפע פון דעם אופן הנהגת הישיבות, צי די מיסדי הישיבה",[["1544","1","נדפס בלקו\"ד ח\"ג תקב, ב ואילך.\nמועתק בזה לשון ה\"פתח דבר\" שם (תקא, ב):\nאין דער פאָרליגענדער חוברת ווערט גע­דרוקט די שיחה פון כ\"ק מו\"ח אדמו\"ר שליט\"א, וועלכע ער האָט אַרויסגעגעבען צו יום ההלולא של כ\"ק אדמו\"ר הזקן — כד טבת, ווי עס ווערט ערקלערט אין זיין בריף, פון יב כסלו תש\"ט<sup data-n=\"e30\">*</sup>. . ווי אין אַנדערע אויסגאַבען פון \"אוצר החסידים\" זיינען אויך דאָ צוגעגעבען געוואָרען אייניגע מראי מקומות און באַמערקונגען מהמו\"ל.\nמנחם שניאורסאהן\nטו\"ב טבת ה'תש\"ט, ברוקלין נ. י."],["1545","2","דמעות מכבסות: ראה זח\"ג עה, ב. ראשית חכמה שער התשובה פ\"ה."],["1546","3","[יומא פו, א]."],["1547","4","אין נעמען אַ רפואה: להעיר ג\"כ מהרשימה בסוף קונטרס חי אלול תש\"ח (ע' 20 [לעיל ע' 264] ואילך)."],["e30","*","נדפס בלקו\"ד שם תקב, א. אגרות­-קודש ח\"י ע' לח. בסיום המכתב שם: \"ולהיות כי הרבה ממחונכי התמימים טועים באופני ועניני עבודה, הנני מעריך שיחה מיוחדת בזה, ויבוא אי\"ה בדפוס לכ\"ד טבת\"."]]],[4301620513,"והמנהלים געהערן צו חסידים בכלל, און באופן פרטי, צי חסידי חב\"ד צי חסידי חג\"ת — פולין גאַליציא וכו', אָדער די מייסדים ומנהלים זיינען עולמשע, ווערן די תלמידים מושפעים פון דעם סגנון המנהלים, יעדער לפי תכונת נפשו.\nאין אָט דעם זמן, ווען מען איז אַ תלמיד, איז על דרך הרגיל קומט מען פנים בפנים מיטן נה\"ב וואָס איז משפיע אויפן שכל און מיטן יצה\"ר וואָס איז משפיע אויפן האַרצן.\nביידע — היצה\"ר והנה\"ב — לייגן זייערע גרעסטע פייהיקייטן אויף אַריינ­צונעמען דעם תלמיד אין אַן אייזערנעם קלעם, באופן אַז עס ווערט אים אומ­עגליך צו באַפרייען זיך, וממציא כמה וכמה דרכים באופנים שונים ומשונים, לפי טבע התלמיד, אם הוא בעל מרה שחורה וואָס נעמט יעדער זאַך אין שוואַרצע פאַרבן. לא מיבעי דעם עתיד, נאָר אויך אין דעם הוה איז באַ אים שטאַרק דעם הרגש אין דעם וואָס אים פעלט, און ניט אין דעם וואָס ער האָט יע רוכש געווען. ואם הוא בעל מרה לבנה, וואָס זעט יעדער זאַך אין ליכטיק­ווייסע פאַרבן איז די עובדא פון יצה\"ר צו ווייזן דעם הוה בכלל און דעם עתיד בפרט אין ווייסע­גליקליכע פאַרבן.\nאון דאָס אַלץ, סיי דעם וועמען דער יצה\"ר הויבט, און סיי דעם וועמען ער איז משפיל, איז מיט דער כוונה בכדי לדחותו ח\"ו מדרך האמיתי בדרכי העבודה, לדחותו ח\"ו מלהיות כפי הכוונה האמיתית העליונה וואָס איז דאָך אַז דער אדם זאָל צוקומען צום ריכטיקן תכלית פון ירידת הנשמה למטה בכדי צו מאַכן אַז דער מטה הגשמי זאָל ניט נאָר נזדכך ווערן, נאָר זאָל אויספירן כוונתו ית' אין עליית העולמות בעילוי אחר עילוי.\n* * *\nעוד זאת צריכים לדעת אשר גם תלמיד מצליח בלימוד ובהנהגה טובה צריך שימוש הרבה עד שיהי' ראוי להיות מחנך ומדריך, כפתגם הידוע בין אנ\"ש מימי קדם: אַ אַלטער חסיד איז מער בר­דעת ווי אַ יונגערמאַן אַ משכיל ועובד.\n* * *\nכבד לצייר ולפרט את סיבת הטעותים המונעים את צעירי התמימים והאברכים להתבונן בארחות חיי הבעלי ציור ובעלי עבודה הזקנים אשר ת\"ל זכו לראות את פני קדה\"ק הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"ם זי\"ע וזכו לשמוע מאמרי דא\"ח ושיחות הקודש, ומהם גם שזכו להיות ביחידות ונתברכו בהצלחה בעבודה מסודרת, כל אחד לפי מהותו בכחות נפשו ולפי אופן עבודתו במילוי סדרי ההנהגה בלימוד ועבודת התפלה, אבל בכל אופן הנה הי' להם במה להתעסק, וההתעסקות היתה על יסוד מיעוך ומילול הישות ומהות מעלת עצמו והכרת מעלת הזולת בכלל, והיוקר פון אַ עלטערן חסיד בכלל.\n* * *\nבכלל איז דער ירד ירדנו פון עדת החסידים בכלל און פון תלמידי התמימים בפרט טוט זייער וויי. און דאָס איז שווער אַרויסצוגעבן בדיבור. דער לבוש הדיבור האָט אַ מעלה און אַ חסרון. מעלת הדיבור איז וואָס ער איז מגלה, עס דער­קלערט אין אותיות הדיבור, דערפאַר זעהען מיר במוחש אַז אפילו לעצמו ווען מען לערנט אַ ענין עמוק, וואָס עס קומט אָן זייער שווער לעמוד על עמקי הסברות בכלל ובפרט, פיהלען דעם טוב טעם שכלי וואָס אין די סברות און פיהלען דעם חילוק פון איין סברא שכלית ביז דער צווייטער, מוז אַלץ זיין דורך דיבור. דער חסרון פון דיבור איז"],[4301620514,"וואָס דיבור איז הגבלה, עס איז פאַראַן אַ אָרט אין שכל צו דערקלערן פאַרוואָס איז אין דיבור פאַראַן מער געשמאַק ווי אין מחשבה, אין מחשבה איז מער דער געפיהל און אין דיבור איז מער דער געשמאַק, אָבער דער חסרון אין דיבור איז וואָס דיבור איז מגביל אין דער הגבלה פון ווערטער.\n* * *\nבאַ חסידי חב\"ד בכלל, און באַ תלמידי התמימים און בעלי עבודה בחסידי חב\"ד בפרט איז אַ חסידישער פאַרבריינגען אַ יסוד פנימי.\n* * *\nאין מיינע חינוך יאָרן האָב איך געזעהען די ריכטיקע בני ונכדי החסידים וועלכע זיינען געווען גליקליך צופרידן, ווען די עלטערע חסידים האָבן זיך מיט זיי אינטרעסירט.\nדי מחונכים האָבן זיך געפיהלט גוט, און מאנכעס מאָל גליקליך, מיטן קירוב פנימי פון אַ עלטערן חסיד.\nאָן אונטערשייד, צי אַ קירוב וואָרט פון אַ עלטערן חסיד אָדער אַ ירגזון וואָרט, האָט באַ דעם חסידישן מחונך אַרויסגערופן אַ גרויסע צופרידנקייט, וויסנדיק, אַז דורך דעם ווערט ער מער און מער מוכשר צו ווערן אַ כלי צו מקבל זיין דעם חב\"ד­חסידישן חינוך אין אַ פנימיות.\nיעדער סיפור האָט אַרויסגערופן באַ די מחונכים אַ בעזונדער בעגייסטערונג, עס האָט געווירקט אויף זייער לימוד און הנהגה כשרונות.\nאין אַזאַ חינוך­הנהגה איז דער חסי­דישער אינגל געוואַקסן אין זיינע פריה­עסטע קינדער יאָרן און איז געגאַנגען מדרגא לדרגא, געוואָרן אַ אב משפחה און מקים געווען אַ חב\"ד­חסידישע משפחה.\n* * *\nיעדער חב\"ד­חסידישער טאַטע אָדער זיידע האָט געלייגט דעם גרעסטן אַכט אויף דעם חינוך פון זייערע יונג פאַרהיירעטע קינדער אַז זיי זאָלן היטן די מנהגי חסידי חב\"ד ווי זיי און זייערע עלטערן.\nאין מיינע קינדער יאָרן האָב איך געהערט פון זקני החסידים וואָס זיי האָבן געהערט נאָך אין זייערע קינדער יאָרן באַ זייערע מלמדים, אַז די עלטערע חסידים זיינען די מילדות החסידים וואָס זיינען מגדל זייערע מחונכים אָט אַזוי ווי מען האָט זיי אַליין מגדל געווען.\nאַ עלטערער חסיד האָט געהאַט אַ חוב קדוש צו ליגן בטובת החינוך פון אַ יונגערמאַן, צו מגדל ומחנך זיין אים בדרכי החסידות; הן אין ידיעה והשגה אַז מען זאָל שטייגן אין אַ עלי' מן הקל אל הכבד, און הן אין עניני עבודה בתיקון המדות אַז מען זאָל גיין בסדר מסודר.\nאַ חב\"ד­חסידישער<sup data-n=\"1548\">5</sup> מחנך האָט קודם כל, געלייגט כל כחו, אויף דעם מחונך אויף דעם כיבוד — אויסקערן — הרפש הטיט ואבק היבש — טרוקענער — דער­נאָך אויף צו וואַשן מיט הייסע וואַסער און סקראָבען מיט אַ מעסער אַרויסצו­נעמען דעם בלוע, די טיף איינגע­וואַקסענע הנהגות וואָס קומט פון דער ביטער פינסטערער איינגעבאַקענער צרעת ממארת וואָס רופט זיך \"איך\".\n* * *\nזקני החסידים, בעלי עבודה בעבודת החינוך, וואָס האָבן נאָך זוכה געווען צו",[["1548","5","אַ חב\"ד­חסידישער: הדיוק בזה מבואר בשיחת פסח תרצ\"ד אות כ­כב."]]],[4301620515,"זעהען את מורנו הבעש\"ט בתחלת התגלותו פון דעם נסתרים­לעבן, און תלמידים הצדיקים הנסתרים הגאונים הר\"ר ברוך, אביו של רבנו הזקן ודודו הר\"ר יוסף יצחק<sup data-n=\"1549\">6</sup>, פלעגן איבערזאָגן אַ תורה­וואָרט וואָס זיי האָבן זוכה געווען צו הערן ממורנו הבעש\"ט.\nפתח רב מתיבתא<sup data-n=\"1550\">7</sup>, מאן דאיהו זעיר איהו רב, ומאן דאיהו רב איהו זעיר. רב מתיבתא מדייק בלשונו ומתחיל בסדר המסודר בעולם התיקון, אף דתהו קדם לתיקון, ובתהו יש ג\"כ הענין דזעיר ורב, אבל בתהו ההתחלה היא מהרב אל הזעיר, וכמו שאנו רואים במוחש דמי שטועה בדרכי עבודה, ובקטנותו הוא גדול, הנה גם בגדלותו נשאר קטן; ומאן דאיהו זעיר איהו רב, דבתיקון הסדר הוא מקטנות לגדלות, אַז בתחלת העבודה בעדאַרף מען פיהלען אַז מען איז אַ קטן, אַז דאָס וואָס מען פאַרשטייט איז אַ קטנות. דער עיקר איז הרגש — פיהלען.\nאון בכדי צו פיהלען מוז מען האָבן גאָר איין אַנדער הכשרה, און אָט די הכשרה האָט מען ווען מען איז אַ מקבל טוב פון עלטערע חסידים.\nדי זקני אנ\"ש ותלמידי התמימים, ה' עליהם יחיו<sup data-n=\"1551\">8</sup> וועלכע האָבן געהאַט אַ אזן שומעת און אַ עין רואה האָבן געהערט די טיף איינדרוקספולע סיפורים און גע­זעהען די פאַרפלאַמטע פנים'ער פון די זקני החסידים אין דעם ריקוד פון אַ התועדות ביומא דפגרא.\n* * *\nאין צוויי נוסחאות, אין צוויי באַזונדערע זמנים אין די קינדער יאָרן האָב איך זוכה געווען צו הערן מהוד כ\"ק אאמו\"ר הרה\"ק ווי ער האָט מבאר געווען די צוויי באַזונדערע סגנונות פון די אמרי קדש וואָס די זקנים וואָס האָבן נאָך זוכה געווען צו זיין באַ הוד כ\"ק המגיד ממעזריטש ומורנו הבעש\"ט, האָבן געהערט.\nמורנו הבעש\"ט האָט געזאָגט:\nדי טבילה אין מקוה און זיצן אין סוכה האָבן אַ שייכות<sup data-n=\"1552\">9</sup>, הן אין דעם הכשרת המקבל און הן אין דעם המשכת האור.\nדער מעזריטשער — אמר הוד כ\"ק אאמו\"ר הרה\"ק — זאָגט:\nמקוה איז מטהר און סוכה איז מעלה.\nאט די צוויי תורות וואָס הוד כ\"ק רבנו הזקן האָט מיטגעבראַכט מיט זיך קומענדיק דעם ערשטן מאָל פון מעזריטש<sup data-n=\"1553\">10</sup>, האָבן די זקנים געהערט פון רבינו הזקן און דאָס האָט זיי געהאַלטן בכל הדרוש להם עד יומם האחרון. פון זיי האָבן דעם רבינס קינדער בקטנותם און אויך די חסידים הראשונים אַ סך מקבל געווען.",[["1549","6","הר\"ר ברוך. . הר\"ר יוסף יצחק: אודותם בארוכה — ראה בספר הזכרונות ח\"א. שיחת ח\"י אלול תש\"ה. ועוד."],["1550","7","פתח רב מתיבתא: זח\"ג קסח, א. וראה המאמר דא\"ח ע\"ז בסוף קונטרס החלצו — רנ\"ט [סה\"מ תרנ\"ט ע' ריא ואילך."],["1551","8","לשון הכתוב — ישעי' לח, טז]."],["1552","9","מקוה. . סוכה: שייכות מקוה וסוכה י\"ל דמקוה הוא בחינת בינה (פע\"ח שער השבת פ\"ג. סידור בכוונת המקוה. לקו\"ת פ' ואתחנן תוס' ביאור ע\"פ וידעת פ\"ב. ועוד). ושייך למקיפים (לקו\"ת פ' תבוא סד\"ה תחת אשר), וסוכה היא מקיפים דבינה (זח\"ג רנה, ב בכתבי האריז\"ל. ודא\"ח בדרושי סוכות). — ולהעיר בתו\"א ר\"פ נח דהמבול כדוגמת המקוה מ\"ם סאה, ובד\"ה כי פדה ה' את יעקב (נדפס בלקו\"ת לג' פרשיות פ' נח [סה, א ואילך. ולאח\"ז — באוה\"ת נח ח\"ג תרסט, א ואילך]) ובהמשך וככה — תרל\"ז פצ\"ה ואילך — ביאור הצד השוה דסוכה ותיבת נח וההפרש שביניהם. ואכ\"מ."],["1553","10","[עוד דברים שאמר או עשה כשחזר ממעזריטש — ראה לעיל ע' 23 הערה 7. וש\"נ."]]],[4301620516,"הוד כ\"ק אאמו\"ר הרה\"ק האָט מבאר געווען באריכות אין יענעם פאַרבריינגען אָט די ענינים, וואָס דאַן האָב איך דאָס ניט געקענט באנעמען, און אויך החסיד ר' חנוך הענדיל<sup data-n=\"1554\">11</sup> האָט דאָס מיר ניט געקענט מאַכן צו פאַרשטיין, ערשט שפּעטער מיט יאָרן האָב איך זוכה געווען צו הערן ביאורים מפורטים באריכות ההסבר.\nאָט דאָס איז דער רכוש גדול וואָס דער חב\"ד­חסידישער מחונך זאַפּט אין זיך אַריין אין דעם חינוך זמן באַ די חב\"ד חסידישע מלמדים און חסידישע טאַטע מאַמע אין דער אַלטער קליינשטעטיל­דיקער מאָראַליש גליקליכער היים.\n* * *\nהוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק זצוקללה\"ה נבג\"ם זי\"ע וואָס האָט נאָך בנערותו געלייגט אַ שטאַרקע יגיעה צו זאַמלען די תורות פון מורינו הבעש\"ט וואָס געוויסע זקנים האָבן אַליין געהערט פון מורנו הבעש\"ט און מורנו הרב המגיד ממעזריטש, האָט אויפגעזוכט אייניגע זקנים וואָס האָבן דערציילט אַ סך ענינים וואָס זיי האָבן געדענקט פון דער צייט וואָס הוד כ\"ק רבינו הזקן איז אָנגעקומען צו זיין שווער אין וויטעבסק אויף קעסט. און פון די זקנים האָט ער געהערט אַז רבינו הזקן האָט דאַן מקבל געווען אַ תורה מכ\"ק דודו הנסתר הגאון הצדיק הר\"ר יוסף יצחק וואָס ער וגיסו הצדיק הנסתר הר\"ר ברוך האָבן געהערט ממורנו הבעש\"ט בתחלת התגלותו.\nעיקר החסידות איז תיקון המדות און מייקר זיין אַ פשוט'ן אידן, וואָס די עבודות זיינען די עליה­טרעפּ אין דעם דרך החיים, און צו גיין אויף טרעפּ בע­דאַרף מען האָבן אַ סיוע פון אַ עלטערן און דאַן איז דאָס אַ הילוך מסודר.\n* * *\nוהנה עוד רעה חולי ישנה אצל צעירי אנ\"ש שמסדרים עניני עבודתם ולימודם בעצמם, וכמובן שרובם טועים בדרכי העבודה, וכאשר בהזדמנות טובה מפק­חים עיניהם על איזה מהנהגותיהם שצריכים לתקן אזי נופל רוחם בקרבם ומקבלים עליהם כמה ענינים של סיגופים ועינוי הגוף.\nכי באמת המה חפצים להיות טוב, זיין ווי מען בעדאַרף זיין, ע\"פ הנהגת החסי­דים, אלא שטעו בזה וכשנודע להם טעותם הם מצטערים במאד, עס דער­נעמט זיי, וכנ\"ל אשר הנה\"ב לויערט אַריינצוכאַפן דעם מענטשן ולבלבל את דעתו, וואָס דורך דעם דערלאָזט ער ניט זיין תיקון, אשר ע\"כ צריכים להתחזק בכל מיני חיזוק אויף חלילה ניט אַריינ­צופאַלן אין זיין מצודה; ומי שנותן לבו ודעתו על זה איז מן השמים מרחמים עליו, וממציאים לו כל הענינים הדרושים להתפתחות דרכי עבודתו לעלות בשלי­בות סולם עבודת הקודש בהצלחה אמיתית.",[["1554","11","ראה אודותו לעיל ע' 17. וש\"נ]."]]],[4301620517,"<h3>אור ליום ד' יו\"ד שבט תש\"ט<sup data-n=\"1555\">1</sup></h3>\n<i>— יום היאָרצייט של הרבנית הצדקנית מרת רבקה נ\"ע<sup data-n=\"1556\">2</sup> — </i>\n<i>בעת ביקורם של המתעסקים בהחזקת ישיבות \"תומכי תמימים ליובאַוויטש\" </i>\n<i>לקבל ברכתו הקדושה של כ\"ק אדמו\"ר שליט\"א</i>\nאהבת ישראל, ליעב האָבן אַ אידן, איז אַ מצוה מן התורה, גלייך ווי אהבת השם יתברך און אהבת התורה.\nדי דריי נאהבים השם יתברך, תורה און אידן, זיינען גלייך אין דעם אופן ווי זיי דאַרפן געליעבט ווערן.\nאהבת התורה ליעב האָבן תורה, איז אין דעם ניט פאַראַן קיין אונטערשייד צווישען ליעבשאַפט צו חומש בראשית אָדער חומש שמות צי ויקרא במדבר ודברים, אָדער נביאים וכתובים. דאָס זעלבע איז אויך וועגן משניות, גמרא בבלי אָדער ירושלמי מדרשים און זהר.\nדי חז\"ל זאָגן<sup data-n=\"1557\">3</sup> אויף דעם פסוק (משלי ה'<sup data-n=\"1558\">4</sup>) אורח חיים פן תפלס וגו' אל תהי יושב ושוקל מצותיה של תורה. כולם מרועה אחד נתנו וא­ל אחד אמרם<sup data-n=\"1559\">5</sup>. און דערום זיינען אַלע תורה­ווערטער און דערקלערונגען באַ אַלע אידן גלייך מצד דעם נשמה­געפיהל.\nאין וואָס עס קען יע זיין, און עס איז טאַקע פאַראַן, אַ אונטערשייד באַ אידן, איז אין דעם שכל, אין דעם פאַרשטאַנד פון תורה, אין די דערקלערונגען אין די פרטי עניני המצות וואָס זיי בעדייטען, איינער פאַרשטייט מער, דער צווייטער ווייניגער. דאָס איז אָבער נאָר אין דעם פאַרשטאַנד פון תורה ומצות, אָבער מצד דעם נשמה­געפיהל זיינען אַלע אידן, פאַרשטייער און ניט פאַרשטייער גלייך.\nדי דערקלערונג פון דעם איז:\nשכל קען זיך איבערגעבן אין ווער­טער, געפיהל קען זיך ניט איבערגעבן אין ווערטער.\n* * *\nתורה איז שכל אלקי, געטלעכער שכל. תורה דערקלערט דעם געטלעכען שכל מיט אַזעלכע קלאָר דייטלעכע ביישפילן פון טאָג­טעגליכן לעבן וואָס דורכשניטליכע מענטשן פיהלן און איבערלעבן.\nאַזעלכע משלים און ביישפילן זיינען פון די גרעסטע ווערטפול און ווינטשונגס­ווירדיקע זאַכן אין תורה וחכמה פאַרשטאַנדן דאָס זיינען די ריכטיגע מיטלען ווי צו בריינגען די תורה ומצות פאַרשטאַנדן צו די ברייטע שיכטן פון עם ישראל, ה' עליהם יחיו<sup data-n=\"1560\">*5</sup>.\nיע, ריכטיג אַז עס איז פאַראַן אַ אונטערשייד פון הרגש — געפיהל — און השכלה — פאַרשטאַנד — וואָס באמת זיינען זיי צוויי בעזונדערע בעגריפן.\nאָבער להיות אַז לימוד התורה איז אַ מצוה מן התורה, וואָס דער בעגריף פון דער מצוה איז ידיעת התורה, צו פאַר­שטיין מיט שכל דורך געוויסע דערקלע­רונגען און ביישפילן, זיינען די משלים ביישפילן און די שכל­דערקלערונגען אַ וויכטיקער טייל פון תורה ומצות.\n* * *",[["1555","1","נדפס בלקו\"ד ח\"ג תקי, א."],["1556","2","ראה אודותה לעיל ע' 14. וש\"נ."],["1557","3","דב\"ר פ\"ו, ב. תנחומא עקב ב. ועוד."],["1558","4","פסוק ו."],["1559","5","ראה חגיגה ג, ב. במדב\"ר פי\"ג, טו­טז. ועוד."],["1560","*5","לשון הכתוב — ישעי' לח, טז."]]],[4301620518,"אָט דאָס וואָס דאָ איז אַרויס געזאָגט געוואָרן אין אַלגעמיינע קורצע הויפּט­שטריכן קען מען זיך אַליין מער אָדער ווייניגער דערקלערן מיטן ביישפּיל פון נגינה.\nאין נגינה זיינען פאַראַן פאַרשידענע טיילן, די ווערטער און דער געזאַנג פאַר זיך אַליין, כמאמר החכם<sup data-n=\"1561\">6</sup> הלשון קולמוס המוח והשכל, הקול קולמוס הלב וההרגש — די שפּראַך איז די פען פון דעם מוח, וואָס בעשרייבט דעם שכל, די שטימע איז די פען פון דער האַרץ און געפיהל.\nבכללות הייסט דאָס, אַז ווערטער און שטימע זיינען דאָס די וואָס פאַרעפנט­ליכן דעם געפיהל און דעם פאַרשטאַנד פון פנימיות הנפש.\nאין טאָג­טעגליכן לעבן זעהען מיר אַז דער וואָס פאַרטיידיגט זיך אָדער דעם צווייטן, איז ווען עס קומט צו דעם הויפּט פאַרטיידיגונגס מאָטיוו ווערט זיין אויס­זעהן ערנסט און זיין שטימע שטרענג, מיט איין אויסגעשריי.\nאין נגינה זעהען מיר, אַז איינער פיהלט די נגינה אַזוי און דער צווייטער אַנדערש, דאָס איז אָבער אַלץ באַ די וואָס הערן די נגינה, באַ דעם מנגן גופא אָבער — איז דאָך דער געפיהל איינער.\nדאָס זעלבע איז ווען מען הערט אַ שכל, איז איינער פאַרשטייט אַזוי און דער צווייטער אַנדערש, דאָס איז אָבער אַלץ באַ די וואָס הערן די נגינה, באַ דעם מנגן גופא אָבער — איז דאָך דער געפיהל איינער.\nנאָך אַ זאַך איז פאַראַן אין נגינה, עס טרעפט אַז עס זינגט זיך, און עס טרעפט אַז מען מוז זינגען, עס זינגט זיך גאָר ניט נאָר מען זינגט ווייל מען מוז זינגען. בכלל איז נגינה לפי מהלך הנפש, אָבער עס איז פאַראַן וואָס מען זינגט ווייל מען מוז זינגען, דאָס הייסט מען איז זיך מגביר אויף די געפיהלען. איז הגם אַ קינסטלער מנגן קען בעהאַלטן זיינע געפיהלן אָבער ער אַליין פיהלט אַז דאָס איז מער ניט ווי אַ הוראת שעה.\n* * *\nאיך זאָג דאָס קעגן דעם אַז מיר אַלע אידן וואָס לעבן אין דער לאַנד און אין די אַנדערע פרייע לענדער, וואו עס הערשט דער יושר פון מענטשן רעכט און אמונה רעכט, אַזוי ווי אין דער דאָזיקער לאַנד<sup data-n=\"1562\">7</sup>, זיינען מיר אידן מער ווייניגער איינגעאָרדנט און עס זיינען — ברוך השם — ניטאָ קיין שטערונגען אויף לימוד תורה וקיום המצות.\nמיר אַלע אידן, וואָס בחסד השי\"ת לעבן אין אַמעריקא און אין אַלע פרייע לענדער, בעדאַרפן תמיד געדיינקען און באַ יעדער פאַמיליען אָדער חברה פאַרזאַמלונג טאָן אַלעס מעגליכע צו ברענגען טרייסט און הילף צו דעם קערפּערליכן און גייסטיקן לעבן פון די פיעלע טויזענטער צובראָכענע אידן במדינות שונות וואָס זיינען נאָך ניט צוגעקומען צום ברעג. איז במילא זינגט זיך ניט. איך מיין ניט צו זאָגן דוקא איך, וואָס איך פיהל די אמת'ע אהבת ישראל,",[["1561","6","ראה — באו\"א — חובת הלבבות שער הבחינה פ\"ה. בחיי הקדמה לפ' בהר. מאירי אבות פ\"ה מכ\"א."],["1562","7","במהדו\"ק של השיחה: וואו דער הויפט פון דער רעגירונג איז פּרעזידענט טרומאַן<sup data-n=\"e31\">*</sup>, אַ מאמין אין דער געטליכער פירונג און שטרעבט צום וואוילזיין מענטשען אָן אונטערשייד פון גלויבן און קאָליר."],["e31","*","נשיא ארצות­הברית 1953­1945."]]],[4301620519,"איך מיין בכלל אַז אַלע אידן דאַרפן אַזוי פיהלן.\n* * *\nאיצטער האָבן מיר דעם פאַרגעניגן צו טרעפן זיך מיט די טייערע אורחים בעלי צדקה וחסד וואָס טוען מיט איבערגעגעבענקייט פאַר החזקת התורה בכלל און פאַר החזקה פון די — ברוך השם — פאַרצווייגטע ישיבת תומכי תמימים ליובאַוויטש בפרט.\nגעלויבט השם יתברך מען טוט פיעל, אָבער ניט וויפיעל מען דאַרף און וויפיעל מען קען טאָן.\nמען קען טאָן אַ סאַך מער, ווי למשל אַ גרויסע משא איז אַ סאַך מענטשן קענען זי זייער לייכט אויפהויבען<sup data-n=\"1563\">8</sup>.\nבאמת איז, אַז אין דערויף ליגט טאַקע די נאַרעריי און די פחד וואָס מען נאַרט זיך אָפּ און מען שרעקט זיך. ווען מען זאָגט אַז אויף אַ זאַך בעדאַרף מען האָבן הונדערט טויזנט אָדער אַ פערטל מיליאָן דאָללאר, ווערט מען דערשראָקן און מען נאַרט זיך אָפּ אַז מען קען דאָס ניט, אָבער באמת קען מען גאָר אַ סאַך אויפטאָן.\n* * *\nמיר האָבן זיך צופיעל צורעט וועגן געלט, מיר וועלן יעצט ריידן צום פּאָינט, כלשון אַמעריקא.\nאיינע פון די זאַכען וואָס מורנו הבעש\"ט נ\"ע האָט אויפגעטאָן איז אהבת ישראל, ליב האָבן אַ איד, ניט נאָר אַ גאון וצדיק, אַ חד בדרא, נאָר אַ איד אַלס אַ איד<sup data-n=\"1564\">9</sup>.\nדער בעש\"ט האָט אונז אויך גע­לערנט<sup data-n=\"1565\">10</sup> צו קוקן זיך צו דער השגחה פרטית וואָס איז דאָ אין אַלע זאַכן, אפילו אין דאָס וואָס מענטשן רופן קלייניקייטן, אַ שטרויעלע אפילו, וואָס ליגט אין גאַס און עס קומט אַ ווינט און טראָגט זי איבער פון איין אָרט אויפן צווייטן איז דאָס צוליב אַ כוונה פון השגחה פרטית, וואָס אַזוי איז אין אַלע בעשעפענישן פון דומם צומח חי מדבר ובפרט באַ אידן ובפרטי פרטיות באַ שומרי תורה ומצות ומחזיקי תורה — איז דאָך אַ ודאי און אַ ודאי אַלעס בהשגחה פרטית.\n* * *\nיעצט פיעל איך בעשיינפערליך אַ השגחה פרטית. עס איז געוואָרען פופציג יאָר זינד די ישיבה תומכי-תמימים איז געגרינדעט געוואָרן אין ליובאַוויטש.\nליובאַוויטש איז אַ קליין שטעטעלע מיט אַ סאַך קבצנים וועלכע האָבן געהאַט קוים ברויט מיט זויער מילך. דער וואָס האָט געקענט קויפן אויף שבת אַ קעלבערנע פיסל איז געווען פאַררעכנט פאַר אַ שיינעם בעל הבית.\nווען דער טאַטע נ\"ע האָט געמאַכט די ישיבה תומכי תמימים האָט ער דאַן ניט געוואָלט נעמען קיין געלט באַ דער וועלט, בכדי מען זאָל אים קיין דעות ניט זאָגן אין דער הנהלת הישיבה, איז געווען שווער צו אָרגאַניזירן די ישיבה. האָט אים זיין מוטער — אמי זקנתי הרבנית רבקה נ\"ע<sup data-n=\"1556\">2</sup> — געזאָגט: וואָס ביסטו זיך מצטער, וואָס מיר וועלן עסן וועלן זיי אויך עסן.\nאון אַזוי איז געווען. די וואָס זיינען צוגענומען געוואָרן אין דער ישיבה, האָט זיי זיין מוטער, הרבנית הצדקנית, מרת רבקה, געשפּייזט.",[["1563","8","ראה סוטה לד, א."],["1564","9","ראה לעיל ע' 40. וש\"נ."],["1565","10","ראה לעיל ע' 19. וש\"נ."],["1556","2","ראה אודותה לעיל ע' 14. וש\"נ."]]],[4301620520,"זעט אַלע די הייליגע געטליכע השגחה פרטית, היינט.\nמיט פופציג יאָר שפּעטער האָבן מיר זיך דאָ צונויפגעקליבן, אידן פון פאַרשידענע ערטער, אַלס אַזעלכע וואָס זיינען מחזיק די ישיבה אין וועלכער אמי זקנתי הרבנית הצדקנית מרת רבקה האָט מיט פופציג יאָר צוריק געגעבן צו עסן די ערשטע תלמידים פון דער ישיבה. און היינט איז איר — הרבנית הצדקנית מרת רבקה — יאָרצייט. זעט מען דאָך אין דעם ממש השגחה פרטית.\n* * *\nדי וואָס ווייסן די מאמרי חז\"ל וואָס בעשרייבן דעם שכר הנשמות אין גן עדן פאַר די מעשים טובים וואָס מען טוט אויף דער וועלט, און האָבן אַ פאָר­שטעלונגס­חוש, קענען זיי זיך, מער אָדער ווייניגער, פאָרשטעלן וואָס עס קומט פאַר היינט אין גן עדן, אין דעם יאָרצייט­טאָג פון דער הייליגער נשמה וואָס זי האָט מיט פופציג יאָר צוריק מעגליך געמאַכט די גרינדונג פון דער ישיבה תומכי-תמימים אין ליובאַוויטש.\nאַלע נשמות הקדושות פון די הייליגע רביים און צדיקים וואָס זיינען אין גן עדן זיינען ממליץ טוב און בעטן רחמי שמים פאַר די אַלע וואָס זיינען מחזיק און זיינען זיך מתעסק אין דער החזקת הישיבה תומכי-תמימים, פאַר זיי און פאַר זייערע בני בית, הצלחה ואריכות ימים.\nהשם יתברך זאָל געבן אַז דער זכות פון די רביים וצדיקים זאָל מגין זיין אויף די אַלע אידן, הם ובני ביתם, און אויך אויף דער ישיבה, זיי זאָלן אַלע וואַקסן בהצלחה: די ישיבה אין תורה און אויך אין גשמיות, די בעלי בתים אין גשמיות און אויך אין תורה."],[4301620521,"<h3>ליל ג' אדר תש\"ט<sup data-n=\"1567\">1</sup></h3>\nכ\"ק אדמו\"ר שליט\"א שאל אחד שביקרו לרגלי ענינו הפרטי\nוואָס מאַכט מען?\n— ענה: מען טרייט דאָס בעסט.\nע\"ז השיב כ\"ק אדמו\"ר שליט\"א: מען דאַרף וויסן וואָס מיינט דאָס בעסט, וואָס איז בעסט.\nהרב ק. — שנכנס עם הנ\"ל — אמר לכ\"ק שמר כ. הוא מגזע חב\"ד מסביבות עיר פאנעדעל.\nכ\"ק אדמו\"ר שליט\"א: פריער מוז מען געדענקען די היימיש­חסידישע מנהגים, ווי מען האָט זיך געפירט אין דער טאַטע­מאַמע'ס הויז, אין חדר באַ די חסידישע מלמדים, און אין די חסידישע מנינים און בתי מדרשים.\nעס איז זיכער אַז יעדע עראינערונג, וואָס אַ חסידישער מחונך דערציילט זיין פאַמיליע און באַקאַנטע, וועגן די איבער­לעבונגען אין טאַטע­מאַמע'ס היים אין חדר און בית המדרש, וועגן די יומא דפגרא'ס מיט די חסידישע סיפורים שמועסן און ניגונים, איז אַ דערפרישונג פאַרן זכרון און אַ זכות פאַר די עלטערן און די מלמדים וועלכע האָבן דערצויגן זייערע קינדער<sup data-n=\"1568\">2</sup> אין דרכי התורה והחסידות, און נוסף אויף די אַלע מעלות שטאַרקן די זכרונות די וואַרעמקייט פון",[["1567","1","נדפס מהעתק המזכירות מוגה בכי\"ק רבינו."],["1568","2","במהדו\"ק מהשיחה בכי\"ק רבינו: און תלמידים."]]],[4301620522,"דעם חב\"ד­חסידישן עמוד האור און דעם אַלגעמיין חסידישן עמוד האש, אַז די שלש אהבות, אהבת השם, אהבת התורה ואהבת ישראל זאָלן זיין די וועגווייזער אין דרכי החיים.\nאין פאנעדעל זיינען געווען אמתע חסידים.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל געזאָגט — שמחת תורה תרנ\"ב — אַלטע חסידים וואָס האָבין גיהאָרעוועט אין עבודת התפלה מיט אַ הכנה פאַרן דאַוונען און מיט אַ בפועל — בכן נאָכין דאַוונען האָבין געוואוסט וואָס מיינט אמת.\nדער חסידות'ער ביאור וואָס מיינט די דריי אותיות פון אמת: א איז דער אָנהויב פון די אותיות, מ איז דער אמצע פון די אותיות, ת איז דער סוף פון אותיות<sup data-n=\"1569\">3</sup>. דאָס מיינט אַז דער אור האמת זאָל דורכדרינגען אין אַלעס, אַז דער אָנהויב מחשבה, און דער דיבור וואָס ער איז מחבר מחשבה מיט דער מעשה בפועל, זאָלן זיין מיט אַ חיות פנימי ועצמי.\nאַמעריקאַנער אידן זיינען בעלי הרגש אין אַ טובה טאָן אַ אידישע געפאַלענע ר\"ל פאַמיליע אין גשמיות, אָבער דאָס רוב נאָר אַ טובה גשמיות, וועגן ענינים רוחניים איז מען מער ווי קאַלט, מען איז פאַר­גליווערט פון די קעלט, און מען איז צוטומלט פון דער גרויסער שאיפה נאָך דעם הון ועושר בביתו<sup data-n=\"1570\">4</sup>, אָבער דער וצדקתו לערנען און געבן צדקה איז עומדת לעד<sup data-n=\"1570\">4</sup>, שטייט אויף איין אָרט.\nאין דער אַלטער רוחניות­גליקליכע היים האָט זיך יעטווידער איינער משתדל געווען צו זיין איידעלער, צו קענען לערנען און טאַקע לערנען.\nעס זיינען דאַן אויך געווען חילוקי דרגות פון תלמידי חכמים און פשוטע אידן, אָבער דאַן איז יעדער איינער געלעגן אין דעם ווי אַ טובה צו טאָן אַ צווייטן. אהבת ישראל, טאָן אַ אידן אַ טובה, איז געווען אַ הויפּט זאַך באַ אַלע דרגות אידן, אָן אונטערשייד צווישן דעם למדן און דעם פשוטן תהלים זאָגער.\nדי תהלים זאָגער, איז ניט נאָר זיינען זיי געווען אמונה אידן, נאָר זיי זיינען אויך געווען בעלי מעשים טובים אידן וואָס האָבן זיך ניט בענוגנט נאָר מיט זייער תפילה בציבור און תהלים זאָגען.\nיעדערער לפי ערכו האָט זיך באַמיהט צו פאַרשטיין וואָס דער רבי לערנט פאַר זיי, צי משניות אָדער מדרש, עין יעקב אָדער גאָר אַ חסידישן סיפור און אַ חסידישן ניגון.\nאין דער אַלטער היים זיינען אין די בתי מדרשים געווען פאַרשידענע טישן, אַ דרום טיש, אַ צפון טיש. ביים צפון טיש פלעגן אידן לערנען אַ מאמר עין יעקב, אַ איד האָט זיך צוגעזעצט זאָגן אַ קאַפּיטל תהלים, אויף אַ צווייטן טיש האָט מען געלערנט גמרא, באַ דעם טיש זיינען שוין געזעסן לומדים און מען האָט זיך מפלפל געווען אין אַ מהרש\"א און אַ מהר\"ם שיף.\nעס זיינען אויך געווען אידן וועלכע זיינען אַריינגעלאָפן אין שול בלויז אָפּ­דאַוונען. אַליין האָט ער באַלאַנגט צו אַ אַנדער שול, נאָר אַזוי ווי די דאָזיקע שול איז נאָהענט צו זיין הויז פלעגט ער זיך אַריינכאַפּן אין דער שול אָפּדאַוונען, און ווען ער האָט געוואַשען די הענט ביים כיור האָט ער שוין געהאַלטן באַ ברוך שאמר, אַרויפגעדרייט די תפילין, אָפּגע­",[["1569","3","ראה ירושלמי סנהדרין פ\"א ה\"א. דב\"ר פ\"א, י. שהש\"ר פ\"א, ט (א)."],["1570","4","תהלים קיב, ג."],["1570","4","תהלים קיב, ג."]]],[4301620523,"זופט דעם דאַוונען און צו אשרי ובא לציון האָט ער שוין צוגעלייגט אַן אויער צו הערן וואָס הערט זיך אויף דער וועלט און אין שטעטל.\nאָט דער סאָרט מענטש איז געווען געקרוינט אין שטעטל מיטן צונאָמען דער טשיקאווער אָדער דער צודרייטער. ער האָט קיינמאָל קיין צייט ניט געהאַט, שטענדיק געווען צוטראָגן און פאַר­האוועט. ער האָט טאַקע געהאַט אַ נאָמען אין זיין שטעטל, אָבער וואָס פאַר אַ נאָמען.\nדער אמת איז אַז מען בעדאַרף טאָן אין עניני פרנסה אָבער מען מוז וויסן די ריכטיקייט און זיך אַליין אָפּגעבן אַ חשבון אויף דעם יסוד מוסד פון תורה ואמונה אַז מען קען ניט פאַרדינען קיין איין גראָשן מער וויפיעל עס איז באַשטימט לויטן דין ומשפט.\nמען בעדאַרף בעטן דעם אויבערשטן אַז דאָס וואָס מען פאַרדינט זאָל גיין למקום הראוי, פאַר זיך, פאַר די אייגענע בני בית און דער עיקר צו דערמעגליכן אַז אַנדערע זאָלן לערנען און זאָלן האָבן וואָס צו לערנען.\nנו, איז וואָס טוט איר אין דעם? וואָס טוט איר אויף?\nיעדער איד האָט פיר נעמען<sup data-n=\"1572\">5</sup>: אדם, איש, אנוש, גבר. די דאָזיקע פיר נעמען ווערן געטיילט אין צוויי סוגים. דער ערשטער סוג בעטאָנט דעם עצם המהות פון מוחין און מדות. אדם איז אַ כינוי פאַר שכל, איש איז אַ כינוי פאַר מדות. און גבר און אנוש בעדייטען און ערקלערען קלאָר און שאַרף דעם תוכן פנימי ועצמי פון אדם און איש, אַז יעדער איינער בעדאַרף טאָן אַלעס וואָס ער קען, הן אַליין און הן דורך גוטע פירער, מלמדים און רבנים, צו שטאַרקן דעם גבר, דעם תוקף אויף דער שוואַכקייט פון אנוש.\nדאָס איז די פליכט פון יעדער אידישן מחונך בכלל, און פון אַ חסידישן מחונך בפרט. אַ חסידישער מחונך מוז טאָן מיט זיך צו ווערן איידעלער. אַ טאַטנס אַ קינד, אַ זיידנס אַ אייניקל פון אַ חסידישער משפחה דאַרף האָבן דעם זכות פון אָפּדרוקן אַ ספר, צו זיין אַ מזכה את הרבים, כמו אָפּדרוקען דעם אַלטן רבינס שולחן ערוך.\nתורה איז דער אידישער מחנך­ספר, פון דעם טאָג וואָס די נשמה קומט אַראָפּ אויף דער וועלט און דאָס קינד ווערט געבאָרן, זיינע דערציהונגס יאָרן, ביז דעם יום האחרון וואָס די נשמה בעדאַרף זיך אומקערן אין הימעל פון דער שליחות אַרבעט וואָס מען האָט איר מזכה געווען דורכצופירן אויף דער וועלט.\nעס איז ידוע דעם הייליקן בעל שם טוב'ס מאמר וואָס ער האָט מבאר געווען דעם מאמר מנהגן של ישראל תורה היא<sup data-n=\"1573\">6</sup>, אַז יעדער מנהג טוב אין חיזוק התורה והמצות איז דער מנהג אַליין תורה<sup data-n=\"1573\">6</sup>, וואָס בריינגט אַ געוויסע פאַר­שטאַרקונג אין לימוד התורה און קיום המצות.\nאיינער פון די מנהגים טובים אין דער מדינה איז אַ משפחה צוזאַמענקונפט, וואָס מזמן לזמן קומען זיך צוזאַמען אַלע בני המשפחה מיט זייערע בני בית.\nדאָס איז זיכער אַ מנהג טוב אין אהבת אחים ואחיות, אָבער מען בעדאַרף די דאָזיקע צוזאַמענקונפטן אויסנוצן אויף דער ריכטיקער וועג און אויפטאָן וואָס",[["1572","5","ראה זח\"ג מח, רע\"א. לקו\"ת שה\"ש כה, א ואילך. סה\"מ תרכ\"ט ס\"ע קעא ואילך. תרל\"ה ח\"א ע' קצ ואילך. ה'ש\"ת ע' 96 ואילך. ועוד."],["1573","6","ראה לקמן ע' 338. וש\"נ."],["1573","6","ראה לקמן ע' 338. וש\"נ."]]],[4301620524,"עס איז נויטיק אויך אין רוחניות. איר בעדאַרפט בעאיינפלוסן און באַוועגן אייער משפחה צו נעמען איינטייל אין דעם. מען בעדאַרף זיך וועגן דעם צוזאַמענריידן מיט אייערע פיר ברידער.\nמר כ.: איך ווייס ניט ווי אַזוי איך קען דאָס באַווייזן.\nכ\"ק אדמו\"ר שליט\"א: אַ סוחר ווען עס שטייט אים פאָר אַ מסחר, ווערט ער שטאַרק נתפעל, למשל, ווען עס מאַכט זיך קויפן אַ זייער גרויסן געשעפט מיט אַ געוויסן גרויסן זיכערן פאַרדינסט, איז ביים אָנהויב טראַכט ער ווי וועט ער דאָס קענען דורכפירן, אָבער ווען ער זעצט זיך אַוועק און נעמט אַ ?לייפעדער<sup data-n=\"1575\">7</sup> און מאַכט אַ חשבון אַז היינט קען ער געבן אַזויפיעל, אין אַ חודש אַרום אַזויפיעל, און מען האָפט לרחמי שמים אַז ער ברוך הוא וועט העלפן. און אַזוי איז אויך אין דעם ענין, פריער אָפּדרוקן איין חלק, נאָכדעם אַ צווייטן, און אין אַ משך פון חדשים קען מען די זאַך דערווייזן צו פאַרענדיקן.\nמען דאַרף האָבן אַ התעוררות הלב צו מקבל זיין די ברכה פון רבין. עס בעדאַרף זיין אַ איידלקייט אין שכל צו פאַרשטיין דעם עונג הנשמה בגן עדן.\nמר כ. מבקש שיעזרו לו למצוא עוד שותפים לזה.\nכ\"ק אדמו\"ר שליט\"א: אַ טאַטע העלפט אַ קינד ווען ער טוט אַ גוטע זאַך. איך בין ניט אויסן נאָר די גשמיות פון דעם, איך בין אויך אויסן אַז גזע החסידים זאָלן זיין בעלי זכות. איך ווינטש אייך אַז איר מיט אייערע ברידער יחיו זאָלן האָבן דעם גרויסן זכות און זיין געבענטשט בגשמיות וברוחניות.\nהשם יתברך זאָל זיך מרחם זיין אויף אונז אַלעמען און אויף כלל אחינו בית ישראל בכל ארצות פזורינו און זאָל אונז שיקן דעם גואל צדק משיח צדקנו במהרה בימינו, אמן כן יהי רצון.",[["1575","7","במהדו\"ק משיחה זו: מיט פּאַפיר."]]],[4301620525,"<h3>[ו' אדר תש\"ט]</h3>\nצום אָבשלוס פון אייער רעדען נעכטען האָט כ\"ק אדמו\"ר שליט\"א אייך געוואונשען איר \"זאָלט זיין אַ גרף ראשי תיבות: גוט רייך פרום\"<sup data-n=\"1576\">1</sup>.",[["1576","1","הועתק ממכתב ז' אדר תש\"ט להר\"י כ\"ץ — אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' פא ואילך. וממשיך באגרות­-קודש שם:\n(גרף אין אידיש ברוסלאַנד — איז אַן עהרען טיטול וואָס מיינט לערך אין ענגליש).\nניט זייענדיק זיכער, אַז איר האָט פאַנאַנדער­געקליבען די אויבענדערמאָנטע ווערטער בין איך עס דאָ מעתיק. און בטח וועט איר זיך משתדל זיין צו זיין אַ כלי צו דער ברכה.\n.. . אולי אפשר לבאר הסדר בהברכה:\nגוט — עבודת הצדקה, וזהו הקדמה והכנה להברכה. . .\nרייך — וכמאמר רז\"ל (תענית ט, א) עשר תעשר בשביל שתתעשר. והן בגשמיות עשיר כפשוטו והן בפנימיות דאין עשיר אלא בדעת וכמרז\"ל (נדרים מא, א) דדא (דעת) בי' כולא בי'. וזהו הקדמה והכנה להברכה. . .\nפרום — דעל ידי העשירות בדעת מתבונן כדבעי ובא לאהבה את ה' וליראה אותו, וכמו שמבאר בתניא באריכות, ואז הוא רוצה חפץ לילך בדרכי השי\"ת שביארו רז\"ל (רמב\"ם הלכות דעות פ\"א, הלכה ה­ו): והלכת בדרכיו כך למדו בפירוש מצוה זו מה הוא נקרא חנון אף אתה הי' חנון כו'. ועל ידי העשירות כפשוטו, הוא גם יכול לקיים בפועל חפצו ורצונו זה."]]],[4301620526,"<h3>יום ג', ז' אדר תש\"ט<sup data-n=\"1577\">1</sup></h3>\nא. בתיבת נח הי' חיות טהורות וטמאות, מי שקולטתו התיבה וכו'<sup data-n=\"1578\">2</sup>. בטומאה יש טומאה דחוי'<sup data-n=\"1579\">3</sup> וטומאה עולמית<sup data-n=\"1580\">4</sup>, בתיבת נח כתיב<sup data-n=\"1581\">5</sup> ומן הבהמה אשר לא טהורה, היינו שה\"לא\" יתהפך לטהור, וזה ע\"י שטף מים חיים, מים בכלל מטהרים, ובפרט מים חיים.\nב. אַמאָל אין ליובאַוויטש האָט מען אַ סאַך פאַרברענגט. הגם שלא היו משכילים גדולים כ\"כ, מ\"מ איז מען געוואָרן דורכגעווייקט מיט טרערן, היינו שכל הגוף עד הרגלים איז געוואָרן דורכגעווייקט אין טרערן. עס האָט זיך דערהערט, דער האָלט האָבן אַ אידן.\nג. כ\"ק אדמו\"ר מהר\"ש נבג\"מ זי\"ע, אמר בשם כ\"ק אדמו\"ר הצ\"צ נבג\"מ זי\"ע, על החסיד ר' גרשון בער נ\"ע<sup data-n=\"1582\">6</sup>, שבכל ענין באמרי בינה הי' בדרך ואתהלכה ברחבה, ומ\"מ נאָכן דאַוונען מעריב צוויי שעה, און נאָכן לייענען קשעהמ\"ט עטליכע שעה, איז פאַרן צולייגען זיך, האָט ער געזאָגט: מען דאַרף אויפשטיין אַן אַנדערער<sup data-n=\"1583\">7</sup>.\nד. היינט איז אינגאַנצן אַנדערש, ביז עס קען פאָרקומען אַזעלכע ענינים וואָס אין מתנגדישע ישיבות איז דאָס אַ חידוש. מען קלאַפּט יעדען אין פּלייצע. באם מוכרח מוז מען אַמאָל אַרויסוואַרפן אויך. אַמאָל האָט מען אַריינגינומען מיט האַרץ, און דער אַרויסוואַרפן איז אויך געווען מיט האַרץ.\nה. נחוץ לעשות אסיפות מזמן לזמן יחד עם המשפיעים הרה\"ח הרש\"ל<sup data-n=\"1584\">8</sup> והרי\"ד<sup data-n=\"1585\">9</sup> שיחי', ולסדר מה שאפשר לתקן בכלל, וגם לדבר ע\"ד פרטי התלמידים. ומה שדרוש לכל תלמיד בפרט, ולרשום זאת בכתב, ולהשגיח אם נתתקן הדבר, וגם לשמוע מהר\"מים והמלמדים דו\"ח מעבודתם ומה שנחוץ לתקן.\nו. נחוץ להשגיח על התלמידים ולדבר עמהם ע\"ד הנקיון<sup data-n=\"1586\">10</sup>, הן נקיון השיניים, והן נקיון הבגדים, ולהסביר להם זאת איך שהוא ע\"פ השו\"ע.",[["1577","1","מרשימת הרב מרדכי מענטליק<sup data-n=\"e32\">*</sup> \"ר\"ד מה ששמעתי מכ\"ק אדמו\"ר שליט\"א\"."],["1578","2","ראה סנהדרין קח, ב."],["1579","3","ראה יומא ו, ב. ובכ\"מ."],["1580","4","ראה תוספתא נגעים פ\"ד, ג. ובכ\"מ."],["1581","5","נח ז, ב."],["1582","6","ראה אודותו לעיל ע' 5. וש\"נ."],["1583","7","ראה לעיל שם. וש\"נ."],["1584","8","ר' שמואל לעוויטין. — ראה לעיל ע' 9. וש\"נ."],["1585","9","ר' ישראל דזייקאָבסאָן. — ראה לעיל ע' 59. וש\"נ."],["1586","10","ראה אגרות­-קודש ח\"ד ע' צא ואילך."],["e32","*","ראש ישיבה דישיבת תומכי­תמימים ליובאַ­וויטש המרכזית בארצות­הברית מיום הווסדה. נפטר כ\"ה תשרי תשמ\"ח."]]],[4301620527,"<h3>פורים תש\"ט</h3>\nא. עס איז פאַראַן ענינים וואָס עס איז דאָ געוויסע זמנים וועלכע מ'דאַרף זיי ריידען, מ'דאַרף זיי ריידען שאַרף, אָבער מען מוז דאָס ריידען קורץ, ד.ה. קורץ און שאַרף.\nדי התחלה פון תורה איז די ליידיגע, די שיטות פנויות<sup data-n=\"1587\">1</sup>. תורה איז אותיות, אותיות פון תורה, אידען קויפן אותיות פון תורה, יעדער אות איז אַ עולם מלא, יעדער איד איז אַ תורה שלימה, אידען און תורה איז איין זאַך<sup data-n=\"1588\">2</sup>.\nדי התחלה פון תורה איז די ליידיגע, ליידיג פון וואָס עס מאַכט פול, ווי מיר זעהן בגשמיות ביי אַ כלי, זי איז ליידיג פון אַ אַנדער זאַך וואָס מען פילט אָן.\nחומריות איז גראָ?, גשמיות קען מען מתקן זיין<sup data-n=\"1589\">3</sup>. מיר זעהן ביי אַ מאכל שלא נתבשל מאַכט דער מאכל פול. אַז מען עסט אַ מאכל שנתבשל און דער מאכל ווערט נתעכל, ווערט ער דורך דעם מאכל נתחזק — דער חלוש ווערט אַ גבור, וואָס קודם האכילה איז ער אַ חלוש און דער מאכל איז אַ נתינת כח וואָס דער חלוש ווערט אַ גבור, אָבער אַ מאכל שאינו מתעכל איז לא די וואָס עס מאַכט פון אַ גבור אַ חלוש — מאַכט דאָס איהם נאָך פאַר אַ חולה.\nאין עבודה איז דאָס: עס איז דאָ ג' נפשות, נפש הבהמית, נפש השכלית און נפש האלקית. מיט דעם נפש הבהמית קען מען גאָר ניט מאַכן<sup data-n=\"1590\">*3</sup>, אים קען מען ניט מתקן זיין. מ'האָט פון איהם בויך­ווייטאָג, האַרץ­ווייטאָג און קאָפּ­ווייטאָג.\nדער יצה\"ר איז אַ חכם<sup data-n=\"1591\">4</sup> להרע<sup data-n=\"1592\">5</sup>, ער מאַכט איהם פאַר אַ צדיק, אַ תמים; מ'דאַרף זיך שטעלן מיט אַ תוקף און זאָגן צום יצה\"ר: איך קען דיך מיט אַלע דיינע חכמה'לעך וואָס דו ווילסט מיך אַריינ­אַרען.\nדעם יצה\"ר דאַרף מען אינגאַנצען אַרויסוואַרפען. מיט דעם נפש הבהמית קען מען עפּעס מאַכן ער זאָל זיין אַ כלי צום נפש האלקית אויף קענען אויספירען די כוונה פנימיות פון תכלית ירידת הנשמה למטה.\nב. איך האָב שוין עטליכע מאָל דער­ציילט<sup data-n=\"1593\">6</sup> פון מיין יומן, פון מיינע קינדערישע יאָרן, דאָרט איז דאָ אַ חלק מיט דעם נאָמען \"וואָס געדענקסטו\".\nדער טאַטע פלעגט מיך פרעגען \"וואָס געדענקסטו\" בכדי אָפּ­פרישען מיר דעם זכרון.\nבמשך הזמנים פלעגט ער מיר מבאר ומסביר זיין דבר דבר על אופנו וואָס ער האָט ביי מיר געפרעגט און דעם ענטפער.",[["1587","1","ראה שיחת פורים תש\"ד (ספר השיחות תש\"ד ע' 66): \"יעדער זאַך דאַרף האָבען אַ הקדמה. די הקדמה צו תורה שבכתב איז דער לובן פון די ד' שיטין, אַ אור פון העלם העצמי וואס קען ניט נתגלה ווערן אין אותיות\". ובהערת כ\"ק אדמו\"ר נשיא דורנו (\"היום יום\" ח\"ב (קה\"ת, תשנ\"ח) ע' יד): \"צ\"ע שזהו רק בין ספר לספר משא\"כ בתחלת הס\"ת, ואולי צ\"ל הגליונות שלמע' ושלמטה?\". וראה לקמן ע' 320. ע' 383. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 139."],["1588","2","ראה זח\"ג עג, א."],["1589","3","ראה סה\"מ תש\"ו ע' 58."],["1590","*3","ברשימת השיחה שתח\"י כ' המניח: כנראה הכוונה על היצה\"ר."],["1591","4","ע\"פ ירמי' כד, יב."],["1592","5","ראה פרקי דר\"א פי\"ג. וראה גם לעיל ע' 115. וש\"נ."],["1593","6","ראה לעיל ע' 41. וש\"נ."]]],[4301620528,"דאָס פרעגן איז געווען בכדי עס זאָל ביי מיר בלייבן די תמונה פון די זאַך, ווייל דאָס איז פון די זמנים וואָס איך בין נאָך ניט שייך געווען צו וויסען די ענינים, און שפּעטער פלעגט ער מיר מבאר זיין דבר דבר על אופנו.\nדער טאַטע האָט מיר מבאר געווען אַז דאָס איז על דרך ווען איינער איז מצייר אַ ציור, איז קודם ער מאַכט דעם ציור מיט אַלע גוונים, מאַכט ער פריער די כלליות'דיגע קוין פון דעם ציור אָן די פאַרבן, וואָס פון די קוין בעשאפט ער דעם חומר פון די זאַך, נאַכהער מאַכט ער די פרטי הציור מיט די פאַרבן וואָס דאָס איז די צורה.\nפריער איז דאָס געווען אַ חומר אָן לעבעדיגקייט און איצטער גיט ער אַריין דעם לעבן.\nפריער איז געווען התגברות החומר על הצורה, און איצטער איז ניט נאָר וואָס ער גיט אַריין אַ לעבן אין ציור נאָר עס איז אויך התגברות הצורה על החומר.\nעס פלעגט זיין אַ סדר ווען דער טאַטע פלעגט זיין אויף יחידות ביים זיידען איז נאָך יעדע יחידות פלעגט ער איהם דערציילען עטליכע סיפורים<sup data-n=\"1594\">7</sup>, עס זיינען אויך געווען סיפורים וואָס ער האָט געהערט פון דעם רבי'ן דער צ\"צ, וואָס דער רבי דער צ\"צ האָט געהערט די סיפורים פון אַלטן רבי'ן ווען ער איז נאָך ניט געווען שייך צו הסברה און דער שווער — דער מיטעלער רבי — פלעגט דאָס איהם מסביר זיין.\nאיינע פון די סיפורים איז: פורים איז על שם הפור<sup data-n=\"1595\">8</sup>; וואָס איז פור אַליין? און אויב על שם הפור, פאַרוואָס איז דאָס ניט פור נאָר פורים<sup data-n=\"1596\">9</sup>?\nנאר דער ענין איז: פור איז עצם, פורים איז התפשטות — אַזאַ התפשטות וואָס איז מגלה דעם עצם; עס איז פאַראַן התפשטות וואָס איז מעלים על העצם, דאָ די התפשטות איז מגלה דעם עצם.\nנאָך וואָס דאַרף מען פור?\nהמן האָט געוואָלט דעם פור — דעם עצם. המן איז געווען דער אמת'ער תלמיד פון נחש הקדמוני, ער האָט געוואָלט מ'זאָל זיך בוקן צו אים מצד עבודה זרה, ניט צו עבודה זרה מצד אים.\nוואָס איז די סגולה לזה? מיט וואָס האָט מען אים געבראָכן?\n— מיט דעם איש יהודי<sup data-n=\"1597\">10</sup>, ניט מיט מרדכי הצדיק, נאָר איש יהודי, אַ האַרציגער איד.\nעס איז דאָ איש, איש יהודי, און צדיק. צדיק איז מצד המוחין, ער ווייסט אַלע ענינים וואָס די נשמה פאַרמאָגט,\nעס איז דאָ אַ בעל לב, אַ האַרציגער, ער איז גאָר ברוגז אויף מוחין, אויף וואָס דאַרף מען מוחין.\nעס איז דאָ תורה ותפלה. תורה איז השכלה והשגה, תפלה איז האַרץ, אין תפלה איז אויך דאָ השכלה והשגה, אָבער דער עיקר איז האַרץ.\nמיט תורה קען מען המן ניט צוברע­כען. אין תורה איז פאַראַן יודעי תורה, לומדים, לומדים מופלגים. אַזעלכע וואָס דעם רבינו תם מאַכט ער אויס למדן, דעם ריב\"א פאַר אַ ניט פאַרשטייער, דעם רשב\"א באַהאַלט ער אין קעשענע, רש\"י",[["1594","7","ראה גם שיחת יום אחש\"פ שנה זו (לקמן ע' 325)."],["1595","8","אסתר ט, כו."],["1596","9","ראה גם אוה\"ת מגילת אסתר (קה\"ת, תש\"נ) ע' קסח. ע' קצד. ועוד."],["1597","10","אסתר ב, ה."]]],[4301620529,"זאָגט אַזוי און ער זאָגט אַזוי. אַז ער וויל מאַכט ער אַ גרייז אין די גמרא, אין רש\"י — באמת איז דער גרייז אין אים נאָר ער לייגט אַריין דעם גרייז אין גמרא און רש\"י. ער זאָגט אַזוי: דעם חידוש האָב איך שוין געזאָגט פאַר גאונים, זיי האָבן אפילו מבטל געווען אָבער זיי האָבן מיר אָפּ'געפרעגט מיט העזה און איך האָב זיי אָפּ'געפרעגט<sup data-n=\"1598\">11</sup> דעם תוספות מיט חכמה. דאָס איז \"המן מן התורה\"<sup data-n=\"1599\">12</sup>, מיט תורה אַ המן.\nפטר'ן המן'ען איז נאָר דורך דעם איש יהודי, אַ פשוטער איד, מיט מסירת נפש, אַ קאַפּיטל תהלים, אַ פשוטער איד אַ דאָרפס איד מיט זיין קאַפּיטל תהלים פטר'ט ער אַוועק המן'ען.\nנאָך דעם האָט מען געמאַכט די קביעות פון זאָגען תהלים, אויף צו ברעכען דעם המן שבכל דור ודור.\nמיר האָבן אסך המן'ס, און ברעכען זיי איז דער איש יהודי מיט אַ האַרציג קאַפּיטל תהלים, לא בחרב ולא בחנית כי אם ברוחי<sup data-n=\"1600\">13</sup> — מיט אַ האַרציג קאַפּיטל תהלים.\nדער כלל ישראל דאַרף האָבן רחמים רבים. מ'קען ריידן אין דעם בארוכה נאָר אַז מען רעדט בארוכה קען מען דאָך זאָגן אַ סאַך פשטים, הגם אַלע פשטים זיינען אמת, אָבער מ'דאַרף וויסן און ניט ריידן.\nדער אויבערשטער זאָל העלפן מיר זאָלן זוכה זיין צו גילוי המשיח און ער זאָל אונז פירן בחסד וברחמים אין ארץ אבותינו הקדושה תבנה ותכונן.\nג. מ'האָט שוין אַמאָל גערעדט אין דעם<sup data-n=\"1601\">14</sup>, כל בעלי השיר יוצאין בשיר ונמשכין בשיר<sup data-n=\"1602\">15</sup>, אַז מען זינגט אַ ניגון, אַ פנימיות ניגון, וואָס אַ רבי האָט דעם ניגון געזונגען, דער רבי האָט אים מחבר געווען, אָדער ער האָט מיט דעם ניגון געדאַווענט, ער האָט מיט אים אויס­געטאָן.\n— ביים זיידן פלעגט זיין ניגונים ווען ער פלעגט אויסטאָן די בגדי חול און אנטאָן די בגדי שבת, און אויסטאָן די בגדי שבת און אָנטאָן די בגדי חול<sup data-n=\"1603\">16</sup>, און די אַלע בגדים זיינען געווען זיידענע<sup data-n=\"1604\">17</sup> —\nאיז דער רבי אין זיין היכל אין ג\"ע מיט אַלע חסידים און באי כחו, הערן דעם ניגון און זינגען מיט.\nעס איז ידוע די מעשה ביים צ\"צ ווען מ'האָט געזונגען דעם רבי'נס ניגון האָבען זיך אַלע אַרומגעקוקט ווי דער רבי איז דאָ<sup data-n=\"1605\">18</sup>.\nעס איז ניט מער וואָס ביי אונז איז פאַרשטאָפּט די כלי השמיעה, אָבער צוליב דעם וואָס דער טויבער הערט ניט און דער בלינדער זעט ניט איז דען דער דבר הנראה והנשמע ניט פאַראַן<sup data-n=\"1606\">19</sup>?\nאיז ווען מען זינגט אַ רבי'נס ניגון קען מען בעטן, דאָס איז אַ זמן פון יחידות.\n(וצוה כ\"ק אדמו\"ר שליט\"א לנגן",[["1598","11","ברשימה אחרת: געזאגט."],["1599","12","חולין קלט, ב."],["1600","13","ע\"פ שמואל­א יא, מז. זכרי' ד, ו."],["1601","14","ראה ספר השיחות קיץ ה'ש\"ת ע' 160. ספר השיחות תש\"ב ע' 134. ועוד."],["1602","15","משנה שבת נא, ב."],["1603","16","ראה שיחת כ' כסלו תרצ\"ד ס\"ה (לקו\"ד ח\"א קג, א). ספר השיחות תש\"ד ע' 95."],["1604","17","ראה גם רשימת היומן קיץ תרצ\"ה (\"רשימות\" חוברת קפב ע' 15)."],["1605","18","ראה לעיל ע' 146. וש\"נ."],["1606","19","להעיר מספר השיחות תרפ\"ח­תרצ\"א ע' 21."]]],[4301620530,"קודם הניגון של ד' הבבות מאדמו\"ר הזקן, ניגון של כ\"ק אדמו\"ר הרה\"ק נ\"ע — דעם טאַטענס ניגון. ואח\"כ הניגון שכ\"ק אדמו\"ר הרה\"ק נ\"ע התפלל עמו, ואח\"כ הניגון של ד' הבבות. בעת הניגון הזה, הנה כ\"ק אדמו\"ר שליט\"א ניגן ג\"כ אותו בדביקות גדולה ובכה הרבה בבכיות עצומות).\nד. אַלע אידן ווייסן, דאָס איז אַ הנחה עצמית, אָפּגעלייגט, אַז בנים אתם<sup data-n=\"1607\">20</sup>, בני בכורי ישראל<sup data-n=\"1608\">21</sup>.\nאַ טאַטע, אַ געטרייער טאַטע, האָט האָלט זיינע קינדער, לבד זה וואָס דער טאַטע איז זיך מצטער ווען דעם קינד פעלט עפּעס, איז זיין גאַנצער ענין אויף גורם זיין דעם קינד אַ קורת רוח.\nאפילו ווען דער קינד איז ניט ווי ער בעדאַרף זיין, פּאַטשט ער אים ניט, ער ווייס אַז מיט פּאַטשען מאַכט מען ניט, ער ווייס אַז ער איז ניט שולדיג, נאָר די סביבה איז גורם, די שלעכטע חברים, א. א.\nער נעמט אים צו זיך און זאָגט אים: וואָס גלייכסטו זיך צו זיי, זיי זיינען דאָך שקצים וואָס גייען אין גאַס און רייסן אָפּ אַן עפּל און חאַפּן אָן אַ ברכה, דו גייסט דאָך אין חדר, טראָגסט ציצית, מאַכסט ברכות, אַז דו וועסט בעזר השי\"ת ווערן אַ בר מצוה וועט מען דיר מצרף זיין צום מנין, ניין אידן וועלן זיין אין שול און מ'וועט ניט קענען זאָגן אַ דבר שבקדושה און דו וועסט משלים זיין דעם מנין צו קענען זאָגן אַ דבר שבקדושה, דאָס איז דאָך אַ זאַך. מיט דעם הויבט ער אים אויף, ער זאָל באמת בעסער ווערן.\nדער אויבערשטער איז זייער אַ גע­טרייער טאַטע, אָבער אידן האָבן צופיל נסיונות.\nעס איז שוין העכסטע צייט<sup data-n=\"1609\">22</sup> עס זאָל זיין גילוי המשיח, מיר ווילן אָן קאָמבי­נאַציעס.\nאַליין גייט מען ניט, דער וואָס האָט אונז געפירט אין גלות דער דאַרף אונז אַרויסנעמען.\nאיך וויל ניט ריידן אין דעם, עס איז ניט מיין עסק, דער אויבערשטער זאָל שיקן משיח צדקינו און צונויפנעמען אַלע אידן ווי זיי זיינען, בחסד וברחמים, און אונז פירן אין ארצנו הקדושה תבנה ותכונן<sup data-n=\"1610\">23</sup>.\n(צוה לנגן הניגון ניע זשוריצי חלאָפּצי, וכל המסובים הלכו בריקוד בשמחה רבה. ואח\"כ אמר: אַ גוטן יום טוב).",[["1607","20","פ' ראה יד, א."],["1608","21","שמות ד, כב."],["1609","22","ראה שיחת ש\"פ משפטים תשנ\"ב (ספר השיחות תשנ\"ב ח\"ב ע' 363)."],["1610","23","ברשימה אחרת: עס איז שוין העכסטע צייט אַז ער זאָל שיקן משיח דעם גואל צדק, און ער זאָל אונז פירן אין ארץ אבותינו הקדושה באמת אן קאָמבינאַציעס.\nאיך וויל ניט ריידן אין דעם, עס איז ניט מיין עסק. . . ער האָט אונז געשיקט אין גלות און ער וועט אונז אַרויסנעמען פון גלות, אַליין גייט מען ניט. דער אויבערשטער זאָל העלפן אַז אידן וואו זיי זיינען זאָלן קענען גיין מיט משיח'ן אין ארץ אבותינו ת\"ו."]]],[4301620531,"<h3>יום חמישי פ' כי­תשא, ט\"ז אדר תש\"ט<sup data-n=\"1611\">1</sup></h3>\n<h4>— בעת מעמד קבלת אזרחות ארצות הברית<sup data-n=\"1612\">2</sup> —</h4>\nבקשר למעמד זה — איתא במדרש<sup data-n=\"1613\">3</sup> שכאשר נצטוה אברהם אבינו<sup data-n=\"1614\">4</sup> \"לך לך מארצך וממולדתך ומבית אביך אל הארץ אשר אראך\"<sup data-n=\"1615\">5</sup>, הנה — \"בשעה שהי'.. מהלך בארם נהרים.. ראה אותן אוכלים ושותים.. אמר הלואי לא יהא לי חלק בארץ הזאת.. כיון שהגיע לסולמה של צור ראה אותן עסוקין בניכוש.. בעידור.. אמר הלואי יהא חלקי בארץ הזאת, אמר לו הקב\"ה<sup data-n=\"1616\">6</sup> לזרעך אתן את הארץ הזאת\".\nועד\"ז בנדו\"ד — לאחרי כל ההליכות ונידודים ממקום למקום, ממדינה",[["1611","1","נדפס בספר ימי בראשית (קה\"ת, תשנ\"ג) ע' 39."],["1612","2","בשעה אחת וחצי אחה\"צ הגיעה ל\"770\" משלחת משפטית מיוחדת מטעם ממשלת ארצות­הברית<sup data-n=\"e33\">*</sup> שבה השתתפו השופטים מר ירוחם פישל קליינפעלד<sup data-n=\"e34\">**</sup> ומר לייב רייפל; העו\"ד — מר יקותיאל קרעמער; שני פקידים הראשיים של מחוז \"קינגס­קאונטי\". ועוד.\nרבינו קיבלם בחדרו הקדוש (חדר ה\"יחידות\"), לבוש בגדי משי וחבוש ב\"סויבלענע היטל\", כשעל ידו עומד חתנו כ\"ק אדמו\"ר נשיא דורנו*<sup data-n=\"e35\">***</sup>.\nרבינו חתם על מסמכים שונים. לאחרי קבלת תעודת האזרחות, פתח ואמר [ההמשך בפנים]:"],["1613","3","ב\"ר פכ\"ט, ח. וראה לקו\"ש חט\"ו ע' 93."],["1614","4","לך לך יב, א."],["1615","5","להעיר מ\"היום יום\" א' חשון (אגרות­-קודש ח\"ד ע' שמא): \"מאז שאמר הקב\"ה לאברהם אבינו ע\"ה לך לך מארצך גו'. . הותחל סוד הבירורים. וע\"פ גזירת ההשגחה העליונה האדם הולך למסעיו במקום אשר הניצוצות הצריכים להתברר על ידו מחכים לגאולתם. הצדיקים שהם בעלי ראי' רואים הם באיזה מקום הבירורים שלהם מחכים להם והולכים שמה בעצמם\"."],["1616","6","לך לך יב, ז."],["e33","*","באחת ההתוועדויות של שבת מבה\"ח בתקופה זו (לאחרי קבלת האזרחות) אמר כ\"ק אדמו\"ר נשיא דורנו:\nב\"קאנגרעס\" חוקקו חוק מיוחד כדי שכ\"ק מו\"ח אדמו\"ר יוכל לקבל האזרחות בביתו, שכן כאשר \"נשיא הדור\" נצרך למשהו, נחקקים חוקים מיוחדים לשם כך (ראה ברכות ו, ב. ועוד)."],["e34","**","ראה מכתב רבינו אליו מיום זה — ט\"ז אדר תש\"ט (אגרות­-קודש ח\"י ע' קכ ואילך): \"בזה הנני לתת לו את תודתי הגדולה על אשר הואיל לסדר בטוב ומעולה דבר התאזרחותי במדינה זו, והנני שולח לו בזה את ברכתי. . ואשר יעזור השי\"ת לידידי ובכל אשר יפנה יצליח בגשמיות וברוחניות\". — אגרת דומה נשלחה לכמה מחברי המשלחת."],["e35","***","מועתק בזה מכתב רבינו מחודש טבת תש\"ט:\n\"איך בעט אייך אַזיי גוט זיין טעלעפאָניש איבערגעבין ידידי מר קרעמער אויב ער האָט שוים זיכער בעשטעלט די צייט פון דעם דזאָדזש מיט זיינע גיהלפן אויף דער קומענדיקן דאָנערשטאָג 1 אַזייגער. גיוויס וועט אונזער גיעהרעטער פריינד דזאָדזש קליינפעלד אויך זיין, אונד מעהר מענטשין אַ חוץ רבי קאַזאַרנאָווסקי, אונד חתני הרב שניאורסאהן וואס האָט די גאַנצע צייט געטאָהן אין דעם ענין, אונד האָט גיבראַכט אז עס זאָהל זיין אין אָרדענונג. . .\nאיך בעט אייך ליבער פריינד ערפילין מאַיין פערלאַנג און זעהן אַיינאָרדענען אַז קיין אַנדערע מענטשין אַ חוץ די אויבערדערמאָנטע אונזער פריינד דזאָדזש קליינפעלד רבי קאַזאַרנאָווסקי אונד מר מינדל זאָהלין ניט זיין.\nאויב איהר האָט שוים ועמען עס איז אַ חוץ דזאָדזש קליינפעלד, רבי קאַזאַרנאָווסקי, אַיינגלאַ­דין בעט איך אייך מר קרעמר אָפּלייגין דעם קומען פון דעם דזאָדזש אויף אַ אַנדער צייט. . .\nדער ענין פון אַיינאָרדענען די בירגערשאַפט פאַר מיר איז דורכאויס נאָהר די אַרבעט פון חתני הרב שניאורסאהן\"."]]],[4301620532,"למדינה<sup data-n=\"1617\">7</sup>, הנה עתה — בהשגחה פרטית<sup data-n=\"1618\">8</sup> — מצאתי את המקום הראוי שמשם תתנהל עבודת הפצת היהדות והפצת המעינות חוצה — כאן באמריקה<sup data-n=\"1619\">9</sup>.",[["1617","7","ראה ספר השיחות ה'תש\"ב ע' 67: \"די השגחה פרטית האָט מיך מטלטל געווען ממדינה למדינה ביז אַמעריקע\"."],["1618","8","ראה ספר השיחות קיץ ה'ש\"ת ע' 20: \"די השגחה עליונה שליחות מיינע, מאַכן אַמעריקע פאַר אַ מקום תורה ביראת שמים\". וראה גם ספר השיחות תש\"ד ע' 33. ע' 42. ועוד."],["1619","9","ראה ספר השיחות ה'תשמ\"ט ח\"ב ע' 548 — שכאשר כ\"ק אדמו\"ר מהוריי\"צ הגיע לארה\"ב נעשה מקום זה מקור ההשפעה (בלשון הכתוב (ירמי' ב, יג) — מקור מים חיים) דהפצת המעינות חוצה לכל העולם כולו. וראה שיחת מוצש\"ק בשלח, יו\"ד שבט תשל\"ד. ש\"פ משפטים ה'תשנ\"ב (ספר השיחות תשנ\"ב ח\"ב ע' 364)."]]],[4301620533,"<h3>יום שלישי, כ\"א אדר תש\"ט<sup data-n=\"1620\">1</sup></h3>\nעס איז אַ מנהג ישראל צו זאָגן מזל טוב (ואמר: מזל טוב).\nעס איז דאָ אַ וואָרט פון דעם רבי'ן: בת תחלה סימן יפה לבנים<sup data-n=\"1621\">2</sup>, וואָס איז דאָ יפה?\nאַז עס ווערט געבאָרען אַ בן און מען איז מקיים אַ מצוה — מען איז איהם מכניס לברית, זאָגט מען: כשם שנכנס לברית כן יכנס לתורה ולחופה ולמעשים טובים; אָבער ביי אַ בת איז דאָך דאָס ניטאָ,\n[ואמר:] אַז עס ווערט געבוירן אַ בת, און מען איז מגדל די בת בדרך התורה והמצוה, מען ערציט איר אַז זי זאָל וויסן וואָס מען מעג און וואָס מען טאָר ניט — איז דאָס איז תחלה, דאָס איז דער יסוד, פון דעם ווערט געבויט די אידישע הויז. און אַז עס איז דאָ די בת, קען נאַכהער זיין יפה לבנים.\n[וסיים כ\"ק אדמו\"ר שליט\"א:] דער אויבערשטער זאָל אייך העלפן עס זאָל אייך מקוים ווערען דעם רבי'נס ברכה.\n[ואמר עוד:] איך פריי זיך מיט אים, אָבער עס איז שוין צייט עס זאָל זיין ביי אייך נאָך קינדער, עס זאָל זיין יפה לבנים.\n[כ\"ק אדמו\"ר שליט\"א לקח הציצה הימנית מהט\"ק שלו ונתנה להילד, נטלה ונשקה ואח\"כ הניחה על עיניו. הרד\"ש שאל להילד: מה זה, ואמר הילד בקול: ציצית.\nלאחר שקרא כ\"ק בהפ\"נ, אמר:] דער אויבערשטער זאָל ממלא זיין כל משא­לות לבכם לטובה ולברכה.\n[כשיצא הרד\"ש נתן ידו לכ\"ק אדמו\"ר שליט\"א ונשקו, והרמ\"פ אחז ביד בנו זאב יחזקאל ואמר: איך וויל ער זאָל זיין אַ חסיד, והשיב כ\"ק אדמו\"ר שליט\"א: איך האָף (ולא נתן ידו הקדושה להילד)]<sup data-n=\"1622\">3</sup>.",[["1620","1","לרגל יום הולדת השלישי (\"אָפּשערעניש\") של הילד זאב יחזקאל שי' הכהן כ\"ץ (ביום הרביעי ט\"ו אדר שושן פורים קטן) — נכנסו ר' משה פנחס הכהן כ\"ץ וזוגתו, וחותנו ר' דוד שטאקהאַמער, והילד זאב יחזקאל שי'.\nכשנכנס הרד\"ש, נתן שלום לכ\"ק אדמו\"ר שליט\"א וגם נשקו על ידו, ואחר שעשה כן אמר להילד זאב יחזקאל שיעשה ג\"כ כזה, ועשה כן ונתן ידו לכ\"ק ונשקו על ידו.\nואמר כ\"ק אדמו\"ר שליט\"א [ההמשך בפנים]:"],["1621","2","ב\"ב קמא, א."],["1622","3","ברשימת הרמ\"פ נוסף: \"ביום ועש\"ק כ\"ד אדר דברתי עם הרמ\"ש שי' בטלפון בשעה 30.3 בערך, ואמר לי אשר כ\"ק אדמו\"ר שליט\"א האָט זייער הנאה געהאַט פון אינגעלע ואמר עליו: ביי אים איז אַ ליכטיגער פנים\"."]]],[4301620534,"<h3>יום א יא ניסן, תש\"ט<sup data-n=\"1623\">1</sup>.</h3>\nאין די ימי החינוך וואָס הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע האָט מיך מחנך געווען, איז געווען אַ סדר קבוע מסודר בדיוק נקודי.\n* * *\nדער וואָס איז געבענטשט מיט אַ געזונטן חוש השמיעה, הערט ער — דאָס מיינט דערהערט<sup data-n=\"1624\">2</sup> — דעם חוט פנימי — דעם אינערליכען שנירל — דעם בריח תיכון פון דעם וואָרט.\nבכלל אין אַ חסידישן סיפור און אין אַ קורצן וואָרט, אָן קיין שום חילוק צי דער וואָרט איז מער ניט ווי אַ מקורי וואָרט אָדער איז אַ מקורי נקודה וואָרט; דאַרף מען דערהערן דעם חוט הפנימי.\n* * *\nיעדער חסידישער וואָרט איז באַלעבט מיט אַ חיות פנימי להחיות, וואָס דאָס איז דער הפרש פון השכלה דחסידות חב\"ד און עבודה דחסידות חב\"ד.\nאַז מען לערנט אַ ענין אין חסידות בעיון גדול און מען איז זיך אַליין מבאר ומסביר דעם ענין מיט כמה משלים ודוגמאות, בריינגט דאָס אַז מען פאַר­שטייט דעם ענין דייטליך קלאָר און לעבעדיק. אָבער אין עבודה בפועל פון תיקון המדות קומט דאָס ניט. איז דאָס טאַקע חיות, ער קאָכט זיך אין דעם, אָבער עס איז ניט להחיות אין פעולת הטבת וזיכוך המדות.\n* * *\nדי עטלעכע ווערטער זיינען דער פירוש וביאור המלות \"חינוך קבוע ומסודר בדיוק נקודי\". עס איז פאַראַן חינוך מסודר בדיוק, און עס איז פאַראַן נאָך אַ אופן חינוך פרטי מסודר בדיוק נקודי, דער חינוך איז ניט קיין כללי, ניט פאַר אַלעמען נאָר פאַר יחידים פרטיים, אָבער יעדער יחיד איז אַ כללי, וואָס זיינע מוחין ומדות, הגם זיי זיינען פרטיים, דאָס איז דאָך זיינע וואָס מען גיט אים מלמעלה, דאָך אָבער איז ער אַ כללי, אין אים און דורך אים ווערט נתגלה אַ אור וחיות להחיות.\n* * *\nדער בכן פון דעם פנימיות'דיקן ביאור איז אַז מען בעדאַרף דערהערן — און אַז מען איז זוכה פילט מען — וואָרום עס איז אַ קבלה מרבי לרבי וואָרט:\nאַ פנימיות'דיקער מחונך האָט די ריכטיקע גוט אויסגעפלאסטערטע כלי קיבול.\nדאָס איז דער מקובל'דיקער וואָרט<sup data-n=\"1625\">3</sup>:\nמצה שמורה ווערט גערופען בשני שמות עצמיים ופנימיים: מיכלא דמהימ­נותא און מיכלא דאסוותא<sup data-n=\"1626\">4</sup>. עס גיט אַ חיזוק אין דעת.\nדאָס איז דער פנימי נקודי עצמי וואָרט",[["1623","1","נדפס עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ תש\"ט ע' 142 ואילך.\nהשיחה נאמרה להרה\"ח ר' שלמה אהרן קאַזאַרנאָווסקי שנכנס להיכל קדשו (חדר ה\"יחי­דות\") של רבינו למסור דו\"ח ע\"ד שליחות מסוימת שנמסרה על ידו."],["1624","2","זע די שיחה בקונטרס יב­ויג תמוז תש\"ח בארוכה [סה\"מ תש\"ח ע' 252 ואילך. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 343 ואילך]."],["1625","3","[הועתק בהגדה של פסח עם לקוטי טעמים ומנהגים ע' לד."],["1626","4","זח\"ב קפג, ב. וראה לקו\"ת צו יג, ד. לקמן ע' 314]."]]],[4301620535,"וואָס מורנו הרב המגיד ממעזריטש האָט מקבל געווען ממורו הקדוש מורנו הבעש\"ט בשם מורו הבעל ח\"י<sup data-n=\"1627\">5</sup> ומסרו להוד כ\"ק תלמידו המקבל פנימי רבינו הזקן ובא ביחוד וביאור<sup data-n=\"1628\">6</sup> מרבי לרבי.\nכל אחד ואחד מהוד כ\"ק אבותינו רבותינו הק' זי\"ע בדורו חזר מסר וביאר את ה\"נקודה וואָרט\" האמור.\n* * *\nדער ביאור פרטי פון דעם וואָרט איז:\nאכילה איז אַ ענין פנימי וואָס פועל'ט דעם חיזוק חיות הנפש אין די אברי הגוף אַז די אברי הגוף זאָלען זיין אַ כלי קיבול צום חיות פנימי פון נפש. עס שטאַרקט דעם גוף צו מקבל זיין דעם חיות הנפש און עס שטאַרקט דעם נפש צו מתגלה זיין זיך אין די אברי הגוף.\nאמונה איז למעלה מטעם ודעת. אויף די ענינים וואָס מען פאַרשטייט איז דאָך ניט שייך צו זאָגען אמונה, ער פאַרשטייט דאָך אַז עס איז אַזוי. אמונה איז הגם בשכלו פאַרשטייט ער ניט ווי דאָס איז, און ער האָט אפילו ניט קיין השערה אין זיין שכל ווי דאָס איז, אָבער אַזוי איז דאָס. ער איז מאמין באמונה פשוטה אַז אַזוי איז דאָס.\nאון דאָס איז דער פירוש הענין וואָס מצה ווערט גערופען מיכלא דמהימנותא און מיכלא דאסוותא. עס איז מיכלא וואָס שטאַרקט דעם געזונט פון דעם גוף אַז ער זאָל הערן דעם תכלית ירידת הנשמה בגוף, און דאָס איז אויך מיכלא דמהימ­נותא אַז דער תוקף האמונה זאָל מאיר זיין אין אַלע עניני החיים פון אידן.\n* * *\nהוד כ\"ק אאמו\"ר הרה\"ק האָט מיך מזכה געווען מיט אַ ענין עצמי — ווי עס איז פאַרצייכענט אין מיין יומן פון יענעם זמן — און געזאָגט:\nנאָך דער יחידות וואָס איך בין געווען חול המועד פסח, איינ'חזר'נדיק און לפי ערכי דורכגעטאָן, האָט מיר הוד כ\"ק אאמו\"ר — אאזמו\"ר הרה\"ק מוהר\"ש — געזאָגט, נאָכדעם וואָס ער האָט מיר מבאר ומסביר געווען די עניני השאלות וואָס איך האָב געפרעגט:\nצוויי כיתות חסידים זיינען געווען באַ הוד כ\"ק רבינו הזקן. ביידע כתות זיינען געווען משכילים און עובדים, על דרך ווי הגאון החסיד ר' אייזיק האָמליער און החסיד הגאון ר' זלמן זעזמער<sup data-n=\"1629\">7</sup>.\nהרה\"ח ר' אייזיק האָט אָנגעהויבען פון השכלה און איז געקומען צו עבודה, און ר' זלמן האָט אָנגעהויבען פון עבודה.\nהשכלה איז קאַלט, עבודה איז הייס. און דער חילוק אין עבודה בפועל איז: באַ אַ משכיל הערט זיך אויך אין עבודה די קאַלטקייט פון השכלה, און באַ אַ עובד איז אין זיין השכלה פילט זיך די איבערפולטקייט פון האַרץ.\n* * *\nדי אַלע חילוקים איז אַלץ אַ זאַך פון געווען, געווען משכילים עובדים אָדער עובדים משכילים. אָבער איצטער איז לא הא ולא הא.",[["1627","5","ר\"ת חי' יחידה. געמיינט אחי' השילוני — זע שיחת ש\"פ פנחס ה'ש\"ת (ספר השיחות [קיץ ה'ש\"ת] ע' 159) [וראה לעיל ע' 232 הערה 18."],["1628","6","בהוצאה ראשונה של השיחה ובהגדה של פסח שם: ובירור. ונתקן בפנים ע\"פ לוח התיקון שבסוף השיחה]."],["1629","7","זע אויך די שיחה בקונטרס הנ\"ל ע' 24 [סה\"מ תש\"ח ע' 260, ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 351] און ווייטער [אודות ר' אייזיק האָמליער — ראה גם לעיל ע' 25. וש\"נ. אודות ר' זלמן זעזמער — ראה לקמן ע' 314]."]]],[4301620536,"השי\"ת יחוס וירחם על כללות עדת ישראל ועדת החסידים למפלגותיהם וישפיע לנו ולהם שפעת חיים וברכה במנוחת הלב והמוח להיות כלים פנימי' לתורת ועבודת החסידות בגשמיות וברוחניות."],[4301620537,"<h3>שיחות חג הפסח</h3>\n<h4>בעת מכירת חמץ י\"ג ניסן ה'תש\"ט<sup data-n=\"1630\">1</sup></h4>\nא. (אחר סדר מכיר' חמץ אמר כ\"ק אדמו\"ר שליט\"א:)\nדער אויבערשטער זאָל העלפען אַז דער מכירת חמץ זאָל זיין אין אַ פנימיות. ביטול חמץ אַליין איז ניט מספיק. עס דאַרף זיין דער ביעור חמץ. וואָס דאָס אַלץ איז אַ הכנה אויף אַריינצובריינגען די מצה, וואָס איז מיכלא דמהימנותא<sup data-n=\"1631\">2</sup>.\nב. מצה איז מיכלא דמהימנותא און אויך מיכלא דאסוותא<sup data-n=\"1632\">3</sup>. דער חילוק איז, אויב ער איז ניט קיין געזונטער איז פריער מיכלא דאסוותא און נאָכדעם מיכלא דמהימנותא. אָבער ביי אַ גע­זונטען איז פריער מיכלא דמהימנותא און נאָכדעם איז דער מיכלא דאסוותא, דאָס הייסט, אַז דער מיכלא דמהימנותא זאָל אויף עם פועל'ן.\n<h4>סדר הראשון, חה\"פ, ה'תש\"ט</h4>\nג. חג הפסח תרנ\"ט האָט הוד כ\"ק אאמו\"ר הרה\"ק שטאַרק פאַרבראַכט ביי די סדרים און האָט דאַן דערציילט:\nהחסיד ר' זלמן זעזמער<sup data-n=\"1633\">1</sup> איז געווען פון די, וועלכע האָבען נאָך געקענט די זקני החסידים וועלכע זיינען געווען ביים בעל שם טוב נאָך איידער דער אַלטער רבי איז געבאָרען געוואָרען, און האָבען געדיינקט ווען דעם אַלטען רבי'ס פאָטער ר' ברוך האָט, צוזאַמען מיט דער מוטער, געבראַכט דעם אַלטען רבי'ן, אַלס קינד פון דריי יאָהר צום בעש\"ט<sup data-n=\"1634\">2</sup>.\nהחסיד ר' זלמן זעזמער האָט איבער­דערציילט וואָס ער האָט געהערט פון די זקני החסידים קורצע תורה­ווערטער פון בעש\"ט. איינע פון די תורה ווערטער:\nהא לחמא עניא, הא איז בינה<sup data-n=\"1635\">3</sup>, איז דאָס לחמא עניא, אַז מען פאַרשטייט די עניות פון השגה דאַן פאַרשטייט מען די עשירות פון חכמה.",[["1630","1","שיחות חג הפסח תש\"ט נדפסו עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ ה'שי\"ת ע' 183 ואילך."],["1631","2","זע זהר ח\"ב מא, א. קפג, ב. — בסהמ\"צ להצ\"צ מצות חמץ ומצה מציין לזח\"א קנז. וצ\"ע."],["1632","3","זח\"ב קפג, ב. — זע אויך \"היום יום\" טו ניסן ה'תש\"ג [ספר השיחות תש\"ב ע' 94 ואילך]. ד\"ה כימי צאתך תש\"ח (קונטרס נו) פי\"ב [סה\"מ תש\"ח ע' 166. וראה לעיל ע' 312 ואילך]."],["1633","1","וועגען עם זע קיצורים לתניא ע' קכג [אגרות­-קודש ח\"ד ע' רסה]. ס' השיחות [קיץ ה'ש\"ת] ע' 104. קונטרס עב [סה\"מ ה'שי\"ת] ע' 88 [ספר השיחות תש\"א ע' 34. לעיל ע' 313. וראה גם ספר השיחות תרפ\"ח­תרצ\"א ע' 244. וש\"נ]."],["1634","2","זע בארוכה שיחת חי אלול ה'תש\"ה (לקוט כה) [ספר השיחות תש\"ה ע' 122 ואילך]."],["1635","3","חידוש כאן כי בכ\"מ בכתבי האריז\"ל נתבאר הא לחמא עניא, הא אחרונה מל'. [וראה גם שיחת ליל ב' דחג הפסח תש\"ח (לעיל ע' 204)]."]]],[4301620538,"פסח איז פה סח<sup data-n=\"1636\">4</sup>.\nהוד כ\"ק אאמו\"ר הרה\"ק האָט גע­רעדט אין דעם אַן אריכות הביאור.\nד. מה נשתנה.\nדער נוסח פון מה נשתנה איז, אַז מען דאַרף זאָגען בזה\"ל:\nטאַטע איך וועל ביי דיר פרעגען פיער קשיות<sup data-n=\"1637\">5</sup>.\nביי הוד כ\"ק רבנו הזקן פלעגען אַלע קינדער פרעגען מה נשתנה<sup data-n=\"1638\">6</sup>: דער מיטעלער רבי, ר' חיים אברהם<sup data-n=\"1639\">7</sup>, און ר' משה<sup data-n=\"1640\">8</sup> און נאָכדעם דער אייניקעל הוד כ\"ק אאזמו\"ר הצמח צדק, און אַלץ מיט'ן זעלבען נוסח, טאַטע וכו', אַז זיי פלעגען ענדיקען פלעגט דער אַלטער רבי אַליין זאָגען בלחישה מיטן זעלבען נוסח, טאַטע וכו'<sup data-n=\"1641\">9</sup>.\nאיך האָב געפרעגט ביי הוד כ\"ק אאמו\"ר הרה\"ק, ביי וועמען האָט דער אַלטער רבי געפרעגט. האָט מיר כ\"ק אאמו\"ר הרה\"ק געענטפערט: מקבל געווען האָב איך ניט, נאָר איך בין משער אַז דאָס האָט ער געפרעגט ביי דעם בעל ח\"י<sup data-n=\"1642\">10</sup>. האָב איך איהם ווייטער געפרעגט, אם כן ווי אַזוי האָט ער אים גערופען טאַטע. האָט מיר הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט: דו ביסט דאָך אַ דברן, בעט איך דיר אַז דאָס זאָלסטו ניט דערציילען...\nה. עבדים היינו.\nיעדער ענין האָט זיך זיין ניגון. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט זאָגען עבדים היינו מיט אַ בעזונדער ניגון, מיט אַ העכערען קול און בקצת דביקות. דער פירוש פון אַ העכערען קול מיינט אַז אין יעדען וואָרט האָט זיך אָנגעהערט דער \"העכער\" פון דעם וואָרט. דאָס וואָס איז העכער פון דעם וואָרט.\nו. אחד חכם וכו'.\nאַלע ריידען וועגען אחד, אויך דער רשע רעדט וועגען אחד<sup data-n=\"1643\">11</sup>. ער גלויבט אין אחד נאָר דאָס איז ביי איהם אַ בעזונדער זאַך, עס האָט צו איהם קיין שייכות ניט, ע\"ד עזב הוי' כו'<sup data-n=\"1644\">12</sup>. ער איז מבטל און זאָגט: עס איז דאָך אם<sup data-n=\"1645\">13</sup> צדקת מה תתן לו ואם רבו פשעיך מה תעשה לו וכו'<sup data-n=\"1646\">14</sup>.\nדער אחד פון תם איז די תמימות'­דיקע אמונה פשוטה פון אַ איש פשוט.\nדער אחד פון שאינו יודע לשאול איז שוין גאָר אַנדערש. פון דעם לערנען מיר אָפּ צוויי זאַכען: אַז מען דאַרף פרעגען און מען דאַרף ענטפערען, וואָס דאָס איז",[["1636","4","בכ\"מ בכתבי האריז\"ל. וראה סהמ\"צ להצ\"צ מצות חמץ ומצה ספ\"ב [כג, ב]."],["1637","5","זע אויך \"היום יום\" טז ניסן ה'תש\"ג."],["1638","6","[ראה ספר השיחות תש\"ד ע' 87."],["1639","7","ראה אודותו — ספר השיחות תרפ\"ח­תרצ\"א ע' 33 הערה 30. וש\"נ."],["1640","8","ראה אודותו — אגרות­-קודש ח\"ז ע' טו ואילך. חי\"ד ע' קסד ואילך. רשימת רבינו — \"דברי ימי חיי אדמו\"ר הזקן\". רשימה בספר התולדות אדמו\"ר הזקן (קה\"ת — אה\"ק — תשמ\"ו) ח\"ד ע' 1192 ואילך. ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 54. ע' 81 ואילך. ע' 113. ע' 126. ע' 250. בית רבי ח\"א פכ\"ד (נז, א)."],["1641","9","ראה גם שיחת ליל א' דחה\"פ תש\"ז (לעיל ע' 102)]."],["1642","10","אחי' השילוני. זע הערה בקונטרס ב' ניסן [סה\"מ ה'שי\"ת] ע' 160 [לקמן ע' 347. וראה לעיל ע' 232 ובהערה 18]."],["1643","11","[ראה גם שיחת ליל א' דחה\"פ תש\"ח (לעיל ע' 199)."],["1644","12","לשון הכתוב — יחזקאל ח, יב. ט, ט. וראה סה\"מ תרנ\"ח ע' א ואילך. עזר\"ת ע' סב ואילך. ובכ\"מ."],["1645","13","ע\"פ איוב לה, ו­ז."],["1646","14","ראה תורת חיים שמות צג, א­ב ובכ\"מ]."]]],[4301620539,"דער — את פתח לו. די שאלת החכם איז דאָס ניט פון די מעלות החכם, עס איז גאָר פון דעם חסרון החכם, ווייל פרעגען פאַרוואָס, דאַרף מען ניט; אָבער ביי ושאינו יודע לשאול איז אַנדערש.\nאמונה איז ניט אויף אַלץ. דאָס וואָס מען קען פאַרשטיין איז ניט שייך קיין אמונה. דאָרט וואו מען האָט שוין דער­גרייכט אַלץ וואָס מען קען צוקומען דורך השגה הויבט זיך דאָרט אָן אמונה. איז — אַז ער קומט­צו צו דעם וואָס איז העכער פון פאַרשטאַנד, דעמאָלט פאַר­שטייט ער, אַז דאָס אַלץ וואָס ער האָט פריער פאַרשטאַנען איז גאָר קיין השגה ניט, אַז ער איז גאָר געווען אַ שאינו יודע לשאול...\nז. אַז ער — דער בעל ההגדה — פאַר­ענדיגט די מדריגות אחד פון די ארבעה בנים הויבט ער אָן ריידען וועגען דעם מה<sup data-n=\"1647\">15</sup> פון יעדערען. חכם \"מה\" וכו'.\nח. אַ איד וואו ער זאָל ניט זיין — דאַרף ער וויסען אַז ער איז אַנדערש.\nדער עיקר איז האָבען געזונטע פיס, שטאַרקע נה\"י, דער חב\"ד איז נאָר צוליעב מדות און נה\"י.\nט. אחר אמירת ההגדה, כשגמרו \"לשנה הבאה בירושלים\" סיים כ\"ק אדמו\"ר שליט\"א: מיט משיח'ן.\n<h4>סדר השני, חה\"פ, ה'תש\"ט</h4>\nי. דער אַלטער רבי איז פריער געווען אַ של\"ה איד<sup data-n=\"1648\">16</sup> און האָט משבח געווען פאַר דעם מיטעלען רבי'ן, וואָס ער האָט גענומען פון של\"ה בכלל ובפרט אין דעם פירוש פון די ט\"ו סימני הסדר.\nיא. (אחר הפסקא הא לחמא עניא המשיך לספר מחג הפסח תרנ\"ט ואמר:)\nיעדער וואָרט פון טאַטען איז געווען מדוייק. מ'האָט געדאַרפט זיין אַ גרויסער מבין צו פאַרשטיין יעדע תנועה. יעדער וואָרט וואָס דער טאַטע האָט געזאָגט איז דאָס געווען, אַן טרערען און אָן קרעכ­צעניש, נאָר אַדורכגעווייטאָגט דורך און דורך און פלעגט דאָס זאָגען בלחישה.\nיב. אין דעם אופן פון זאָגען די הגדה איז ביי הוד כ\"ק אאמו\"ר הרה\"ק געווען בדיוק אפילו אין דעם דגש. דעם ערשטען לשנה הבאה וכו' פלעגט ער זאָגען דעם דגש אויף דעם בית (מתיבת הבאה<sup data-n=\"1649\">17</sup>); און ביים צווייטען לשנה הבאה איז געווען דער דגש אויף דעם אלף: לשנה הבאה בני חורין<sup data-n=\"1650\">18</sup>.\nיג. הוד כ\"ק אאמו\"ר הרה\"ק האָט דאַן געזאָגט: דער עיקר אַז עס זאָל זיין דער ירושלים האמיתי, יראה שלם<sup data-n=\"1651\">19</sup>. עס קען זיין כמה טעות'ן אין דעם, וואָס הגם עס זיינען אידישע טעמים אָבער דער תוך איז ניט אמת, און אַז דער תוך איז ניט אמת קען דאָס פאַרפירען אין רע הגמור.\nדאָס האָט דער טאַטע געזאָגט לפרסם",[["1647","15","החילוק דאח\"ד ומ\"ה דכל אחד, אולי יש לבאר עפמשנ\"ת ענין הוי' השני (שהוא שם מ\"ה) ואחד שבשמע ישראל שזהו זו\"ן — ראה לקו\"ת שה\"ש ד\"ה לבבתיני פ\"ב. אמרי בינה שער הק\"ש בתחילתו. שרש מצות התפילה פי\"ג ועוד."],["1648","16","[ראה לעיל ע' 99. וש\"נ]."],["1649","17","זע אויך פירש\"י לך לך טו, יז."],["1650","18","[ראה ספר השיחות תרפ\"ח­תרצ\"א ס\"ע 213 ואילך. וש\"נ."],["1651","19","ראה ב\"ר פנ\"ו, י. תוד\"ה הר — תענית טז, א. לקו\"ת פקודי ד, א. ר\"ה ס, ב. שה\"ש ו, ג. סה\"מ תרפ\"ט ע' 122. לקו\"ש חט\"ו ע' 234. ובכ\"מ."]]],[4301620540,"ברבים. ביים טאַטען איז געווען וואָס ער פלעגט זאָגען ברבים און בחשאי. בחשאי גופא צוויי פאַלען. בחשאי וואָס ער האָט געמיינט לפרסם, בחשאי שהזהיר שלא לפרסם.\nיד. דער חילוק פון די פופציג יאָהר (תרנ\"ט­תש\"ט) איז, וואָס דאַמאָלסט האָט ער — הוד כ\"ק אאמו\"ר הרה\"ק — געזעהן און געפיהלט און מיר האָבען בלויז געהערט — און יעצט איז ער ווייס און מיר פיהלען...\nעס איז דאָ זיס און ביטער. זיס אַז עס ווערט ביטער איז דאָס אַ סימן אַז עס איז קאליע... דער אויבערשטער זאָל העלפען אַז עס זאָל ווערען אויף אַ אמת זיס.\nטו. הרי זה משובח.\nזה, ווייזט דאָך אויף אַ זאַך וואָס איז בגלוי. עס קען אָבער זיין אַ פאַל וואָס מען זעהט און מען ווייס ניט וואָס מען זעהט, איז דאָס דער פירוש הרי זה משובח, אַז מען זאָל פאַרשטיין וואָס מען זעהט.\nנאָך אַ פירוש: אַז דאָס וואָס מען זעהט זאָל פועל'ן אַ פעולה אין פועל און דאַן איז הרי זה משובח.\nטז. מעשה ברבי אליעזר וכו'.\nאַז הוד כ\"ק אאמו\"ר הרה\"ק פלעגט צוקומען צו דער פסקא האָט ער זיך זייער פאסמאקעוועט מיט דער דאָזיקער ועידה און פלעגט זאָגען: אַ שיינע כנופיא<sup data-n=\"1652\">20</sup>.\nאַמאָל האָט ער געזאָגט אַז רבי עקיבא האָט געהאַט אַ חוש אין עבודה, האָט ער געמאַכט אַ טאָלק פון ר' טרפון'ס עשירות<sup data-n=\"1653\">21</sup>.\nדאַמאָלסט איז החסיד הגביר ר' שמואל גורארי'<sup data-n=\"1654\">22</sup> געזעסען הינטער דער טיר און זיך צוגעהערט צום אמירת ההגדה<sup data-n=\"1655\">23</sup>, האָט ער שטאַרק הנאה געהאַט פון דעם וואָרט, און איז שפּעטער אַריינ­געגאַנגען צום טאַטען אויף יחידות און געפרעגט ווי אַזוי מאַכט מען אַ טאָלק מיט די עשירות.\nיז. (בתוך הסעודה ניגנו ניגון הידוע מכ\"ק אדמו\"ר נ\"ע הנק' דער ראָסטאָווער ניגון<sup data-n=\"1656\">24</sup> ואמר אחד, אַז דער ניגון איז פּאַחאָזשע (בדומה) ווי מען האָט איהם געזונגען אין ליובאַוויטש. ואמר כ\"ק אדמו\"ר שליט\"א:)\nאַז אַלע ענינים וואָלטען געווען חאָטש \"פּאַחאָזשע\" ווי אין ליובאַוויטש — וואָלט געווען גוט. איך ווייס ניט פאַר­וואָס, צי עס זיינען איצט שטאַרקערע בירורים אָדער שוואַכערע מבררים...\nיח. אין יאָהר תרנ\"א האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט, אַז דאָס וואָס חסידים האָבען גענומען פון חסידות און וואָס רביים האָבען געגעבען חסידים איז, אַז יעדער ענין זאָל זיין ווי אַ דבר חדש אָן הפרש וואָס פאַר אַ ענין עס זאָל ניט זיין.",[["1652","20","ראה גם שיחת ליל ב' דחה\"פ תש\"ז. תש\"ח (לעיל ע' 105. ע' 205)]."],["1653","21","זע ויקרא רבה פל\"ד, טז. כלה פ\"א. כלה רבתי פ\"ב."],["1654","22","ר' שמואל ב\"ר שניאור זלמן גורארי'. מה\"יושבים\" אצל אדמו\"ר מהר\"ש, ואח\"כ נצטווה ממנו להתעסק במסחר. מחסידי אדמו\"ר מהורש\"ב ואדמו\"ר מהוריי\"צ. נפטר בחודש אד\"ר תרפ\"א. ראה אודותו אגרות­-קודש חי\"ד ע' קעה: \"הוא הי' האחד אשר בכל עת מסר נפשו בשביל כ\"ק אדמו\"ר [מהורש\"ב] זצוקללה\"ה נבג\"מ זי\"ע, ובשביל רצונותיו הקדושי' אשר הי' נותן ביד רחבה מבלי התחשב כלל, וזכה אשר קבורתו בתוך אהל כ\"ק אדמו\"ר [מהורש\"ב] זצוקללה\"ה נבג\"מ זי\"ע\". וראה גם אגרות­-קודש ח\"א ע' שכו."],["1655","23","ראה ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 270. קיץ ה'ש\"ת ע' 63. תש\"ב ע' 90."],["1656","24","זע ספר הניגונים ניגון מד."]]],[4301620541,"דער לשון איז געווען: בלא פלוג. צי אַ ניגון אָדער אַ ריקוד. מען האָט מדייק געווען יעדער וואָרט, מען האָט געהיט יעדע תנועה פון ניגון. אויף ריקוד — זיינען ניט אַלע געווען מבינים צו פאַרשטיין וואָס מען האָט געזעהן.\nיט. דער מעלה אַליין ווערט נתעלה דורך דער עלי' פון דעם מטה. אצילות ווייסט אַז עס איז דאָ אַ למעלה פון אצילות, אָבער אצילות מצד עצמו פאַר­שטייט ניט דעם למעלה פון אצילות. דורך דער עבודה פון למטה ובעלייתו — ווערט אצילות העכער אַז זי איז משיג די גילויי אורות פון למעלה פון אצילות.\nכ. מזיגת הכוס של אליהו הנביא הי' השתא (בב' הלילות) אחר ברכת המזון<sup data-n=\"1657\">25</sup>.\n<h4>סעודת ליל שביעי של פסח ה'תש\"ט</h4>\nכא. פאַר דעם יאָהר תרנ\"ד פלעגט הוד כ\"ק אאמו\"ר הרה\"ק רעדען ביי אַ פאַרבריינגען קורצע ווערטער. געווען אַזעלכע ווערטער, וועלכע איך האָב לפי ערך שנותי דאַמאָלסט ניט געקענט תופס זיין און מיין מלמד ר' ניסן<sup data-n=\"1658\">26</sup> פלעגט מיר שפּעטער מסביר זיין<sup data-n=\"1659\">27</sup>.\nבכלל איז געווען זמנים חלוקים אצל הוד כ\"ק אאמו\"ר הרה\"ק: תר\"מ­מ\"ב מ\"ג­נד. מ'קען עס זעהן פון די מאמרים פון יענע יאָהרען, אין דעם מאמר אחרי תרמ\"ט<sup data-n=\"1660\">28</sup> האָט זיך דער טאַטע געקאָכט אין דעם ענין פון תהו ותיקון.\nאיינע פון די ווערטער איז געווען: ופסח ודלג<sup data-n=\"1661\">29</sup>. לכאורה איז ניט מובן וואָס איז ופסח און וואָס איז ודלג, עס איז דאָך די זעלבע זאַך, איז וואָס איז דער ודלג מוסיף אויף דעם ופסח, הגם עפ\"י נגלה קען מען זאָגען אויף דעם אַ ביאור, אָבער וואָס איז דער \"אינעווייניג\" פון דעם. נאָר דער ענין איז, ופסח מיינט אַ שפּרונג. אַז מען שפּרינגט דאַרף מען וויסען פון וואַנען מען שפּרינגט און וואוהין מען שפּרינגט. נאָכן שפּרונג זעהט מען ערשט, אויב דער שפּרונג איז געווען אַ ריכטיגער, צי מען האָט גע­שפּרונגען וואו מען דאַרף, און דאָס איז דער — ודלג.\nאַז מען דערמאָנט זיך אויף די אַמאָ­ליגע ווערטער איז מען זיך פשוט מחי'.\nכב. חסידים זיינען עשירים, זיי האָבען אוצרות, נאָר מען דאַרף דאָס אויפגראָ­בען, אויב ניט בלייבט דאָס פאַרגראָבען.\nכג. דעם טאַטענ'ס אַ וואָרט:\nאַלע השכלות און השגות קומען ניט צו אַ געשמאַק אין דאַוונען.\nכד. אַמאָל האָט מען געלעבט מיט דעם וואָרט און באַלעבט דעם וואָרט, פאַרן דאַוונען און אין דאַוונען.\nהיינט, האָט מען מיט וואָס צו טאָן און מען ווייסט ווי אַזוי צו טאָן, נאָר דער חסרון איז אין טאָן, דער טאָן אַליין פעהלט...\nכה. (כ\"ק אדמו\"ר שליט\"א ענה לאחד",[["1657","25","זע שיחת פסח ה'תש\"ג אות יד [ספר השיחות תש\"ג ע' 58. וראה שיחת ליל ב' דחה\"פ תש\"ז (לעיל ע' 108). וש\"נ."],["1658","26","ראה אודותו לעיל ע' 41. וש\"נ."],["1659","27","ראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 292. לעיל ע' 128."],["1660","28","סה\"מ תרמ\"ט ע' רלג ואילך."],["1661","29","בא יב, כג ופירש\"י שם."]]],[4301620542,"על שאלתו:) אין מים איז מעין דער קוואַל, מקור איז די נקודה עצמית פון יעדער זאַך.\nכו. מען האָט געדאַרפט צונויפקליי­בען די אַלטע ווערטער, מען האָט גע­דאַרפט ליגען אין דעם. איך האָב אַמאָל געשריבען צו הרב ש. ד.<sup data-n=\"1662\">30</sup> שי' וועגען דעם, ער האָט געהאַט אַ חוש אין צונויפ­קלייבען ווערטער. ר' מרדכי ע\"ה<sup data-n=\"1663\">31</sup> האָט געחזר'ט אַ וואָרט, ער האָט גענומען אַ וואָרט, צי דער וואָרט האָט אים גענומען. נו.. ר' שילם ע\"ה<sup data-n=\"1664\">32</sup> האָט דורכגעטאָן און דורכגעווייטאָגט דעם וואָרט.\nכז. שביעי של פסח פלעגט מען אַמאָל אופזיין אַ גאַנצע נאַכט<sup data-n=\"1665\">33</sup>, אָהן חכמות, פשוט אויפזיין. מען פלעגט לערנען כמה שיעורים, נגלה און נסתר. דער נסתר איז אויך געווען נגלה.\n<h4>סעודת יום שביעי של פסח ה'תש\"ט</h4>\nכח. (כ\"ק אדמו\"ר שליט\"א אמר להעומדים מסביב לשולחן, אם עדיין לא סעדו סעודת יו\"ט שילכו לנט\"י להסעו­דה. ואמר אחד: צריכים לשאול אם הם כבר אחר התפלה, וענה כ\"ק אדמו\"ר שליט\"א):\nאון ווער האַלט דאָס נאָכ'ן דאַוונען. אַמאָליגע חסידים פלעגען מאַכען יעדען טאָג אַ קנייטש אין סידור, היינט האָב איך געדאַווענט ביז דאָ; ער פלעגט כמובן גומר זיין דעם גאַנצען דאַוונען, נאָר \"געדאַווענט\" האָט ער נאָר ביז דאַנען, מאָרגען פלעגט ער דאַוונען נאָך אַ שטיקעלע און דאָרט מאַכן דעם קנייטש אין סידור<sup data-n=\"1666\">34</sup>. אויף מאָרגען פאַרן דאַוונען פלעגט ער זיך פאַרטראַכטען וואָס דער נעכטיגער דאַוונען האָט אין איהם אויפ­געטאָן, בויך ווייטאָג אָדער שובע. דער חסיד פלעגט פון בויך ווייטאָג אויך ניט נתפעל געוואָרען. ער האָט געוואוסט אַז ע\"ד ווי אַ מאכל אויב מען צוקייעט עס ניט ווי מען בעדאַרף בעקומט מען בויך ווייטאָג פונדעסטוועגען עסט מען ווייטער און אַזוי איז אויך אין עבודה.\nאַמאָליגע חסידים האָבען קיינמאָל ניט אָפּגעדאַווענט; זיי האָבען שטענדיג געהאַלטען אין דאַוונען.\nכט. דעם יאָהר תר\"ן איז אַלץ געווען באריכות; מאמרים באריכות, ביאורים באריכות, געמאָנט באריכות און געגע­בען באריכות.\nדאַן איז געווען אַ וואָרט: כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"1667\">35</sup>, נון פל­אות<sup data-n=\"1668\">36</sup>. ווער איז דערפון נתפעל",[["1662","30","ראה מכתב י\"א שבט תש\"ט — אגרות­-קודש ח\"י ע' פב]."],["1663","31","כנראה הכוונה לר\"מ חפץ הי\"ד הנק' מרדכי דיסנער, שו\"ב בריגא [ראה אודותו — ספר השיחות תרפ\"ח­תרצ\"א ע' 41. וש\"נ]."],["1664","32","כנראה הכוונה לר\"ש קוראטין. ראה אודותו הערות בסו\"ס תורת שלום ע' 323 [בהוצאת תשי\"ז ואילך: ע' 70 הערה 1. וראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 18. תרפ\"ח­תרצ\"א ע' 13."],["1665","33","ראה ספר השיחות שם ע' 215. וש\"נ."],["1666","34","ראה גם לעיל ס\"ע 75. וש\"נ."],["1667","35","[מיכה ז, טו]."],["1668","36","זח\"א רסא, ב. ועייג\"כ מאו\"א מע' נו\"ן סכ\"א. וברשימות הצ\"צ על פסוק זה (מיכה ז, טו) סק\"ג [אוה\"ת נ\"ך ח\"א ע' תפו] כתב, וז\"ל: לע\"ל אראנו נפלאות נו\"ן פלאות היינו נו\"ן שערי בינה ממש, וגם לא נש\"ב דאצילות כ\"א נש\"ב דכתר כמ\"ש בלקו\"ת שהכתר עליון ממש נק' שער הנו\"ן דבינה וגם יהי' הגילוי מלמעלה משער הנו\"ן כי שער הנו\"ן הוא א\"א כו'."]]],[4301620543,"געוואָרען משה רבינו ע\"ה. אין משה'ן איז דערהערט געוואָרען דער אור הנשמה בגילוי בגופו ע\"ד ווי עס איז בקבלה — אַזוי איז געווען דער לשון — אַז ביים אַלטען רבי'ן האָט מאיר געווען אור היחידה בגופו ממש<sup data-n=\"1669\">37</sup>. פאַרוואָס האָט משה זוכה געווען דערצו, ווייל ער איז געווען בגופו אין מצרים. דאָס הייסט ער האָט מרגיש געווען דעם שיעבוד. משרע\"ה האָט דערהערט בפנימית לבבו אין לב הגשמי דעם ניט גוט פון אַ אידען אין גשמיות.\nהגם עס איז דאָך געווען טענות: בשבתנו<sup data-n=\"1670\">38</sup> על סיר הבשר וכו', דאָס האָבען געפרעגט ניט די בחירים, אָבער בכלל איז דאָך דאָס געווען פאַר מתן תורה, איז וואָס האָבען זיי געוואוסט, און זיינען נעבעך געווען אין אַזאַ קלעם. משה האָט מרגיש געווען זייער ניט גוט גשמי און איז בטל געווען פאַר יעדער נימול. ומפני זה זכה לגילוי נון פלאות.\nאַ וואָרט נאָך פופציג יאָהר הויבט ער אָן צו בורען (תוסס).\nל. כמוס עמדי חתום באוצרותי<sup data-n=\"1671\">39</sup>. מהו החילוק בין חתום לכמוס ומהו חתום באוצרותי.\nדער חילוק פון די ביידע לשונות איז: אַ אוצר ליגט אין אַ מקום משומר, אָבער דער מענטש אַליין גייט אַוועק פון דעם; כמוס עמדי מיינט, אַז וואו מען גייט און וואו מען געפינט זיך איז דאָס כמוס עמדי.\nאיך האָב אַ שליחות וואָרט, וואָס איך האָב געהערט מיט פופציג יאָהר צוריק, וואָס דאַמאָלסט האָט מען דאָס ניט געדאַרפט דערציילען.\nעס איז פאַראַן אַ זמן וואָס מען דאַרף ניט זאָגען און עס איז פאַראַן אַ זמן וואָס מען מוז זאָגען. הגם דאָס איז נוגע זיך, דאַרף מען דאָס טאָן מיט אַ מסירת נפש<sup data-n=\"1672\">40</sup>. ע\"ד ווי ביי משרע\"ה, משה קיבל תורה מסיני<sup data-n=\"1673\">41</sup>, איז הגם התורה ניתנה לו<sup data-n=\"1674\">42</sup>, פונדעסטוועגען — ומסרה ליהושע, מיט אַ מסירה ונתינה, ער האָט זיך אַליין אַוועקגעגעבען.\nאיך האָב אַ סך מאָל געטראַכט, דער­ציילען אָדער ניט, היינט האָב איך מחליט געווען דאָס מגלה צו זיין. דער סדר אין דעם איז ווי אין תורה. אין תורה איז פאַראַן דער סתום און דער גליא. אין אַ ספר תורה מוז זיין פריהער חלק, דער גויל<sup data-n=\"1675\">43</sup>, נאָכדעם הויבט זיך אָן ספר בראשית<sup data-n=\"1676\">44</sup>, אַ סיפור מעשה, אַ תינוק קען תופס זיין אַ סיפור און עס איז זיך ביי איהם מתקבל על הלב, מיר זיינען אַלע תינוקות — וועל איך דאָס מגלה זיין אין אַ סיפור, אין אַ סיפור איז אויך פאַראַן דער גליא און דער סתום, וועל איך דערוויילע מגלה זיין נאָר דעם גליא פון דעם סיפור און דאָס וועט זיין בכתב.\nלא. תרנ\"ב האָט מען געהערט אַ וואָרט: פתחי לי כחודה של מחט ואני אפתח לכם כפתחו של אולם<sup data-n=\"1677\">45</sup>. דער",[["1669","37","[ראה לעיל ע' 151."],["1670","38","בשלח טז, ג."],["1671","39","לשון הכתוב — האזינו לב, לד."],["1672","40","ראה לקו\"ש חי\"ח ע' 477."],["1673","41","אבות פ\"א מ\"א]."],["1674","42","נדרים לח, א."],["1675","43","זע לקו\"ת ביאור דבחוקותי. שם שה\"ש ד\"ה שחורה אני (הראשון) פ\"ג. ובי' דשימני כחותם פ\"ג. שיחת פורים [תש\"ד] (קונטרס עה) אות ג [(סה\"מ ה'שי\"ת ע' 138. ספר השיחות תש\"ד ע' 66)."],["1676","44","ראה גם שיחת פורים שנה זו (לעיל ע' 306)."],["1677","45","כן הובא בהקדמה לספר חרדים. ובכ\"מ בדא\"ח (ראה לקו\"ת קרח נה, א. שה\"ש לה, ג. סה\"מ תש\"ג ע' 198). וראה שהש\"ר פ\"ה, ב [ב]. יל\"ש שה\"ש רמז תתקפח. תנחומא (באָבער) תולדות יח. זח\"ג צה, א]."]]],[4301620544,"חודה של מחט האָט ניט קיין תפיסת מקום, הגם דער מחט האָט דאָך יאָ אַ מקום, אָבער דער שפּיץ, דער חודה של מחט, האָט ניט קיין מקום, מאַכען אַ פתח קען מען נאָר מיט אַ זאַך וואָס האָט ניט קיין מקום. דער פתח האָט יע אַ מקום, אַ אורך ורוחב און גובה, אָבער אויפמאַכען דעם פתח איז נאָר מיט אַ זאַך וואָס איז ניט תופס מקום.\nפתחי וכו' כפתחו של אולם. אין דעם פתחו של אולם וואָס האָט דאָך אַ אורך ורוחב וגובה וועט זיך דאָרט דערהערען דער חודה של מחט.\nלב. אַמאָל האָט מען געמאָנט השכלה השגה, אָבער דער עיקר האָט מען גע­מיינט דעם שפיץ.\nלג. באַ אַמאָליגע חסידים איז געווען אַ וואָרט: ביטער.. . אַי, ביטער.. .\nדער אויבערשטער זאָל העלפען איך זאָל זעהן נחת אין אידען בכלל און אין חסידים בפרט אין גשמיות און אין רוחניות, און בפרטיות אין עבודה.\nלד. חסידות מאָנט בכן­ע\"ב<sup data-n=\"1678\">46</sup>, שם ע\"ב טראָגט אַרויס אַלץ. עס זיינען פאַראַן שם מ\"ה, ס\"ג, ב\"ן, אָבער ע\"ב, דאָס טראָגט אַרויס אַלץ.\nלה. עס איז ווייניג עבודה. מען לערענט דעם מאמר און מען זאָגט ביאורים, דער זאָגט אַזוי און דער זאָגט אַזוי, עס פאַרדריסט פאַרוואָס יענער פאַרשטייט אים ניט, ווי ער אַליין פאַר­שטייט זיך. מען איז יענעם מבטל, וואָס ווייס ער, וואָס האָט ער געזעהן — אָבער טאָן און אויפטאָן אין עבודה, דאָס פעלט.\nלו. (אחר הסעודה הזכיר כ\"ק אדמו\"ר שליט\"א עוד הפעם ע\"ד שהחסידים הישנים עשו בכל יום קמט בהסידור, שאל אחד: ווי אַז מען האָט נאָך ניט אָנגעפאַנגען דעם ערשטען קנייטש, וענה כ\"ק אדמו\"ר שליט\"א:)\nמען דאַרף וויסען ווער עס פרעגט עס, אויב דער \"קלוגינקער\", ער אַרבעט אויף אַלע כלים, איינעם הויבט ער, אַ צווייטען וואַרפט ער. מען דאַרף ניט אַראָבפאַלען ביי זיך, ניט מצד שנים, די עלטער, ניט מצד געזונד דאַרף זיין אַ מניעה צו עבודה, מען דאַרף טאָן און אויפטאָן.\n<h4>סעודת יום אחרון של פסח תש\"ט</h4>\nלז. חינוך אמיתי איז — אַז אַ יחיד איז אַ רבים, ווייל באמת יעדער יחיד איז אַ רבים, ער איז בכח צו מאַכען אַ רבים און באַלעבן אַ רבים<sup data-n=\"1679\">47</sup>.\nדאָס איז ביי אידען בכלל און ביי חסידים בפרט.\nלח. אידען זיינען אַ גוי אחד בארץ, אַז אין ארציות זאָל זיך דערהערען דער אחד הוי'; ביי מתן תורה האָט דער אויבערשטער געגעבען דעם כח אַז דער גוי — די אידען — זאָלען ממשיך זיין דעם הוי' אחד אין ארץ<sup data-n=\"1680\">48</sup>.",[["1678","46","זע קונטרס לימוד החסידות פ\"ג [אגרות­-קודש ח\"ג ע' שלה]."],["1679","47","[נת' בארוכה בשיחת יו\"ד שבט תש\"מ. וראה אגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' רסז."],["1680","48","ראה תו\"א וישב כז, סע\"ד. וראה אגה\"ק ס\"ט (קיד, א)]."]]],[4301620545,"דאָס איז די שליחות און מטרה פון ירידת הנשמה למטה — אויף ממשיך זיין דעם הוי' אחד אין ארץ.\nלט. אַמאָל איז געווען אַ אוזן שומעת, היינט איז ישיבת כרכים קשה<sup data-n=\"1681\">49</sup>. דאָס איז גלות בתוך גלות, אפילו מען זיצט ביי זיך אין שטוב, פאַרמאַכט די פענסטער פאַר­מאַכט די לאָדענס, ווייל דער אויר איז אַ אַנדערער, אויר איז אור יו\"ד<sup data-n=\"1682\">50</sup>, דאָ איז דער אויר אַ אַנדערער, און דאָס איז דער גלות בתוך גלות.\nאין אַ קליין שטעטיל איז דער אויר אַ אַנדערער.\nדי הונדערט יאָהר<sup data-n=\"1683\">51</sup> וואָס מ'האָט געטאָפּטשעט אין בלאָטע אין ליובאַוויטש האָט מען געמאַכט אַז אין די בלאָטע זאָל זיך דערהערען דער הוי' אחד<sup data-n=\"1684\">52</sup>.\nאָבער מ'דאַרף ניט נתפעל ווערען, מ'דאַרף זיין ווי אַ סאָלדאַט, אַ סאָלדאַט טוט זיין אַרבעט מיט מסירת נפש.\nמ. מען האָט שוין אַמאָהל<sup data-n=\"1685\">53</sup> גערעדט פון מעלת הציור.\nאַמאָהל<sup data-n=\"1686\">54</sup> איז דער טאַטע מיט מיר געגאַנגען אין ראָסטאָוו אין גאַס האָט ער זיך אָפּגעשטעלט פאַר אַ פענסטער וואו עס זיינען געשטאַנען אויסגעשטעלט מאַשינעס פון עבודת הארץ, ווי אַזוי צו שניידען תבואה און אָפּהיטען יעדער קערענדעל אַז עס זאָל ניט גיין פאַר­לוירען און אַז אפילו דער שטויב זאָל זיין לתועלת.\nהאָט כ\"ק אאמו\"ר הרה\"ק אַרומגע­רעדט די אַלע ענינים, און יעמאָלט געזאָגט אַז דאָס איז אַ משל פון ירידת הנשמה למטה בגוף אין איר תבואת הארץ<sup data-n=\"1687\">55</sup>.\nעס איז פאַראַן אַ משל און אַ נמשל, פון דעם משל פאַרשטייט מען דעם נמשל, כ\"ק אאמו\"ר הרה\"ק איז געווען אַזוי אויסגעאַרבעט, אַז ער האָט געזעהן אין משל דעם נמשל.\nדאָס איז געווען ראי' ניט הבטה.\nמא. עס איז דאָ אין וועלט אַ אויס­שפּראַך אַז מ'האָט ב\"ה אויפגעטון.\nבאמת האָט מען ב\"ה אויפגעטון, וואָס אין דער קאַלטער אַמעריקא איז דער אַייז געטאַיעט (נמס), עס איז אַראָפּגענו­מען געוואָרען די האַרטקייט און שפּיצי­קייט, אָבער עס איז נאָך ניט קיין וואַסער, עס קען נאָך קאַלט מאַכען די וואַרימע.",[["1681","49","זע שיחת פורים [תש\"ד] (קונטרס עה) אות טו [(סה\"מ ה'שי\"ת ע' 144 ואילך. ספר השיחות תש\"ד ע' 73)]."],["1682","50","זע תורה אור פ' מקץ סד\"ה נר חנוכה מצוה. ועוד."],["1683","51","[תקע\"ג­ד<sup data-n=\"e36\">*</sup> — תרע\"ו<sup data-n=\"e37\">**</sup>."],["1684","52","ראה גם לעיל ע' 163]."],["1685","53","זע שיחת שבועות תרצ\"ד [סעיף יו\"ד]. שיחת פורים הנ\"ל."],["1686","54","[ראה שיחת אחש\"פ תש\"ז. ליל ב' דחה\"פ תש\"ח (לעיל ע' 121. ע' 204)]."],["1687","55","זע תורה אור פ' שמות ד\"ה הבאים ישרש. אור התורה דארט."],["e36","*","אדמו\"ר האמצעי קבע דירתו בעיר ליובאַוויטש ביום ב', פרשת נצבים­וילך, י\"ח אלול תקע\"ג (אגרות­-קודש ח\"ג ע' תקב ואילך. ספר השיחות קיץ ה'ש\"ת ע' 95. ועוד). ההתיישבות בקביעות היתה בחודש מר­חשון שנת תקע\"ד (ספר השיחות שם בהערה 76 ע\"פ שיחת י\"ט כסלו תרצ\"ג ס\"ח). במקום אחר איתא שבקיץ (חודש תמוז) תקע\"ד התיישב אדמו\"ר האמצעי בליובאַוויטש (רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 232. קונטרס אדמו\"ר \"הצמח צדק\" ותנועת \"ההשכלה\" ע' 3)."],["e37","**","ביום א', ט\"ז מר­חשון (שיחת י\"ט כסלו שם) עוזב כ\"ק אדמו\"ר מהורש\"ב את ליובאַוויטש ומעתיק את מושבו לעיר רוסטוב ע\"נ דאן."]]],[4301620546,"עס איז ניט קיין להכעיס אידען, עס איז מהיכי­תיתי אידען.\nאַז מען שטעלט אַריין אין אייז אַ כלי מיט הייסע וואַסער מאַכט עס אַ תוך אָבער עס איז נאָך אייז, עס מאַכט מעהר קאלט די וואַסער ווי עס איז פועל אויפן אייז, אָבער אַז מען נעמט וואר­וואַסער — זודיקע וואַסער — יעמאָלט מאַכט דאָס אַ טיפען תוך, אָבער עס איז נאָך אַלעס ניט קיין וואַסער.\nווען מען גראָבט טיפער ווערט מים מתוקים.\nדאָס איז ניט קיין דרוש ניט קיין ציור שכלי, נאָר דאָס איז דער אמת אין פועל. מען זאָגט דאָס — אַז די אומנים זאָלען וויסען וואו זיי האַלטען אין דער מלאכה.\nמב. אין די יאָהרען וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט גערעדט בארוכה (משנת נו\"ן עד נ\"ד) האָט זיך אַמאָהל גערעדט וועגען דעם ציור הענין וואָס פון תורה, עבודה, אַ פועל טוב און מצות מעשיות ווערען באַשאַפען מלאכים<sup data-n=\"1688\">56</sup>. פון יעדען אות אין תורה, אַזוי אין עבודה, און אַ פועל טוב און מצות מעשיות ווערט פון אַלעס באַשאַפען אַ מלאך.\nפון דעם איז דאָ קאַלטע מלאכים און הייסע מלאכים, און זיי זיינען מקנא איינער דעם אַנדערען. די קנאה איז במחשבה.\nמלאך מיכאל און מלאך גבריאל קוקען זיך צו וואָס פאַר אַ חברה דאָס איז, עס איז אַ גרויסער רעש, און מיט וואָס איז מען זיי משכך — מיט די אותיות פון תפלה, מיט דעם גיסט מען זיי אפ, און מיט די התבוננות והתפעלות המוח, וואָס דאָס איז קאַלטע וואַרימקייט און עס גיט אַ ברען, מיט דעם איז מען זיי משכך.\n(וסיים כ\"ק אדמו\"ר שליט\"א:) אַ קינד הערט דאָס. מ'האָט אַ ר' הענדל<sup data-n=\"1689\">57</sup>, ר' ניסן<sup data-n=\"1690\">58</sup>, און זיי פיטשקען דאָס אַריין — איז צו זיבעציג יאָהר איז מען מקנא יענעם זמן.\nמג. עס איז פאַראַן וואָס מען ווינשט זיך, וואָס איינער ווינשט דעם אַנדערען, און ווי יעדער ווינשט זיך.\nאיך קוק אויף יעדען יחיד ווי אויף אַ רבים. יעדער תמים קען אויפמאַכען אַ גאַנצען ישוב. עס איז אָבער דאָ אין דעם צוויי מניעות: ערשטענס מען ליגט אין הבלים, און צווייטענס וואָס מען נאַרט זיך, מען פרעגט ווער בין איך. הגם עס איז אמת — אָבער עס איז שלא במקומו.\nפרעגען פרעגט דאָס דער קלוגינ­קער, ניט דער נפש אלקית וואָס ער איז דער אמת'ער חכם. דער נפש הבהמית איז דאָך אַ שקרן, ער איז אַ בעל גוונים: ער לאַכט, ער וויינט. דער לאַכען איז געלייגט, דער וויינען איז געלייגט, ער איז אַ ליגנער, ער לייגט. ווען ער שטייט, ווען ער זיצט, אפילו ווען ער גייט, וואָס ער איז דאָך אַ מהלך, פונדעסטוועגען לייגט ער.\nנאָר מ'דאַרף ניט נתפעל ווערען, אַ סאָלדאַט גייט מיט אַ ראניעץ אין פאחאד, חאָטש ער גייט דאָך אין אַ מקום סכנה, גייט ער מיט אַ ניגון פון שמחה<sup data-n=\"1691\">59</sup>. הגם וואָס קען אַ סאָלדאַט — ער קען נאָר שיסען, און גייט מיט מסירת נפש, אָבער",[["1688","56","[ראה שיחת ליל ב' דר\"ה שנה זו (לעיל ע' 275)."],["1689","57","ראה אודותו — לעיל ע' 17. וש\"נ."],["1690","58","ראה אודותו — לעיל ע' 41. וש\"נ."],["1691","59","ראה שיחת אחש\"פ תש\"ז (לעיל ע' 122). וש\"נ."]]],[4301620547,"ער גייט מיט שמחה און דאָס מאַכט אים פאַר אַ מנצח<sup data-n=\"1692\">60</sup>.\nמד. אַ יישר כח פנימי די וואָס זיינען געפאָרען אין מיין שליחות מעורר צו זיין אידען<sup data-n=\"1693\">61</sup>, זיי ווייסען אַליין ניט וואָס זיי האָבען אויפגעטון.\nעס קומט אַ יונגערמאַן אין אַ שטאָט און ער רעדט מיט אַ אידען, ער גיט אַ קוועטש מיטן פינגער — שפּריצט אַרויס תמימות. ער דערמאָנט זיך אויף די זכרונות פון זיין טאַטען, פון זיין זיידען, ער ווערט נתפעל: אַ בחור מיט אַ באָרד איז געקומען מעורר זיין, ער רייסט זיך אָפּ פון זיינע עסקים, און קומט צו­לויפען אַ פאַרשוויצטער און פירט איהם מיט זיין קאַר, וכו'.\nהגם דער מעורר אַליין ווייס ניט וואָס ער האָט אויפגעטון<sup data-n=\"1694\">62</sup>.\n— מ'דאַרף זיין אַ דעתן האָבען אַ חוש הראי' און אַ חוש השמיעה אויף צו דערקענען. —\nער האָט אָבער זיין שכר, אַז ווען ער גיט אַ טראַכט פאַרן דאַוונען ווערט ער נתפעל פון דער תמימות פון דעם אידען.\nאיך גיב אַ יישר כח ברבים, וואָס אַ יישר כח איז אַ חיזוק און אַ נתינת כח בגשמיות וברוחנית. איך גיב זיי אַ ברכה כפולה ומכופלת עס זאָל אַראָפּקומען אין מוחין, אין מדות, און עס זאָל אַרויס­רופען אַ תשוקה אויף וועלען טון נאָך.\nמה. איך וויל אייך דעציילען אַ סיפור המעשה, — (הפסיק וצוה לנגן ניגון. אחר הניגון אמר:)\nדי מעשה איז געווען נאָך אַ יחידות. וואָס די יחידות איז געווען וועל איך אייך ניט זאָגען נאָר דעם סיפור המעשה.\nווען כ\"ק אאמו\"ר הרה\"ק פלעגט אַריינגיין אויף יחידות צום זיידען — כ\"ק אאזמו\"ר",[["1692","60","הובא באגרות­-קודש כ\"ק אדמו\"ר שליט\"א ח\"ג ע' רסה ואילך, ומבאר שם: \"אין איש החיל עושה את הקנה רובה וגם אין זה ביכלתו. אינו משיג בשכלו איך יורה הקנה רובה בפרט וטכסיסי המלחמה בכלל, אבל מוסר הוא את נפשו ורצונו למפקד המלחמה ועושה את זה בשמחה ואז דוקא הוא המנצח.\nובמוחש רואין שהיסוד לכל זה היא האמונה שמאמין בראש כל מפקדי המלחמה הוא המלך והנשיא, במלחמה הרוחנית היינו הנשיא מנהיג הדור. ובדורנו בפרט — הוא כ\"ק מו\"ח אדמו\"ר הכ\"מ, שהורה והעמיד את כל אחד ואחת מאתנו במקום מיוחד בשדה המלחמה נגד צד הלעומת זה\"]."],["1693","61","אויף דער פקודה פון כ\"ק מו\"ח אדמו\"ר הכ\"מ זיינען מסודר געוואָרען פון צייט צו צייט, דורך \"מחנה ישראל\", נסיעות פון תלמידי התמימים — ספעציעל אין זייערע ימי החופש — וועלכע האָבן באַזוכט אַ גרויסע צאָל שטעט אום צו באַקאַנען זיך אויפן אָרט מיטן מצב היהדות בכלל און מצב החינוך בפרט, מעורר און מחזק זיין אַלט און יונג, פאַרשפּרייטען די ספרים און חוברות וועלכע זיינען אַרויסגעגעבען דורך דעם מל\"ח (מרכז לעניני חינוך) און דורכפירען פאַרשידענע אַנדערע שליחות'ן אין חיזוק היהדות און חינוך הכשר.\nכ\"ק מו\"ח אדמו\"ר הכ\"מ האָט געהאַלטען די נסיעות פאַר זייער וויכטיק און האָט זייער מייקר און מחשיב געווען די נוסעים. ע\"פ הרוב פלעגען זיי, אין צוזאַמענהאַנג מיט די נסיעות זוכה זיין אויפגענומען צו ווערען אויף יחידות און באַקומען הוראות בכלל און בפרט אין דעם אופן ווי דורכצופירען זייער שליחות אין די נסיעות.\nדעם חוה\"מ פסח האָבען, אויף דער התעוררות פון כ\"ק מו\"ח אדמו\"ר הכ\"מ, אַ ריי תלמידי התמימים — פּאָרווייז — באַזוכט אַ צאָל אידישע קהילות אַרום ניו­יאָרק. די ערשטע באַריכטען פון די נסיעות זיינען אָנגעקומען נאָך פאַר די אַנדערע טעג פסח, און צו די נוסעים זיינען עס געווענדעט די אויבען דערמאָנטע רייד."],["1694","62","[ראה גם לקו\"ש ח\"ב ע' 369 ואילך]."]]],[4301620548,"מוהר\"ש — איז נאָך יחידות פלעגט ער אים דערציילען אַ סיפור<sup data-n=\"1695\">63</sup> וואָס דער סיפור האָט געהאַט אַ שייכות צו דער יחידות, על דרך ווי קאָמפּאָט וואָס איז בא לאחר הסעודה אָבער עס איז בתוך הסעודה.\nאַ איד דאַרף האָבען אַ חוש אין נועם הוי'<sup data-n=\"1696\">64</sup>. אין אַ חוש איז שייך התפתחות. התפתחות איז דורך פעולה, כמו ווי אין כחות איז דורך פעולות ווערט התפתחות הכחות, וואָס די התפתחות איז אין כלים און אין אור, כמו\"כ איז אין התפתחות אין חושים, נאָר עס איז לפי ערך הכלי, אַ כלי רחבה אַ כלי עמוקה. נאָך דעם ווי דער אַלטער רבי האָט אַריינגעגעבען אין חסידים כחות אין אַ פנימיות, האָבען אַ חוש אין אַ נועם אין אַ אידען, איז דאָס אַ כלי רחבה אויף דעם נועם הוי'.\nמו. שש\"פ תרל\"ז האָט דער זיידע דער רבי מוהר\"ש דערציילט אַ סיפור פון צוויי חסידים וואָס האָבען נאָך גע­קענט דעם מעזריטשער, נאַכהער זיינען זיי געוועזען דעם אַלטען רבי'נס חסידים, פנימיות'דיקע חסידים, זיי האָבען געהאַט אַ הכרה אין אַלטען רבי'ן, ניט השגה נאָר הכרה.\nזיי זיינען געווען דורכגעטאָנענע בעלי עבודה, זיי זיינען געווען ישוב'­ניקעס, בעלי פרנסה בריוח, און זיי האָבען געגעבען דעם רבי'ן גרויסע סכומים פאַר עניני אה\"ק און פאַר זיינע עניני הכלל.\nדי צוויי חסידים זיינען געווען חלוק אין זייער עבודה, ביי איינעם איז געווען פון אונטען אַרויף, און ביי איינעם פון אויבען אַראָפּ. איינער האָט אָנגעפאַנגען פון פועל, יעדער זאַך האָט ער געטאָן בפועל ממש מיט אַ מסירת נפש, נאַכהער איז געווען השגה, דער אַנדערער — איז פריהער געווען הבנה והשגה און נאַכהער דער פועל.\nאַמאָהל האָט דער רבי געשיקט צו ביידען אַ שליח ער זאָל בעטען געלד ביי זיי, דער שליח איז געקומען צו דעם \"פון אונטען אַרויף\" און ער האָט אים געזאָגט: דער רבי דאַרף האָבען געלד, האָט ער געפרעגט וויפיל, האָט דער שליח גע­זאָגט דער רבי האָט ניט געזאָגט. איז דער ישובניק אַריינגעגאַנגען און אַרויס­גענומען וויפיל ער האָט געהאַט און אַוועקגעגעבען.\nדער שליח איז געגאַנגען צו דעם צווייטען און האָט איהם געזאָגט דער רבי האָט געשיקט נאָך געלד. האָט ער גע­פרעגט וויפיל, האָט דער שליח ווייטער געזאָגט דער רבי האָט ניט געזאָגט וויפיל, האָט ער איהם געזאָגט: איך וועל צופאָרען אין ליאָזנא פרעגען דעם רבין וויפיל ער דאַרף, וועל איך געבען.\nדער שליח איז געקומען צוריק צום רבין און אַוועקגעלייגט די פּעקלעך, האָט איהם דער רבי געפרעגט וואו איז די געלד פון צווייטען, האָט ער געזאָגט וואָס דער צווייטער האָט געענטפערט.\nהאָט זיך דער רבי פאַרחב\"ד'ט און האָט געזאָגט: קודם המעשה, אָדער לאחר המעשה?\nצומאָרגענס מיט'ן טאָג איז דער ערשטער געקומען אין ליאָזנא, ער איז אַריין צום רבין, האָט איהם דער רבי געזאָגט מ'דאַרף אַרויספאָרען.\nהאָט ער גלייך איינגעשפּאַנט און איז אַוועקגעפאָרען — עס איז נאָך געווען פאַר'ן דאַוונען — און האָט גענומען פאַר­",[["1695","63","ראה גם שיחת פורים שנה זו (לעיל ע' 307)."],["1696","64","בארוכה וועגען נועם הוי', ע\"פ חסידות, זע די מאמרים פון אחש\"פ און ש\"פ שמיני ה'תש\"ט (קונטרס סה) [סה\"מ תש\"ט ע' 130 ואילך]."]]],[4301620549,"קויפען אַלעס וואָס ער האָט געקענט, און איז מיט די בני בית געגאַנגען פאָרען. כאָטש ער האָט ניט געוואוסט וואו צו פאָרען האָט ער געזאָגט אַז דער רבי הייסט פאָרען דאַרף מען פאָרען. פּלוצלינג איז געוואָרען זעהר פינסטער, עס איז געווען אַ זומער רעגען האָט געגעבען אַ גאָס אַ 15 מינוט און עס האָט באַלד אויפגעהערט. ער איז אָנגעקומען אין ליאָזנא, אַוועקגעשטעלט די ב\"ב און איז געגאַנגען אין ביהמ\"ד דאַוונען.\nדער אַנדערער איז אויפגעשטאַנען אין דער פריה, האָט ער געטראַכט וואָס וועט ער פאָרען פאַר'ן דאַוונען, ער וועט אָפּדאַוונען און זייגער צוועלף­איינס וועט ער פאָרן צום רבין.\nדערווייל איז געוואָרען אַ גרויסער שטורם, און עס האָט געגעבען אַ בליץ און פאַרברענט די גאַנצע גאַס, און ער האָט קוים אַרויסגעראַטעוועט די נפשות.\nהאָט דער זיידע געזאָגט: דאָס איז דער חילוק פון פאָלגען ביז פאָלגען, ביידע האָבען געפאָלגט. ביי דעם איז געווען אומר ועושה — ער האָט גלייך געטאָן בפועל. און ביי דעם איז פריער געווען אַ יישוב הדעת און נאַכהער טאָן.\n(וסיים כ\"ק אדמו\"ר שליט\"א:) די מעשה דאַרף מען הערען, עס איז נוגע אַזוי ווי עס איז נוגע חסידות אַזוי איז נוגע די מעשה, אַזוי ווי מען האָרעוועט אויף פאַרשטיין אַ חסידות, אַזוי דאַרף מען האָרעווען אויף פאָלגען.\nמז. מען האָט זעהר געקלאַפּט אין טיר, ואמר כ\"ק אדמו\"ר שליט\"א: מען קלאַפּט מיט אַ אמת. ורצה הרא\"ס ללכת לפתוח. ואמר כ\"ק אדמו\"ר שליט\"א: מ'דאַרף זעהן ווער עס איז. דער טאַטע איז געשטאַנען אַ גאַנצע נאַכט אויף אַריינ­צוגיין צום זיידען.\nמח. העמידו את הקאַמפּאָט לפני כ\"ק אדמו\"ר שליט\"א האָט ער עס אַוועק­גערוקט אין אַ זייט ואמר: מיר האָבען נאָך אַ סך צו טון, וצוה לנגן את הניגון של אדמו\"ר הזקן בעל ד' בבות, ואמר: עס זאָלען זינגען נאָר די וועלכע קענען, ואמר לש. ז. קודם שהתחיל לנגן: זיי זיך מכין.\nמט. אחר שתיית כוס של ברכה — שבירך עליו כ\"ק אדמו\"ר שליט\"א אמר: עס איז געשמאַק צו געבען אידען, מ'דאַרף זיין אַ כלי פנימי צו דעם, עס זאָל זיין להצלחה בגו\"ר. וסיים: מ'דאַרף וויסען ווער עס גיט און ווער עס נעמט.\nכ\"ק אדמו\"ר שליט\"א נתן לכל הנאספים בעצמו — בידיו הק' — מכוס של ברכה, וקרא בשם כל אחד ואחד, ועל כל אחד ואחד הביט כ\"ק בפניו קודם הנתינה.\nנ. ביום ו' עש\"ק אסרו חג אחרי הצהרים מסר כ\"ק אדמו\"ר שליט\"א ע\"י מ. ש. שהתלמידים יחזרו דא\"ח ברבים, ועכ\"פ ידברו דברי התעוררות בש\"ק הזה פ' שמיני, שבת מברכין חודש אייר ובשב\"ק הבע\"ל שבת ר\"ח אייר.\nמ. ש. שאל: עס איז דאָך שוין פרייטאָג נאָכמיטאָג וקצר הזמן לסדר הדבר. וענה כ\"ק אדמו\"ר שליט\"א: אַ שבת וואָס מען זאָגט תהלים פירט זיך אַנדערש."],[4301620550,"<h3>יום ד', י\"ט אייר תש\"ט<sup data-n=\"1697\">1</sup></h3>\nמען דאַרף מסדר זיין די תלמידים שיחי', שבמשך הזמן שנמצאים בהישיבה, ובפרט הקשישים שבהם, לסדר אותם אויף שפּעטער. כמו ווי מען לערנט צו האָבן ידיעה אין לימוד, כמו\"כ דאַרף מען לערנען צו האָבן ידיעה אין עבודה, אין דעם טאָן מיט זיך, און אין דעם טאָן מיט יענעמען. ואפי' הפשוטים שבהתלמידים דאַרף מען מסדר זיין, דעם סדר א' אין לימוד, און סדר ב' אין הסתדרות, כמו לימוד אומנת הזביחה.\nאַז מען ווערט אַ שו\"ב אין אַ שטעטל, גיט דאָס אַ מעגליכקייט מקרב צו זיין די יוגענד צו אידישקייט, און אויפטאָן מיט יענעמען.\nמען דאַרף געפינען ערטער צו לער­נען אומנת הזביחה דגסות, וטוב הדבר להוסיף עוד תלמידים שילמדו אומנת הזביחה.",[["1697","1","מרשימת הרב מרדכי מענטליק<sup data-n=\"e38\">*</sup>."],["e38","*","ראה לעיל ע' 305 בשוה\"ג."]]],[4301620551,"<h3>כ\"ח אייר, עש\"ק פ' במדבר תש\"ט<sup data-n=\"1698\">1</sup></h3>\nדי ידוע'דיגע וואָרט<sup data-n=\"1699\">2</sup>, אַז דער אָרט וואַרט אויף דעם מענטש'ן טויזענטער יאָרען אַז דער מענטש זאָל אַהין קומען און טראַכטן אָדער זאָגן אַ וואָרט תורה אָדער אַ פעולה טובה, איז דאָס ניט נאָר ווען מען פאָרט ערגעץ, נאָר אויך וואו מען גייט זייענדיק אין דער היים צי אין גאַס.\nעס איז פאַראַן אַ שיחה ארוכה פון טאַטן<sup data-n=\"1700\">3</sup>, אַז אפילו אַ בלעטעלע וואָס וואַלגערט זיך, אפילו דבר ההוה ונפסד טוען: בולאַך<sup data-n=\"1701\">4</sup>! וואָס טרעטסטו אויף מיר.\nבעניני קירוב צריך לדבר ולקרב מקל אל הכבד.\nר' גרשון בער<sup data-n=\"1702\">5</sup> אמר: מען דאַרף אויפ­שטיין גאָר אַן אַנדערער ווי נעכטען<sup data-n=\"1703\">6</sup>.\n[והמשיך כ\"ק אדמו\"ר שליט\"א:] על הבר מצוה של קרעמער תפגוש אנשים שונים, תדבר עמהם וועגען אידישקייט.\n[ספרתי אודות מרכז משפחתי בקאַלי­",[["1698","1","מרשימת הרב שלמה אהרן קאַזאַרנאָווסקי — \"ראשי פרקים בהיכל כ\"ק אדמו\"ר שליט\"א עש\"ק במדבר תש\"ט, בבואי מלאָס אַנג'עלאס\"."],["1699","2","ראה ספר השיחות תש\"ג ס\"ע 12 (הועתק (בשינויים) ב\"היום יום\" טו אדר א). וראה גם רשימת היומן של רבינו מיום ה' כז מנ\"א תרנ\"ו (לקו\"ד ח\"ד תקצו, סע\"א ואילך)."],["1700","3","ראה ספר השיחות תרפ\"ח­תרצ\"א ס\"ע 155 ואילך (הועתק ב\"היום יום\" ז אדר שני): \"אַז מען גייט אין גאַס דאַרף מען טראַכטן דברי תורה. . צי אין מחשבה אָדער אין דיבור, וואָס דאָס ווענדעט זיך אָן דעם אָרט וואו ער גייט צי מען מעג ע\"פ דין ריידן דאָרטן דברי תורה. אָבער אַז ער גייט אין גאַס און איז ניט פאַרנומען אין דברי תורה, זאָגט אים דער שטיין אויף וועמען ער טרעט: דו בולאַך איינער, וואס טרעטסטו אויף מיר? ווער ביזטו, מיט וואָס ביזטו העכער פון מיר? פאַרוואָס זאָל איך ניט טרעטן אויף דיר?\". וראה גם אגרות­-קודש ח\"ד ע' קנא (הועתק ב\"היום יום\" טו אדר א). ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 17. קיץ ה'ש\"ת ע' 87."],["1701","4","גולם."],["1702","5","ראה אודותו — לעיל ע' 5. וש\"נ."],["1703","6","ראה לעיל שם. וש\"נ."]]],[4301620552,"פורניא, ואמר כ\"ק אדמו\"ר שליט\"א:] עס דאַרף ניט זיין די קאנטעטקייט, דער זיין צופרידן פון זיך ווען מען טוט אַ גוטע זאַך."],[4301620553,"<h3>ליל א' דחה\"ש בסעודה תש\"ט<sup data-n=\"1704\">1</sup></h3>\nא. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט אָנהויבען זאָגען תיקון שבועות באַלד נאָך ליכט צינדען אין אָנהויב פון ליל חג השבועות, דערנאָך מפסיק געווען און נאָך דער סעודת יו\"ט ווייטער ממשיך געווען.\nב. רז\"ל זאָגען<sup data-n=\"1705\">2</sup> חרדה מסלקת הדמים. היינט ווי איז געווען נאָך אַזאַ חרדה — ציטערניש — ווי ביי מתן תורה<sup data-n=\"1706\">3</sup>.\nג. הוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל אַרום גערעדט בארוכה דעם ענין החרדה וואָס איז געווען ביי אידען בעת קבלת התורה. משה רבינו האָט געוואוסט און משער געווען פריער וואָס פאַר אַ חרדה עס וועט זיין, פונדעסטוועגען איז דאָס כלל ניט געווען בערך צו דער חרדה וואָס איז געווען בפועל.\nד. החסיד ר' גרשון דוב פּאַהאַרער<sup data-n=\"1707\">4</sup> פלעגט זאָגען נאָך קריאת שמע שעל המטה: אַה! מאָרגען דאַרף מען אויפ­שטיין גאָר אַ אַנדערער<sup data-n=\"1708\">5</sup>.\nשבועות ביינאַכט דאַרף מען זאָגען: מאָרגען אין דער פריה דאַרף מען זיין גאָר אַ אָפּגעפרישטער.\nה. אַמאָל — דאָס זאָג איך דברי הרב — פלעגט מען מייקר זיין אַ וואָרט פון אַ עלטערען חסיד אַ עובד, אַ סך מעהר ווי פון אַ חסיד אַ משכיל. באמת איז אַז ביי עובד און משכיל איז ביי זיי פאַראַן ביידע ענינים — עבודה און השכלה —, נאָר דער חילוק איז פון וואנען עס פאַנגט זיך אָן. צי די השכלה האָט געבראַכט צו עבודה, אָדער די עבודה האָט געבראַכט צו השכלה.\nו. אַז מען ווערט עלטער מיט פופציק יאָהר דערהערט מען אַ וואָרט מיט אַ אַנדער ליכטיקייט. עס הערט זיך די פנימי' הנקודה מיט אַן אַנדער קלאָר­קייט. אַז מען איז אינגער איז פאַראַן פערשידענע ענינים וואָס פאַרשטעלען אויף דער פנימיות הנקודה פונ'ם וואָרט, אָבער אַז מען ווערט עלטער הערט זיך דאָס אָן מיט אַן אַנדער ליכטיקייט.\nז. אַמאָל איז געווען אַ סדר ביי מלמדים, אַז נאָכדעם ווי זיי האָבען מבאר געווען און געגעבען צו פאַרשטיין אַ ענין פלעגען זיי זאָגען צום תלמיד: אַז דו וועסט עלטער ווערען וועסטו פאַרשטיין.\nאיז דאָך לכאורה קשה, וויבאַלד אַז ער גיט אים צו פאַרשטיין איז וואָס זאָגט ער אים: אַז דו וועסט עלטער ווערען וועסטו פאַרשטיין. נאָר דאָס איז דער אין סוף פון ידיעת התורה.\nאויף דער חסיד'שער שפּראַך הייסט דאָס, אַז די השגה דבינה זאָל דערהערען די הפלאה פון חכמה, בינה איז הבנה — פאַרשטיין. אָבער אפילו אַז ער פאַר­שטייט איז ער דאָך אַ פתח. אויב ער איז",[["1704","1","נדפס בסה\"מ ה'שי\"ת ע' 242 ואילך עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו."],["1705","2","[נדה ט, א. וש\"נ."],["1706","3","ראה גם ריש וסוף ד\"ה וירא העם וינועו תש\"ד (סה\"מ תש\"ד ע' 228. ע' 235)]."],["1707","4","זע וועגען אים התמים ח\"ה ע' לח ואילך. שם ח\"ח ע' לז ואילך. ספר השיחות קיץ ש\"ת ע' 26 [וראה לעיל ע' 5. וש\"נ."],["1708","5","ראה לעיל שם. וש\"נ."]]],[4301620554,"נאָך אַ מהדר איז אפילו ניט פאַרשטייענ­דיק מיינט ער אַז ער פאַרשטייט, אָבער אפילו אַז ער פאַרשטייט יע, איז אויך דער פתח גרעסער פון דעם פאַרשטיין.\nמה שאין כן אַז השגה דבינה דער­הערט די הפלאה פון חכמה, איז גאָר עפּעס אַנדערש.\nח. ביי אַמאָליקע חסידים איז געווען אַ קאָך אין די ג' אהבות: אהבת השם, אהבת התורה און אהבת ישראל.\nאין די גאָר יונגע יאָהרען האָב איך געהערט אַ אויסשפּראַך פון הוד כ\"ק אאמו\"ר הרה\"ק: דער קדושה'דיקער יחם לבבו.\nמען האָט זיך געקאָכט אין די ג' אהבות. פונדעסטוועגען דאַרף די אהבת ישראל ניט פאַרדעקען צו זעהן יענעמס חסרונות אין חינוך, ידיעה און מדות. נאָר מ'דאַרף יענעם זאָגען בדרך קירוב. מען דאַרף זאָגען זיך, מען קען געפינען די חסרונות ביי זיך אַליין — און מען דאַרף ניט האָבען אויף דעם אַ ריבוי יגיעה, בפרט לאור האמת, — דאַרף מען זאָגען זיך וועט יענער במילא דער­הערען.\nט. דאָ אין אַמעריקע איז אַ ביסעל פאַרטומאַנעט<sup data-n=\"1709\">6</sup>. אַ טומאַן מיינט אַז עס שיינט די זון, נאָר עס איז פאַרטומאַנעט, עס זעהט זיך ניט די ליכטיקייט.\nדאָ אין אַמעריקע, אַז מען טראָגט אַ באָרד און פיאות און מען גיט צדקה מיינט מען שוין אַז מען איז יוצא טויזענד פּראָצענט, אָבער דער אמת איז ווי דער באַקאַנטער חסיד'ישער אויסשפּראַך: לא פגע ולא נגע<sup data-n=\"1710\">7</sup>.\nמען באַדאַרף טאָן מיט דעם זולת.\nי. אמר: מען דאַרף זינגען, אָבער ניט איבערנעמען זיך דערמיט.",[["1709","6","ראה גם שיחת י\"ט כסלו שנה זו (לעיל ע' 290)."],["1710","7","ראה לעיל ע' 161. וש\"נ."]]],[4301620555,"<h3>יום ב' דחה\"ש תש\"ט, בסעודה</h3>\nיא. (רבים דחקו עצמם להכנס, והממונים על הסדר שמרו על הדלת ולא נתנו לכולם להכנס. כשחזר אחד הממונים למקומו אצל השולחן שאל כ\"ק אדמו\"ר שליט\"א: וואָס איז געוואָרען. וענה: עס זיינען דאָ אַזעלכע וואָס מ'וויל ניט זיי זאָלען אַריינגעהן. ואמר כ\"ק אדמו\"ר שליט\"א:) מען דאַרף זען אַז די טעמים זאָלען ניט זיין. מ'דאַרף טאָן, ניט אין דעם ניט אַריינלאָזען, נאָר — אַז די טעמים אויף ניט אַריינלאָזען זאָלען ניט זיין.\n(אח\"כ בא עוד אחד ושאל אותו כ\"ק אדמו\"ר שליט\"א:) וואו האַלט מען ביי הגבל, צי ביי וקדשתו.\nעס איז דאָ דער הגבל את ההר, און עס איז פאַראַן דער וקדשתו<sup data-n=\"1711\">8</sup>. חסידים האַלטען ביי וקדשתו. דער וכבסו שמלותם<sup data-n=\"1712\">9</sup> דאָס מוז זיין. רייניקען, רייבען, קראַצען אפילו די לבושים<sup data-n=\"1713\">10</sup>. וכבסו שמלותם דאָס מוז זיין, דאַן איז דאָ דער הגבל את ההר וקדשתו.\nיב. הוד כ\"ק אאמו\"ר הרה\"ק האָט מיר אַמאָל געזאָגט, אַז מען איז זיך אַמאָל מונע צו זאָגען אַ שאַרפען וואָרט, ווייל",[["1711","8","יתרו יט, כג."],["1712","9","שם, י]."],["1713","10","זע אויך \"היום יום\" ה' סיון ה'תש\"ג [ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 243."]]],[4301620556,"דעם מקבל וועט עס וויי טאָן, אָבער מען דאַרף דאָך זאָגען.\nאהבת ישראל, דערהערען אַ צווייטען אידען, דאַרף מען דאָס פיהלען בתוך ופנימיות, — אין פנימיות פון תוך.\nיג. עס איז אַ חילוק פון דעם חסיד'ישען חינוך ביז דעם סתם חינוך. מ'מיינט ניט דעם פרייען חינוך, פון דעם רעדט מען ניט, נאָר אפילו פון דעם פרומען חינוך.\nווען איך בין געווען גאָר אַ קליין קינד, גלייך ווי איך האָב אָנגעפאַנגען צו ריידען, האָט הוד כ\"ק אאמו\"ר הרה\"ק מיר געזאָגט: אַלץ וואָס דו וועסט וועלען פרעגען, זאָלסטו פרעגען ביי מיר.\nהגם איך האָב געהאַט אַ בעזונדער מענטש וואָס האָט אַכטונג געגעבען אויף מיר אין אַלע ענינים, פונדעסטוועגען האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט: אַלע ענינים וואָס דו וועסט האָבען צו פרעגען — זאָלסטו פרעגען ביי מיר.\nווען מען האָט מיר מחנך געווען זאָגען מודה אני<sup data-n=\"1714\">11</sup>, האָט מען מיר געהיי­סען צולייגען איין האַנד צו די צווייטע, און איינבויגען די קאָפּ און אַזוי זאָגען מודה אני.\nווען איך בין געוואָרען אַ ביסעל עלטער, אָבער אַלץ נאָך אין די קינדער­יאָהרען, האָב איך געפרעגט הוד כ\"ק אאמו\"ר הרה\"ק: פאַרוואָס ווען מען זאָגט מודה אני, דאַרף מען צולייגען איין האַנד צו די אַנדערע, און מרכין זיין את הראש. האָט ער מיר געענטפערט: באמת דאַרף מען טאָן ניט פרעגענדיק פאַרוואָס, נאָר איך האָב דיר דאָך געזאָגט דו זאָלסט אַלץ פרעגען ביי מיר.\nהאָט הוד כ\"ק אאמו\"ר הרה\"ק אַריינ­גערופען ר' יוסף מרדכי דעם משרת<sup data-n=\"1715\">12</sup>, אַ איד אַ בן שמונים און האָט אים גע­פרעגט: ווי אַזוי זאָגסטו אין דער פרי מודה אני. ענטפערט רי\"מ: איך לייג צו איין האַנד צו די אַנדערע און בויג איין דעם קאָפּ. פרעגט אים ווייטער הוד כ\"ק אאמו\"ר הרה\"ק: פאַרוואָס טוסטו אַזוי. ענטפערט רי\"מ: איך ווייס ניט. ווען איך בין געווען אַ קליין קינד האָט מען מיך געלערענט אַזוי.\nזעהסט. — זאָגט צו מיר הוד כ\"ק אאמו\"ר הרה\"ק — ער טוט ווייל זיין טאַטע האָט אים אַזוי געלערענט. און אַזוי פריער ביז משה רבינו און אברהם אבינו, וואָס אאע\"ה איז געווען דער ערשטער איד. מען דאַרף טאָן ניט פרעגענדיק פאַרוואָס.\nהאָב איך אַזאָג­געטאָן: איך בין דאָך נאָך אַ קליינינקער. ענטפערט מיר הוד כ\"ק אאמו\"ר הרה\"ק:\nאַלע אידען זיינען קליין, און אַז מען ווערט עלטער זעהט מען ערשט אַז מען איז קליין.\nאָט דאָס הייסט חינוך אמיתי.\nיד. ביי הוד כ\"ק אאמו\"ר הרה\"ק פלעגט זיין זמנים וואָס מצד זיין שוואַכען געזונד פלעגט מען צו פאַר­בריינגען אַריינלאָזען נאָר יחידי סגולה. איך בין דאָך געווען דער מנהל פועל<sup data-n=\"1716\">13</sup> — פון ישיבת תומכי-תמימים — פלעג איך מצדד זיין, אַז ווען איך בין אַריינגע­גאַנגען זאָל די טיהר בלייבען ניט פאַר­שלאָסען, אָדער מ'זאָל קענען פון דער צווייטער זייט עפענען.\nכבוד אמי הרבנית<sup data-n=\"1717\">14</sup> האָט געפרעגט ביי",[["1714","11","ראה גם שיחת ליל א' דחה\"ס ה'שי\"ת (לקמן ס\"ע 359 ואילך)."],["1715","12","ראה אודותו — לעיל ע' 233. וש\"נ."],["1716","13","ראה לעיל ע' 234. וש\"נ."],["1717","14","ראה אודותה — לעיל ע' 21. וש\"נ."]]],[4301620557,"מיר, פאַרוואָס טו איך דאָס, עס איז דאָך נוגע דעם טאַטענס בריאות. האָב איך געענטפערט: איך בין דער מנהל פון תומכי-תמימים דאַרף איך זאָרגען לטובת התלמידים, און צו דעם געזונד פון הוד כ\"ק אאמו\"ר הרה\"ק וועט דאָס ניט שאָדען. אדרבא, עס וועט אים גורם זיין עונג.\nדאָס וואָס מען לאָזט דאָ ניט אַריין, מיינט מען אַודאי אַז מען וועט מיר מכביד זיין אויב מען וועט אַריינלאָזען מעהר, אָבער באמת מיט דעם איז מען גאָר ניט מכביד.\nמען ווייס ניט וויפיעל עס קאָסט.\nטו. דאָס וואָס מען פלעגט ניט אַריינ­לאָזען, איז געוועזען צוליעב אַ תועלת. דער וואָס פלעגט אַריינגיין פלעגט זיין דערפון געהויבען, און דער וואָס פלעגט ניט אַריינגיין פלעגט זיין ביי זיך אַראָפּ­געפאַלען. אָבער אַז דאָס, וואָס דער וואָס גייט יע אַריין איז ביי זיך געהויבען איז דאָס ישות, און דער וואָס גייט ניט אַריין איז ביי אים גסות, עס אַרט אים פאַרוואָס יענער איז אַריינגעגאַנגען און ער ניט — קען מען שוין אַלעמען אַריינלאָזען.\nטז. איך וויל זאָגען אַ שטאַרקען וואָרט. הגם מאָנען איז ניט מיין שיטה, דאָס איז ניט דער דרך החסידות. אפילו ווען מ'דאַרף מאָנען ביי יענעם פאַרוואָס ער איז ניט ווי ער דאַרף זיין, מאָנט מען ביי זיך פאַרוואָס איז יענער אַזוי, אָבער דעם אמת מוז מען זאָגען.\nאיך וויל ניט ריידען אין דעם האַר­בער זייט.\nדי גאַס אין אַמעריקא איז ניט ווי עס דאַרף זיין.\nאיך מיין ניט די ערד, דאָ איז אויס­געברוקירט מיט שטיינער, דאָ איז אַלץ פאַרשטיינערט. מען דאַרף אָבער ליכטיק מאַכען די גאַס.\nמען דאַרף טאָן. עס איז דאָ אַפולע צו טאָן. מען דאַרף אָנפאַנגען מיט די קליינע קינדערלעך און דורכדעם וועט מען מקרב זיין די עלטערען, די באָבעס און די זיידעס.\nיז. מען דאַרף שטאַרק טאָן מיט די קליינע קינדערלעך, מיט די גדיים.\nיח. דורך די צעהן יאָהר וואָס איך בין אין אַמעריקע האָב איך פאַרקערט מיט טויזענדער אידען. זיי זיינען טייערע אידען, אפילו דער וואָס לייגט ניט קיין תפילין ר\"ל, איז, אַז מען איז אים מעורר אויף דעם און ער גיט אַ קרעכץ דאַרף מען דעם קרעכץ מקנא זיין.\nיט. אויף וואָס וואַרט מען. מען איז דאָך מעכב די גאולה.\nעס איז שוין ערב שבת<sup data-n=\"1718\">15</sup> נאָך חצות<sup data-n=\"1719\">16</sup>. יעדער איד ערב שבת איז זיך מכין צו שבת.\nמנהג ישראל תורה היא<sup data-n=\"1720\">17</sup>. יעדער איד ערב שבת נאָך חצות גייט אין וואַסער, וואַשט זיך ארום, און איז זיך מכין צו שבת, ער קויפט אַ סאָטקע<sup data-n=\"1721\">18</sup> — פאַר זיך אַליין דאַרף ער דאָס ניט, נאָר אפשר וועט ער האָבען אַ אורח אויף שבת.\nער שניידט אָפּ די נעגעל, און וואָס עס בלייבט איז ריין אָן טיט ורפש.\nער שטעכט ניט, און אויב שטעכען",[["1718","15","ראה גם לעיל ע' 226. לקמן ע' 391."],["1719","16","ראה לקו\"ש חט\"ו ע' 282. שם ע' 42 ואילך. וש\"נ. ספר השיחות תש\"נ ח\"א ע' 254. וש\"נ."],["1720","17","ראה לקמן ע' 338. ע' 348. וש\"נ]."],["1721","18","נאָמען פון אַ קליינער פלעשל בראָנפען אין רוסלאַנד."]]],[4301620558,"שטעכט ער זיך. אַי יענער דערהערט — נו...\nאון אַזוי אַלץ וואָס ער טוט איז דאָס אַ הכנה צו שבת, און יעדערער איז זיך מכין לפי ערכו.\nמען דאַרף אָנפאַנגען ביי דער מעלה פון אַ אידען.\nכ. הוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל געזאָגט ביי אַ פאַרבריינגען, וואָס ער האָט געהערט פון הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש אויף יחידות אין נאָמען פון הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק, וואָס ער האָט מקבל געווען פון הוד כ\"ק רבינו הזקן:\nאַ איד איז אַ כלי צו עצמות אין סוף, נאָר מען דאַרף אַראָפּנעמען די מסכים אַז עס זאָל נתגלה ווערען דער עצמי. דער רבי — הוד כ\"ק רבינו הזקן — האָט דאָס ממשיך געווען צו חסידים דורך חסידות לדורותיהם.\nדער ענין פועל'ט צוויי ענינים: עס פועל'ט אַ חיזוק און עס צו­ברעכט, עס גיט אַ חיזוק, דאָס וואָס מען ווייס אַז מען איז אַ כלי צו עצמות, און עס צוברעכט אַז מען באַטראַכט זיך, אַז עס איז אַדורכ­געגאַנגען אַ טאָג און מען איז ניט דער­פאָרען.\nכא. הוד כ\"ק אאמו\"ר הרה\"ק האָט אַמאָל געזאָגט: רז\"ל זאָגען<sup data-n=\"1722\">19</sup> אם הרא­שונים כמלאכים אנו כבני אדם, ואם הראשונים כבני אדם אנו כחמורים, ולא כחמורו של רבי פנחס בן יאיר.\nרפב\"י האָט זיך עוסק געווען אין הצלת נפשות<sup data-n=\"1723\">20</sup>. זיין שכר וואָס מען האָט אים געגעבען מלמעלה איז געווען, אַז ער איז געוואָרען אַ בעל­הבית אויף זיין חמור.\nעס זיינען דאָ אַזעלכע וואָס זיינען זיך עוסק אין דעם טוב, און עס זיינען דאָ אַזעלכע וואָס זיינען זיך עוסק אין דעם לא טוב.\nער — רפב\"י — איז געווען אַ בעל­הבית אויף זיין חמור. ביי זיין חמור איז דאָס געווען ניט בהרגש הלב, נאָר בהרגש הדעת<sup data-n=\"1724\">21</sup>.\nאַז מען באַטראַכט די הפלאה פון דעם זעהט מען ווי מען האַלט ביי גאָרניט. ווי מורי הרשב\"ץ פלעגט זאָגען: לא פגע ולא נגע<sup data-n=\"1725\">22</sup>.\nכב. מען דאַרף זינגען דעם רבי'נס ניגון פון די פיר פאַלען. מען זאָל אים זינגען זעהר געלאַסען און הויך ווי מעגליך. דעם פערטען פאַל איבער'חזר'ן פיר מאָל. מען מעג זיך אויפשטעלען ביים זינגען דעם ניגון.\n(ניגנו בעמידה. אחרי שניגנו הניגון אמר כ\"ק אדמו\"ר שליט\"א:)\nעס איז ברור הדבר, אַ רבינס אַ ניגון הערט מען אין גן עדן העליון, דעם ניגון המיוחס — אַזוי האָבען חסידים גערופען דעם רבינס ניגון פון די פיר פאַלען — אין רדל\"א, דלא ידע ולא אתידע.\nא חסיד'ישער ניגון הויבט­אויף דריי טפחים. אַ רבי'נס אַ ניגון מעהרער. דער ניגון המיוחס הויבט­אויף פון עמקי שאול ביז תכלית העילוי. תכלית העילוי איז, אַז השכלה דערהערט זיך אין עבודה.",[["1722","19","[שבת קיב, ב כגירסת התוס' חולין ה, ב (ד\"ה צדיקים). וראה בארוכה לקו\"ש חט\"ו ע' 281 הערה 14]."],["1723","20","זע חולין ז, א."],["1724","21","זע די ספרים וועלכע זיינען אָנגעצייכענט אין סדר הדורות חלק תנאים ואמוראים מע' פנחס בן יאיר."],["1725","22","[ראה לעיל ע' 161. וש\"נ]."]]],[4301620559,"כג. חסידים ב\"ה לעבען. עס דאַרף אָבער זיין להחיות, מאַכען יענעם לעבען, און דאָס פעלט לעת­עתה.\nכד. (אחרי ברהמ\"ז נתן בעצמו בידו הק' מהכוס של ברכה לכל הנאספים. אחד הציע אולי ליתן לאחר לחלק. ואמר כ\"ק אדמו\"ר שליט\"א:)\nאַ איד דאַרף זיך ניט בענוגענען מיט זעהן אַז יענער זאָל טאָן יענעם אַ טובה. נאָר מען דאַרף וועלען אַליין טאָן.\nכה. (אח\"כ נתן לא' לחלק כוס של ברכה לכל הנאספים בביהמ\"ד וצוה להכריז:)\nמען מאָנט ניט קיין סך. יעדער איינער זאָל מאַכען לעבען נאָך איינעם, און דורכדעם וואָס ער וועט מאַכען יענעם לעבען, וועט ער אַליין לעבען.\nכו. ביום שני אחרי ברכת המזון דסעודת ההתועדות ציוה כ\"ק אדמו\"ר שליט\"א לפתוח הדלתות, ונכנסו גם כל אלו שלא הרשום להכנס להסעודה — לקבל פני הרב ולאמר: גוט יום טוב.\nכן בשני הלילות דחג השבועות אחרי תפלת ערבית, נכנסו כל הנאספים להיכל כ\"ק אדמו\"ר שליט\"א לקבל וגם לאמר: גוט יום טוב."],[4301620560,"<h3>חג הגאולה י\"ג תמוז תש\"ט<sup data-n=\"1726\">1</sup></h3>\nא. הוד כ\"ק רבינו הזקן האָט מקבל געווען מרבו הרב המגיד ממעזריטש, וואָס ער האָט מקבל געווען מרבו מורנו הבעש\"ט, דעם וואָרט: וואס געדענקסטו<sup data-n=\"1727\">2</sup>?\nאָט דער וואָרט — וואָס געדענקסטו — האָט מחי' געווען מיט אַ חיות פון תחיית המתים די חסידים לדורותם. תחיית ה­מתים הייסט חיים ארוכים, חיים אמיתיים. מיתה איז הפסק, און חיים ארוכים איז חיים בלי הפסק, וואָס דאָס איז חיים אמיתיים<sup data-n=\"1728\">3</sup>. עס איז ניטאָ דער העדר החיים. עס איז מעהר ווי לעבען. אין עבודה איז דאָס, אַז ניט נאָר וואָס מען לעבט אַליין, נאָר מען באַלעבט אויך אַנדערע<sup data-n=\"1729\">4</sup>.\nדער נקודת הענין איז, אַז חיים אמיתיים איז קדושה<sup data-n=\"1730\">5</sup>, און קדושה איז אין סוף.\nב. אין חסידות איז דאָ ג' ענינים, תורת החסידות, מדות חסידות און הנהגה בדרכי החסידים, וואָס דאָס איז דער ענין פון מוחין, מדות און דאָס וואָס עס איז העכער פון מוחין און מדות.\nמוחין איז תורה, מדות איז תפלה. און נה\"י איז דער בפועל, וואָס די כוונה איז אַז מוחין זאָל אַראָפּקומען אין מדות און פון מדות אין נה\"י, וואָס דאָס איז די הנהגה בדרכי החסידים, און<sup data-n=\"1731\">6</sup> דאָ אין",[["1726","1","כפי שנרשמה ע\"י השומעים. נדפס בסה\"מ ה'שי\"ת ע' 262 ואילך עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו."],["1727","2","ראה לקמן סי\"ז (ע' 336)."],["1728","3","[הובא ונתבאר בשיחת ש\"פ חוקת; י\"ב תמוז — ה'שי\"ת (תורת מנחם התוועדויות ח\"א ע' 119 ואילך. ס\"ע 129 ואילך)."],["1729","4","ראה שיחת ש\"פ פינחס ה'שי\"ת (תורת מנחם התוועדויות שם ע' 146)]."],["1730","5","ראה ד\"ה אתה הבדלת ה'שי\"ת (קונטרס ע) [סה\"מ ה'שי\"ת ע' 42 ואילך]."],["1731","6","ברשימה אחרת נ\"א, וז\"ל: \"און בכדי אַז מוחין ומדות זאָלען אַראָפּקומען אין אַ בפועל אין נה\"י איז דאָס בכח עצם הנפש\".\nואולי יש להסביר עפמשנ\"ת בלקו\"ת מסעי צ, ג. ושם שה\"ש כז, ג בענין דנה\"י חדשים נמשכים מהכתר."]]],[4301620561,"נה\"י דערהערט זיך דער גילוי פון עצם הנפש.\nג. עס איז שווער צו רעדען, און בפרט צו מאָנען, ובפרטי פרטיות צו מאָנען ביי יענעם.\nזעהט, לעבט אַליין און מאַכט לעבען אַנדערע.\nד. מען לערענט חסידות, אָבער מען \"דאַווענט\" ניט.\nעס וועט דאָך ניט אַרויסקומען אין גאַס, קען מען דאָך זאָגען: אַז מען לערענט חסידות און מען דאַווענט ניט — באריכות — לייגט ער אַריין דעם אור החסידות אין אַ כלי מאוסה. מען דאַרף דאָך זיין אַ שומר פיו וכו' זאָג איך אַ כלי לא טהורה. איך וויל ניט פאַראומ­רייניקען מיין מויל צו זאָגען אַ פאַר­פּאַטשקעטע כלי.\nה. ער רעכענט אַז ער פאַרשטייט חסידות, אָבער באמת ווייס ער ניט דעם פירוש המילות, אפילו דעם אלף­בית אויך ניט.\nו. ווען מען וואָלט געטאָן אין עבודת התפלה, ווען מ'וואָלט געדאַווענט בארי­כות וואָלט דאָס אראָפּגעקומען אין יר\"ש, אַז אַ הגה\"ה און אַ יש אומרים פון שולחן ערוך וואָלט אים נוגע געווען.\nאַז מען וואָלט געטאָן אין עבודת התפלה און מ'וואָלט וויסען וואו מען האַלט, וואָלט מען ניט דערעסען ניט דערשלאָפען, מען וואָלט געווייטאָגט, עס וואָלט ניט איינגעגאַנגען קיין שום נחת, אפילו ניט קיין נחת פון קינדער, וואָס דאָס איז דאָך דער גרעסטער נחת אַז קינדער גייען בדרך הישר, איז אפילו דער נחת וואָלט ניט איינגעגאַנגען.\nז. אַה, אַמאָל פלעגט זיין פול די שוהלען פון דאַוונער, מלמדים פלעגען דאַוונען אַלע טאָג. אָבער שבת, ראש חודש, ימים טובים, אַ יומא דפגרא פלעגט זיין פול די שוהל מיט דאַוונער. ניט נאָר וואָס מען האָט געזאָגט די עברי פון דאַוונען, נאָר מען האָט געדאַווענט און געשוויצט, ניט נאָר אַליין געשוויצט, נאָר אויך די ווענט האָבען געשוויצט. די ק\"ש שעל המטה איז געווען ווי עס דאַרף צו זיין, דער חשבון הנפש פון פאַר­גאַנגענעם טאָג, ווי אַזוי און מיט וואָס דער טאָג איז דורכגעגאַנגען. אַזוי ביי דעם מלמד, נאָכ'ן אָפּלערנען אַ גאַנצען טאָג איז ביי אים געווען דער חשבון, און אַזוי אויך ביי דעם בעל עסק.\nח. מען דאַרף דאַוונען, מען דאַרף טאָן אין עבודת התפלה, האָרעווען אויף דאַוונען.\nעבודה איז אַרבעט, אַזוי ווי אַ אַרבעטער, עס קומט פאַרטאָג גיט ער אַ קרעכץ, ער וויל נאָך שלאָפען, חאָטש נאָך אַ 15 מינוט, עס ברעכט אים די ביינער, ער וויל זיך נאָך אויסרוהען, אָבער ער דערמאָנט זיך אַז ער מוז גיין צו דער אַרבעט; אַזוי איז אויך עבודת התפלה, דאַוונען איז אַ עבודה, ניט דאַוונען ווי אַ פידעלע.\nמען דאַרף האָרעווען פאַר'ן דאַוונען, מ'דאַרף האָרעווען אין דאַוונען און מען דאַרף האָרעווען נאָכן דאַוונען צו בע­טראַכטען זיך וואָס האָב איך אָפּגע­האָרעוועט, בכדי אַז במשך כל היום זאָל זיך אנהערען דער דאַוונען ביי יעדערער כפי ענינו.\nט. חסידים בכלל און תמימים בפרט דאַרפען אָנהויבען דאַוונען באריכות. ווען חסידים וואָלטען וויסען ווי זייערע עלטערען און די צדיקים אין גן עדן וואַרטען אויף זייער דאַוונען וואָלטען אַלע געדאַווענט באריכות."],[4301620562,"איך בין מובטח, אַז ווען מ'וועט טאָן אין עבודת התפלה וועט דער אויבער­שטער ממלא זיין אַלע בקשות. תכין לבם תקשיב<sup data-n=\"1732\">7</sup>.\nי. חסידים האָבען כחות עצמיים. זיי האָבען אויגען צו זעהן, אויערען צו הערען, שכל צו פאַרשטיין, נאָר מען דאַרף שייערען די כלי, שייערען אַזוי לאנג עד שיגיע לטהרו, כמארז\"ל<sup data-n=\"1733\">8</sup> חותה אילך ואילך עד שמגיע לטהרו. שייערען שייערט מען מיט זאמד און וואַסער, אָבער עס ווענט זיך וואָס פאַר אַ זאַמד, אויך וואָס פאַר אַ \"מאַטשאַלקע\", אָבער מען דאַרף שייערען ביז מען וועט צוקומען לטהרו, ניט נאָר צו דער כלי נאָר לטהרו של כלי.\nיא. חסידים האָבען כחות וואָס די רביים האָבען זיי מנחיל געווען לדורו­תיהם עד ביאת הגואל.\nיעדער חסיד דאַרף זאָגען אַלע טאָג אַ קאַפּיטעל תהלים ביחוד, אַז דער זכות פון די רביים זאָל ביי זיי נמשך ווערען און עס זאָל ביי זיי נקלט ווערען דער גילוי אור אין אַ פנימיות<sup data-n=\"1734\">9</sup>.\nדער נקודת הענין איז: אור הקדושה איז דאָך אין סוף און צו דעם דאַרף מען האָבען כלים. וואָרום אַז עס איז אין עוד כלי, איז ויעמוד<sup data-n=\"1735\">10</sup> וגו'.\nעס איז דאָ ברק, אַ בליץ. נאָך אַ בליץ קומט אַ דונער. עס קען חלילה אַוועק'הרג'נען אַ מענטשען, דאָס איז ניט דער אמת'ר ברק. עס דאַרף זיין אַז עס זאָל נקלט ווערען. אַ אור פנימי אַז ער ווערט נקלט איז ער אַליין לעבט און באַלעבט אויך אַנדערע.\nיב. מען דאַרף האָבען אַ חוש אין אהבת ישראל, אַז איינער באַגעגענט דעם צווייטען פרעגט ער ביי אים: ברודער, וואָס מאַכסטו. דאָס איז אַזאַ אויסשפּראַך ביי חסידים, מען צוקושט זיך און מ'פרעגט, ברודער וואָס מאַכסטו. דאָס איז אַזאַ רגילות, זיין טאַטע האָט אַזוי געטאָן, זיין זיידע, דער עלטער זיידע, אָבער דאָס איז אַ טרוקענער אהבת ישראל, אָן אַ לעבען. עס דאַרף זיין אַ פייכטער, אַ נאַסער און אַ קלעפּעדיקער. מען דאַרף זעהן יענעמס מעלות, אויב מען זעהט ביי יענעם אַ חסרון איז באמת דער חסרון אין זיך, אַז מען וועט זיך מתקן זיין וועט יענער דערהערען.\nיג. אַ איד דאַרף וויסען אַז וואו ער גייט און וואו ער געפינט זיך איז דאָס מיט אַ סדר מסודר פון מחשבה נעלמה פון עצמות אין סוף.\nיד. עס איז דאָ אַ שטאַרקע תביעה אויף חסידים, פאַרוואָס מען דאַווענט ניט. איך וועל ניט זאָגען ווער דער תובע איז, חסידים פאַרשטייען אָבער אפילו ווען מען זאָגט זיי ניט ווער. איך בין אַ שליח אויף איבערגעבען: מען מאָנט עבודת התפלה. די אַלע וואָס זיינען איצטער דאָ פאַראַן (הראה באצבעו הק' על כל הנאספים) קען יעדער זיין אַ משפיע אויף צוויי דריי מנינים צו לערנען מיט זיי אַ וואָרט חסידות און ווייזען ווי מ'דאַרף דאַוונען.\nטו. איך וויל זאָגען אַ ענין פנימי. איך בין מובטח און איך בין מבטיח, אַז די וואָס נעמען אויף זיך בל\"נ עוסק זיין אין עבודת התפלה וועלען האָבען אַ הצלחה מופלגה אין אַלע זייערע ענינים,",[["1732","7","[תהלים י, יז."],["1733","8","ראה יומא נט, א."],["1734","9","הובא ונתבאר בשיחת ש\"פ פינחס ה'שי\"ת (תורת מנחם התוועדויות ח\"א ס\"ע 48 ואילך)]."],["1735","10","מלכים ב' ד, ו. וראה ג\"כ תורה אור ביאור לד\"ה וקבל היהודים [צז, ב."]]],[4301620563,"בגשמיות וברוחניות. זיי וועלען דאָס זעהן במוחש, זיי וועלען האָבען אַ הצלחה בלתי מוגבלה.\nמען דאַרף טאָן. טאָן מיט מסירת נפש, אָפּרייסען פון עסען, אָפּרייסען פון שלאָפען, אָבער ניט פון דעם זמן וואָס מען דאַרף האָבען פאַר די בני בית, מיט די בני בית דאַרף מען ריידען און מדריך זיין זיי בדרכי החסידות.\nטז. קליינערהייט איז ביי מיר געווען אַ חקירה צי מלאכים ווייסען חשבון, מלאכים ווייסען דאָך אַלץ, צי ווייסען זיי אויך חשבון. האָב איך דאָס געפרעגט הוד כ\"ק אאמו\"ר הרה\"ק, האָט ער מיר געענטפערט: צי מלאכים ווייסען חשבון. — אָבער ברור הדבר אַז מלאך מיכאל מאַכט אַ חשבון פון יעדען קאַפּיטל תהלים וואָס מען זאָגט און דערפון מאַכט ער אַ הענג­לייכטער וואָס בעלייכט למעלה, אין עולם, אים און לדורותיו.\nאיך בין נאָך דאַמאָלסט געווען זעהר יונג; דאָך פלעגט מיר הוד כ\"ק אאמו\"ר הרה\"ק אָפט פרעגען, וואָס הערט זיך מיט דעם \"הענגלייכטער\".\nיז. מיין חסיד'ישער חינוך הפרטי ביי הוד כ\"ק אאמו\"ר הרה\"ק, האָט זיך אָנגעפאַנגען אין יאָהר תרמ\"ט<sup data-n=\"1736\">11</sup>.\nהוד כ\"ק אאמו\"ר הרה\"ק פלעגט דאַן ביי מיר פרעגען, וואָס געדענקסטו<sup data-n=\"1737\">12</sup>? און פלעגט מיר נאָכדעם מסביר זיין די ענינים וואָס איך האָב זיך דערמאָנט פון אַמאָל.\nדער וואָרט: וואָס געדענקסטו? איז מקובל פון זיידען הצדיק ר' ברוך — דער פאָטער פון אַלטען רבי'ן — וואָס דער בעש\"ט האָט דאָס ביי אים געפרעגט. אַזוי האָט דער בעש\"ט געפרעגט ביי אַלע זיינע תלמידים. און בעת די ערשטע יאָהרצייט פון בעש\"ט אום שבועות<sup data-n=\"1738\">13</sup>, ווען דעם בעש\"ט'ס זוהן הרה\"ק ר' צבי האָט זיך אויפגעשטעלט און געזאָגט אַז די גאַנצע פמליא של מעלה האָט זיך איבערגעטראָגען צום מעזריטשער, האָט דאַן דער מעזריטשער מגיד אויך גע­פרעגט ביי אַלע זיינע תלמידים: וואָס געדענקסטו?... און אַזוי האָט געפרעגט הוד כ\"ק רבינו הזקן ביי זיינע תלמידים און אַז מען האָט געענטפערט אויף די שאלה, האָבען זיי מסביר געווען וואָס מען האָט ניט פאַרשטאַנען.\nיח. איך נעם אויף זיך, בל\"נ, אַרויס­געבען אַ ספר הליקוטים פון די מאמרים פון קודם הבר­מצוה און פון לאחר הבר­מצוה<sup data-n=\"1739\">14</sup>.\nיט. עס איז שווער צו מגלה זיין, נאָר מען קען ניט מעלים זיין, און בפרט מצד אהבת ישראל, אהבת השם, און ווי עס איז מקובל ביי חסידים, אַז אַ מקובל'­דיקער וואָרט איז פועל, דערפאַר וויל איך דאָס מגלה זיין:\nהוד כ\"ק אאמו\"ר הרה\"ק פלעגט אָפט אַריינקוקען אין די דריי ספרים: כתר שם טוב, אור תורה<sup data-n=\"1740\">15</sup> און תניא.",[["1736","11","ראה גם רשימת חורף ה'שי\"ת (לקמן ע' 353). וראה רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 241. לעיל ס\"ע 64]."],["1737","12","ראה לעיל ע' 41. וש\"נ."],["1738","13","ראה בכל זה תורת שלום ספר השיחות ע' 94, 324 [ובהוצאת תשי\"ז ואילך: ע' 84­83]. התמים ח\"ב ע' מו."],["1739","14","בשנת תש\"ס יצא לאור (בהוצאת קה\"ת) קונטרס \"בר מצוה תרנ\"ג\" הכולל מאמרי הבר מצוה."],["1740","15","מערכת \"אוצר החסידים\" מכינה עתה לדפוס הוצאה חדשה ומוגהת מספר זה [נדפס בשנת תשל\"ג — שנת המאתיים להסתלקות­הילולא של הרב המגיד ממעזריטש]."]]],[4301620564,"הוד כ\"ק אאמו\"ר הרה\"ק פלעגט ניט וועלען מ'זאָל דערפון וויסען. דערפאַר זיינען די דריי ספרים געלעגען ביי אים אין שופלאָד פון זיין טיש. אין שופלאָד זיינען געלעגען פערשידענע צדקה געל­דער, זיינען די דריי ספרים אויך דאָרט געלעגען, און ער פלעגט אין זיי אַריינ­קוקען פאַר יחידות און פאַר קשהמ\"ט, וויפיעל ער האָט אין זיי געלערענט, צי אַ עמוד, צי עטליכע שורות אָדער אַ ענין ווייס איך ניט, נאָר ער פלעגט עפענען די דריי ספרים און עפּעס לערנען אין זיי.\nעס איז נויטיג ונכון הדבר, אַז חסידים זאָלען האָבען ביי זיך די דריי ספרים און, איבער טעמים ידועים, ניט איינבינדען זיי בכרך אחד. לערנען אין זיי כמה שירצה, אָבער עס זאָל זיין געלערענט, אַלע טאָג, לכל הפחות אין שבתות וימים טובים און בזמנים ידועים.\nכ. ביי חסידים איז פאַראַן אַ טייטש אויף דעם וואָרט וואָס הוד כ\"ק רבינו הזקן זאָגט<sup data-n=\"1741\">16</sup>: כל החיל אשר נגע יראת ה' בלבו — חסיד'ישע קאָזאַקען. ביי אַ קאָזאַק איז דער פערד בטל צום רוכב. ער — דער פערד — איז ניט קיין נפרד, ער לויפט אַנטקעגען פייער, ער שטעלט זיך ניט אָפּ פאַר קיין זאַך. ער לויפט אַנטקעגען דעם פייער מיט שמחה און ווען דער קאָזאַק איז מנצח זיין מנגד איז ער צופרידען און פרעהט זיך אויף זיין שפּראַך. דאָס איז דער ביטול המרכבה אל הרוכב.\nכא. אַה, מען דאַרף האָבען אַ געשמאַק אין אַ אידען. אפילו ווען יענער איז ניט ווי עס דאַרף צו זיין, דאַרף מען וויסען אַז דאָס פעלט ביי זיך, יענער ווייס ניט וואָס ער ווייס, ווען יענער וואָלט וויסען וואָס ער ווייס וואָלט ער אַ ודאי אַנדערש געווען. ווען ער אַליין וואָלט געווען ווי עס דאַרף זיין וואָלט זיך יענער פון אים אָפּגעלערענט.\nכב. חסידים זיינען ניט פויל, נאָר מען פאַרשפּיעלט זיך.\nכג. (לההתועדות נכנס קהל רב והיה צפיפו' גדולה למאד, ואמר אחד מהמקו­רבים: צו אַ גרויסער עולם. ואמר כ\"ק אדמו\"ר שליט\"א:) אין קדושה איז וואָס מעהר — אַ מעלה.\nכד. (לאחר שניגנו את הניגון של ד' בבות מאדמו\"ר הזקן, אמר:) דער זכות פון רבי'ן זאָל מגין זיין, עס זאָל נמשך ווערן צו יעדען און זיינע בני בית הצלחה בגשמיות וברוחניות, מען זאָל נעהנטער ווערען צו דעם גילוי אור המשיח.\nכה. (לאחר ההתועדות כשמזג מכו­סות אחדים שלו יי\"ש ושפך לבקבוק לחלק לאנ\"ש ונשאר מעט מכוס א' שפכו ג\"כ ואמר:) מען דאַרף מייקר זיין אַ טראָפּען.\nכו. (הנאספים התחילו לצאת מהחדר בניגון \"כי בשמחה וגו'\", אמר:) אַוועק­גיין, אָבער ניט אַרויסגיין. מען דאַרף זיך שוין נעמען צו דער אַרבעט.",[["1741","16","שו\"ע שלו חאו\"ח מהדו\"ב ס\"א ס\"ב. בסידורו הערה לתיקון חצות בסופה. אגה\"ק ס\"ל. וראה ג\"כ קונטרס י\"ב תמוז [תש\"ט, שיחת י\"ב תמוז] תש\"ח [לעיל ע' 251. וראה סה\"מ תרפ\"ט ע' 126. ספר השיחות תש\"ב ע' 114]."]]],[4301620565,"<h3>רשימה<sup data-n=\"1742\">1</sup></h3>\n<h4>— ניתנה מכ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע ליום חי אלול תש\"ט — </h4>\n<b>— נעתקה מגוף כתי\"ק —</b>\nמנהגן של ישראל תורה היא<sup data-n=\"1743\">2</sup>. האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט — י\"ב תמוז תר\"ן — צוויי פירושים אין דעם: א) דער מנהג אַליין איז תורה<sup data-n=\"1744\">3</sup>. ב) דאָס וואָס מען היט אָפּ אונטער אַלע אומשטענדען דעם מנהג ישראל, איז דאָס אַליין תורה.\nדברי הוד כ\"ק אאמו\"ר הרה\"ק האמורים זיינען דייטליך קלאָר, אַז זיי דאַרפען ניט קיין ערקלערונג בכלל און בפרט מען זאָל דאָס דאַרפען מבאר זיין בהטעמה.\n* * *\nבעלי עיון אין לימוד התורה און בעלי חריפות, זיינען צוויי דרגות חלוקות אין סוגי השכלה. עס גיבט בעלי עיון וואָס יעדער עיון שכלי קוועלט באַ זיי און ווערט באַרייכערט מיט שכלים עיוניים אין אַ אופן פון שאלה ותשובה, וואָס יעדער אופן השכלה איז אַ געוויסע שליבה — טרעפּ — צו דער צווייטער דרגא השכלה. דאָס מיינט אַז די צווייטע השכלה איז אַ געוויסע תולדה שכלית פון דער ערשטער השכלה. די צווייטע השכלה איז געוויס רייכער אין איינעם פון די דריי חלקי חב\"ד וואָס אין השכלה, אָבער בכללות איז דאָס אין די ראַמען פון דעם ענין שכלי אין וועלכען ער איז זיך עוסק.\nדער ענין פון בעלי חריפות איז גאָר אַ בעזונדער סוג אין בעלי השכלה. תמורת דעם וואָס דער בעל העיון איז די טיפסטע השכלה חידושים זיינע, אין די אַלע דריי טיילען חב\"ד, מיט צוגענגליכע ביאורים און הסברים; איז באַ די בעלי חריפות, איז זייער חב\"ד איז געוויסע השכלות און המצאות אין אַזעלכע שכלים נפלאים וואָס מען קען מיט זיי דערקלערען כמה עיונים פון השכלות נסתרות.\nדי צוויי השכלה דרגות, בעלי עיון ובעלי חריפות, זיינען חלוק אין די חלקי דרגות פיהלען און פאַרשטיין, וכן חלוקים באַ חסידי חב\"ד בעלי עבודה — אין אריכות התפלה און בירור וזיכוך המדות.\n* * *\nמנהגן של תלמידי הוד כ\"ק אבותינו רבותינו הק' נשיאי חב\"ד, אַז יעדער אייינער האָט בדורו מדייק געווען, מיט אַ געוויסען הדרכה ביאור בעל פה, אין אַ שיחה ברבים, אָדער דורך אַ געשרי­בענעם בריף אָדער קונטרס, אַ הנהגה אָדער אַ התעוררות וואָרט פון איינעם פון הוד כ\"ק נשיאי חב\"ד אָדער מוריהם רבינו הבעש\"ט אָדער רבינו הרב המגיד ממעזריטש זי\"ע.\nדי אויבענדערמאָנטע הדרכה — ביאורים פאַרנעמען דעם גרעסטען בעסטען פרוכטבאַרן פּלאַץ אין עדת חסידי חב\"ד, פון דעם ערשטען טאָג וואָס",[["1742","1","נדפס בסה\"מ ה'שי\"ת ע' 286 ואילך עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו."],["1743","2","תוד\"ה נפסל מנחות כ, ב: מנהג אבותינו תורה היא. וראה ג\"כ מנהגים ישנים מדורא ע' 153. מהרי\"ל הובא ברמ\"א בשו\"ע יו\"ד סשע\"ו ס\"ד [וראה לקמן ע' 348]."],["1744","3","[ראה גם שיחת ג' אדר שנה זו (לעיל ע' 303)]."]]],[4301620566,"הוד כ\"ק רבינו הזקן האָט מקבל געווען אין יאָהר תקכ\"ה, ח\"י אלול, ווען ער איז געוואָרען אַ בן עשרים.\n* * *\nאונזער געבורט און וואוינארט, די וויגעלע פון חסידות חב\"ד — ליובאַוויטש — איז געווען אין מאָהליווער גובערניע, און די שטעטעל ליאָזנא איז געווען אין וויטעבסקער גובערניע, אָבער אין די אינערליכע סדרים זיינען זיי געווען ווי אַלע קליינע שטעטלעך אין יענער צייט, הילצערנע הייזער געדעקט מיט דראניצעס, און די הייזער פון די זייטיקע גאַסן געדעקט מיט שטרוי, וואָס דאָס איז געווען די הויפּט­סיבה פון די אָפטע שריפות, וואָס האָבן געמאַכט פיעל זאָרג אין דעם אופן השמירה פון די כתבים און האָבן געבראַכט פיעל הזיקות.\nכהיום איז פריש אין זכרון די איבער­געשראָקענע פנים'ער און די בהלה­געשרייען \"עס ברענט\".\nאון נאָך אַלע שמירות האָט מען — לא עתה — געליטען גרויסע כתבים און ספרים הזיקות. צווישען זיי אויך אַ סך פון די ביאורים.\n* * *\nאין מיין יומן איז פאַרשריבען דער סדר השמחה בצנעה און די דבורי קודש וואָס הוד כ\"ק אאמו\"ר הרה\"ק האָט מיר דאַן — יב תמוז תר\"ן — דערציילט, פון דעם אריכות הסיפור וואָס הוד כ\"ק אביו אאזמו\"ר הרה\"ק מוהר\"ש האָט אים בלחש איבערגעגעבען, וואָס הוד כ\"ק אביו אאזמו\"ר הרה\"ק צמח צדק האָט אים דערציילט אין דעם יום הקדוש ווען עס איז נתמלא געוואָרען הונדערט יאָהר זינט די התגלות נשמת כ\"ק רבינו הזקן.\nוזה לשונו הקדוש: אין דעם דאָזיקען יום הקדוש איז געווען אַ שמחה כפולה אין אַלע עולמות בדרך העלאה מלמטה למעלה און בדרך המשכה מלמעלה למטה.\nאין דעם יום הקדוש בן מאה פון גילוי נשמת רבינו בעלמא דין<sup data-n=\"1745\">4</sup> איז אַ גילוי שמחה כפולה, שמחת הנשמה און שמחת העולם. די שמחה פון דער נשמה איז וואָס זי האָט דורכגעפירט איר שליחות אין דער התגלות אין עולם החומרי, און שמחת העולם פון דעם וואָס די חומריות העולם האָט ממלא געווען די כוונת ההעלם.\nדער גילוי השמחה פון אַ נשמה בכלל און פון נשמת הצדיק בפרט און פון נשמת נשיא עדת ישראל בפרטי פרטיות איז מגלה אור וחיות פנימי אין תלמידיו ותלמידי תלמידיו לדורי דורות.\n* * *\nהוד כ\"ק אאמו\"ר הרה\"ק זאָגט מיר — י\"ב תמוז תרנ\"ה —, דער טאַטע — הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש — האָט מיר געזאָגט בשם דעם זיידען — רבינו הצמח צדק — אַז הוד כ\"ק רבינו הזקן האָט אין אַ געוויסער צייט געזאָגט אים און דעם שווער — כ\"ק אדמו\"ר האמצעי:\nאַז ווען אין לבושי הנשמה פון נר\"ן איז עפּעס ניט מובן ומושג אַ ענין אין השכלה והבנה, איז דאָס אַ עונש אויף דעם העדר עבודה אין עבודת התפלה. די עצה לזה איז תשובה פנימית, וואָס מען בעדאַרף מעורר זיין פנימית הנשמה. דאָס מיינט מקיפים עצמי' חי'",[["1745","4","נולד ביום ד' חי אלול שנת תק\"ה. וראה שיחת חי אלול ה'תש\"ה (ליקוט כ\"ה) אות ח' [ספר השיחות ה'תש\"ה ע' 127] שנשמה חדשה צריכה הכנה מקודם שלש שנים, ואולי זהו הדיוק כאן \"בעלמא דין\"."]]],[4301620567,"יחידה; חי' לעבעדיק בעצם, יחידה יחיד ה'.\n* * *\nדעם מאמר עצמי האָט הוד כ\"ק אאזמו\"ר הרה\"ק צמח צדק איבערגעזאָגט בדיוק כלשונו בזמנים מיוחדים וידועים און האָט איבערגעגעבן דעם זיידען — הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש — מיט געוויסע הוראות ווען ער זאָל דעם מאמר איבערזאָגן בדיוק כלשונו.\nהוד כ\"ק אאמו\"ר הרה\"ק זאָגט איבער דעם מאמר מדוייק כלשונו הק' כאמור מיט אַ געוויסע דביקות און פני קדשו מאירים בהתלהבות קדש, און גיט מיר איבער געוויסע הוראות קדש ווי און ווען דאָס איבערחזרן במחשבה ודבור לעצמי וגם ביחידות להראויים לזה."],[4301620568,"<h3>תש\"ט<sup data-n=\"1746\">1</sup></h3>\nמלפנים היה הסדר אצל אדמו\"ר הזקן ואדמו\"ר האמצעי, וזמן גם אצל אדמו\"ר הצ\"צ, אשר בצאת כל אחד מהיכל היחידות הי' נכנס במחול<sup data-n=\"1747\">2</sup> עם החסידים הנאספים, און מ'האָט גוט פאַרבראַכט, ואז הי' ההתחלה מהנטיעה. בבוא כל אחד מהנכנסים לעירו הביתה הי' אז יום­טוב אצל כל אנ\"ש. שבת­קודש התוועדו כולם ונטלו ידיהם לסעודה ואכלו לחם ומליח והוא הי' ראש המדברים וחזר על היחי­דות מה ששמע מכ\"ק האדמו\"ר. וכן היו נוהגים והשמחה והריקודים וההתפעלות הי' ביותר אצל כל אנ\"ש. וכל זה עשה רושם גדול ובפרט אצל הנכנס בעצמו שהי' אצלו הקליטה מהנטיעה.\nאמנם, פעם נסע הרה\"ח ר' הלל מפּאַריטש<sup data-n=\"1748\">3</sup> לליובאַוויטש וסיפר לאדמו\"ר הצ\"צ אודות זה, וצוה הצ\"צ להחליש זאת מסיבת המחלוקת והבלבולים של המתנגדים שהיה בזמן ההוא, ומני אז נחלש הענין עד שנפסק כו'.\nואח\"כ אמר כ\"ק אדמו\"ר שליט\"א: אַה, דער סדר פון ליובאַוויטש, ווי גוט און געשמאַק דאָס איז געווען. . .\n* * *\n[מקובל מרבותינו הק' בשם הרב המגיד ממעזריטש שאמר בשם הבעש\"ט ז\"ל, אשר בעת שמחה, תנאים, חתונה, או ברית­מילה יכולים לתת מזל­טוב קודם המעשה.\nושאלתי את כ\"ק אדמו\"ר שליט\"א איך הי' הלשון הק' שיכולים או שצריכים (מ'קען צי מ'דאַרף)? ואמר כ\"ק אדמו\"ר שליט\"א:] צריכים לומר מזל­טוב קודם השמחה כי זה גורם שהדבר הטוב יבוא למטה בתגבורת, ותגבורת שוללת מניעות ועיכובים.",[["1746","1","מרשימת הרה\"ח ר' אליהו (ייאכיל) סימפּ­סאָן ממה ששמע מרבינו בתקופה ששימש כגבאי של רבינו. ראה אודותו לעיל ע' 51."],["1747","2","ראה לעיל ע' 110. וש\"נ."],["1748","3","ראה אודותו לעיל ע' 29. וש\"נ."]]],[4301620569,"<h3>ערב ראש השנה ה'שי\"ת<sup data-n=\"1749\">1</sup></h3>\n<i>לאחר התרת נדרים</i>\nאויבערשטער זאָל געבן אַ התעוררות תשובה אמיתית אין אַ קבלת עול מלכות שמים באמת ובפנימית הלב, אַז עס זאָל אַראָפּקומען אין אַ בפועל ממש.\nדער אויבערשטער זאָל רחמנות האָבען אַז עס זאָל אַראָפּגענומען ווערען אַלע מניעות ועיכובים אויף תורה ועבודה.\nדי עצה אויף דעם איז, אַז דער אויבערשטער זאָל געבען אידען אַ שנה טובה ומתוקה בגשמיות ורוחניות בכלל ובפרט — וועלן אידן טאָן וואָס זיי קענען, און דער אויבערשטער וועט זעהן וואָס אידען קענען.\nדער אויבערשטער זאָל געבען אַז ס'זאל זיין אַ גאולה אמיתית בקרוב ממש.\n* * *\n<i>בעת שנתנו לכ\"ק אדמו\"ר את הפדיון ע\"ד כלל ישראל, והפדיון השייך לכ\"ק אדמו\"ר בעצמו.</i>\nהיינט איז אַ זמן וואָס דער פרט דאַרף נכלל ווערן אין כלל<sup data-n=\"1750\">2</sup>. אויף דעם כלל איז מען ניט מדקדק, דעם כלל גיט דער אויבערשטער גאָר אַפולע, דער כלל איז דאָך גוט, ביי יעדען איינעם איז דאָך דער כלל גוט, אויב עס פעלט איז דאָס אין פרטים. בפרט היינט ער\"ה איז דאָך דער כלל אין זמן, איז דאָך דער כלל אין כלל, איז גאָר גוט.\n* * *\n<i>כשנכנסו לקבל ממנו את הפ\"נ לקראו על ציון כבוד אמו הרבנית הצדקנית מרת שטערנא שרה נ\"ע זי\"ע.</i>\n(אמר א': היינטיגן יאָהר דאַרף דאָך אַודאי זיין גוט, מאחר שנאמר בהמאמר פון פאַר ר\"ה<sup data-n=\"1751\">3</sup> כי השי\"ת חייב לסלוח און ער קען דאָך. וענה כ\"ק אדמו\"ר שליט\"א:) און ער וויל. באמת זיינען דאָך אַלע אידען גוט, — אַה, די פשוטע אידען.\nאַז עס וואָלט געווען ווער עס זאָל עם זאָגען דעם אמת, אַז ער איז גאָר שולדיק; אַז דער אויבערשטער וואָלט געבען אַלעס גוט אין אַלע ענינים בגו\"ר וואָלט מען זעהן וואָס אידען ווילען טאָן מצד הנשמה. עס זאָל אַרונטערגענומען ווערען אַלע מניעות ועיכובים, וואָלט אַלעס געווען גוט.\nאַ כתיבה וחתימה טובה אַ שנה טובה ומתוקה.\n(נתן בתוך הפ\"נ מעות על צדקה לחלק על דעתם. והוסיף אַז מען קען דאָס פודה זיין).",[["1749","1","נדפס עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ תשי\"א ע' 17."],["1750","2","זהו הפעם היחידה שענה כ\"ק מו\"ח אדמו\"ר הכ\"מ כנ\"ל אודות הפדיון שלו."],["1751","3","ד\"ה אני לדודי ג' דסליחות תש\"ט (קונטרס סח) [סה\"מ תש\"ט ע' 230 ואילך]."]]],[4301620570,"<h3>די רייד </h3>\n<b>פון ליובאַוויטשער רבי'ן שליט\"א פאַר אַ גרופּע עסקנים פון דעם מרכז הישיבות תומכי-תמימים ליובאַוויטש </b>\n<b>מיטוואָך, פ' האזינו, ה' עשי\"ת, תש\"י<sup data-n=\"1752\">1</sup></b>\nברוכים הבאים!\nאיהר אַלע זייט ביי מיר זייער חשוב'ע געסט. אהבת ישראל — האָלט האָבען אַ אידן, איז אַ געבוירענע זאַך ביי יעדער אידיש קינד אָן אונטערשייד צווישען שפל שטאַנד און יחוס שטאַנד.\nאונזער אַלגעמיינער טיטול איז יוד, וואָס אַלע ווייסען די הפלאת המעלה פון אות יוד לגבי אַנדערע אותיות אַז אַלע אותיות איז זייער תמונה הויבט זיך אָן מיט דעם נקודת היוד<sup data-n=\"1753\">2</sup>.\nצו אונז גזע הוד כ\"ק רבינו הזקן איז איבערגעגעבען אַ וואָרט וואָס הוד כבוד קדושת רבינו הזקן האָט מקבל געווען פון זיין רבי'ן הוד כ\"ק רבינו המגיד ממעזריטש וועלכער האָט דאָס וואָרט מקבל געווען מהוד כבוד קדושת מורנו הבעל שם טוב.\nדער ערשטער אות פון שם הוי' איז דער אות יו\"ד ווייל אַ איד איז דער טעם און כוונה פון בריאת העולם, און די תמונה פון אות יו\"ד איז מגלה און דערקלערט די כוונה צוליעב וואָס השם יתברך האָט באַשאַפען די וועלט. דער קוץ העליון איז מרמז אויף דער כוונה וואָס עלה ברצונו יתברך צו באַשאַפען דעם עולם הגשמי, און דער קוץ התחתון איז מורה אויף דעם יש הגשמי, און ווען מען פירט דורך אין דעם וועלטליכען גשמיות'דיגען לעבען די כוונה העליונה צוליעב וואָס השם יתברך האָט באַשאַפען די וועלט איז דאָס דער ריכטיקער תמונת היו\"ד. יעדער איז לפי מצבו ולפי ענינו, דאָס הייסט לפי העבודה וואָס זיין נשמה בעדאַרף דורכפירען בעלמא דין להצלחה און דער יסוד מוסד איז החזקת לומדי תורה ביראת שמים.\nבאַ תורה שטייט כי טוב סחרה מכל סחורה<sup data-n=\"1754\">3</sup>, תורה איז אַ מזומנ'ע סחורה ווי אַ סוחר לויבט זיין סחורה דאַרף איך אייך ניט מבאר זיין. איך האָב אָפטערס געהערט ווי אלטע גרינדליכע סוחרים פירען זיך, ווען איינער קומט צו אַ סוחר און בעט ער זאָל אים געבען סחורה, ער באַדאַרף האָבען אַ היבשע ביסעל ווייל אַלע פרעגען זיך אויף דער דאָזיגער סחורה, ענטפערט דער גרויסער סוחר, וואָס זאָגסטו אויף איהם, ער וויל אַ היבשע ביסעל סחורה, מיין סחורה איז דאָך מיט גאָלד צוגלייך און אַז איך וועל דיר געבן אַ לעק סחורה האָט דאָך דאָס אויך זייער אַסך די ווערט, דו וועסט די ביסעל אויך צוצוקערען, כי טוב סחרה מכל סחורה, דער אמת'ער טוב סחרה מכל סחורה זאָגט ער אויף תורה.\nאיך בין זייער צופרידען פון אַייער אַרבייט פאַר תורה, איך מיין ניט פון דעם וויפיעל געלט איר גיט, איך ווייס ניט צו איהר גיט גענוג וויפיעל איהר דאַרפט געבען, דאָס דאַרף מען פרעגען ביי דעם מנהל, איך מיין פון אַייער איבערגע­בענקייט, דאָס איז העכער פאַר אַלץ.",[["1752","1","נדפס בלקו\"ד ח\"ג תקסט, ב."],["1753","2","ראה גם אגרות­-קודש ח\"ט ע' תפה. ועוד."],["1754","3","פיוט \"שישו ושמחו בשמחת תורה\". וראה גם שיחת י\"ט אלול תש\"ח (לעיל ע' 267)."]]],[4301620571,"איך רייד דאָ ניט פון דעם ענין פון געלט געבען נאָר איך מיין אין דעם וועלען תורה. אַז ביי אייך מאַכט זיך איהר באַגעגענט זיך מיט נאָך אַ אידען דאַרף מען איהם פרעגען וואָס טוסט דו פאַר תורה, איך האָב געלויבט השם יתברך געטאָן דאָס און דאָס און וואָס טוסט דו?\nאיך רייד דאָס וועגען תורה בכלל און בפרט תומכי תמימים וואָס איז דאָך אַ אַלטער מוסד וואָס דער טאַטע האָט מייסד געווען און מיט טרערען געבעטען דעם אויבערשטען בזכות פון די הייליגע עלטערען ער זאָל מצליח זיין הן צו די תלמידים אין גשמיות און עס זאָל זיך אָנזעהן אין רוחניות און הן פאַר די וואָס וועלען מחזיק זיין תומכי-תמימים, זיי און זייערע בני בית זאָלען מצליח זיין בגשמיות וברוחניות און די ברכה ווערט מקויים בכל עת ובכל זמן.\nמיט דעם כח וואָס מען האָט מיר געגעבען אויף צו בענטשען אנ\"ש, מחזיקי תורה און אידען בכלל — בענטש איך אייך אַז דער אויבערשטער זאָל אייך אַלעמען געבען אַ שנה טובה ומתוקה, אַ חתימה וגמר חתימה טובה אין אַלע ענינים, אייערע ענינים זאָלען זיין ווי על פי תורה, איהר זאָלט האָבען אַ געשמאַק אין אהבת השם, אהבת התורה און אהבת ישראל.\nברוכים תהיו בגשמיות וברוחניות."],[4301620572,"<h3>שיחה<sup data-n=\"1755\">1</sup> </h3>\n<b>מוצאי יו\"כ תש\"י, בסעודה<sup data-n=\"1756\">2</sup></b>\n<i>— לויט אַ פערצייכנונג פון די הערער —</i>\nא. פון די חושים מיוחדים וואָס דער אויבערשטער האָט געבענטשט הוד כ\"ק אאמו\"ר הרה\"ק האָט ער גערעכענט דעם חוש הציור אין דיבור<sup data-n=\"1757\">3</sup>, דעם כח אַרויס­צוטראָגען אין דיבור אַ זאַך כאלו ווי דאָס לעבט. אין ציור איז דאָך דער עיקר דער חיות פון דער זאַך. דער צמצום און כיבוש — אַיינקוועטשען — פון דעם גולם און דער אַרויסבריינגען פון דעם חיות.\nדער גולם מוז זיין, ווייל אין חיות אַליין איז ניט שייך קיין ציור, אָבער דער עיקר איז צו מגלה זיין דעם חיות פון דעם, ביז וואַנען דער גשם ווערט אַ חי. דער גולם איז דאָך עפר ווערט דאָס אַ חי. ניט נאָר דער גשם ווערט חי נאָר דער חומר ווערט חי. ער דערהערט די הפלאה פון חומריות על הגשם און דאַמאָלסט דערהערט זיך אין דעם גשם אַ אור וחיות פנימי.\nב. דעם וואָרט האָט הוד כ\"ק אאמו\"ר הרה\"ק געזאָגט מיט צענדליקער יאָהרען צוריק מוצאי יוהכ\"פ, און האָט דערביי געזאָגט:\nהיינטיגען יום כיפור האָב איך דעם ענין דערהערט במוחש. וויסען דעם ענין האָב איך געוואוסט פריהער אויך, נאָר במוחש איז דאָס ביי מיר נתחדש גע­וואָרען היינטיגען יוכ\"פ.",[["1755","1","נדפס עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ תשי\"א ע' 41 ואילך."],["1756","2","בעמערקונג:\nאַ טייל פון דער שיחה איז אריין אין דער רשימה פון כ\"ק מו\"ח אדמו\"ר הכ\"מ, וועלכע איז געדרוקט אין קונטרס ב' ניסן השי\"ת (קונטרס עו) [נדפס לקמן ע' 347 ואילך."],["1757","3","ראה גם שיחת ליל שמח\"ת שנה זו (לקמן ע' 373)."]]],[4301620573,"אַז מען האָט הוד כ\"ק אאמו\"ר גע­פרעגט: וואָס מיינט במוחש?\nהאָט הוד כ\"ק אאמו\"ר הרה\"ק גע­ענטפערט:\nראיית פני הרב.\nפון דעם איז משמע, אַז יענעם יום כפור האָט הוד כ\"ק אאמו\"ר הרה\"ק עפּעס געזעהען, וואָס אַנדערע זעהען דאָס ניט.\nאַז מען שטייט אין אַזעלכע ד' אמות דאַרף מען זיין גאָר אַן אַנדערער.\nג. הוד כ\"ק אאמו\"ר הרה\"ק פלעגט קלייבען ווערטער און סיפורים וואָס ער האָט געהערט פון החסיד רשב\"ץ<sup data-n=\"1758\">4</sup> און פון אַנדערע עלטערע חסידים. איינער פון די סיפורים איז געווען:\nאַ חסיד איז אַריינגעגאַנגען צום זיידן הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש אויף יחידות, האָט ער געהערט אויף יחידות — מיט דעם לשון האָב איך געהערט פון הוד כ\"ק אאמו\"ר הרה\"ק — אַ ענין<sup data-n=\"1759\">5</sup> עמוק עמוק מי ימצאנו<sup data-n=\"1760\">6</sup>. דער פירוש איז, אַז דער מי איז ימצאנו. אַזוי איז דאָך דער טייטש ימצאנו מל' מציאה, אָבער דאָ האָט ער געטייטשט ימצאנו פון לשון אויסדריקען — אויסקוועטשען. דער מי קען דאָס מגלה זיין. \"מי\" מיינט דער מי ברא אלה, זעהען דעם כח המהווה אין יעדען גשם, זעהען דעם חיות אלקי פון יעדער זאַך און די השגחה פרטית וואָס איז דאָ אין יעדער זאַך. לדוגמא, אַז דעם מענטש דוכט זיך אַז ער דאַרף גאָר יעצט זיין אין אַן אַנדער אָרט און ער קומט גאָר אַהער, מיינט ער אַז דאָס איז דורך אַ טעות. אָבער דער אמת איז, אַז עס איז גאָר קיין טעות ניט. אַ איד געהט ניט אַליין, נאָר מען פיהרט איהם. ער דאַרף זיין דא, ווייל ער דאַרף עפּעס נעמען פון דאַנען, און ער האָט עפּעס געבראַכט אַהער, ווייל אַ איד וואו ער גייט בריינגט ער עפּעס. נאָר דאָס איז בהעלם, דער נעמען פון דאַנען איז אויך בהעלם, אָבער ער דאַרף דאָס אויספּאַקן, ער דאַרף דאָס מגלה זיין, וואָס ער האָט פון דאַנען גענומען.\nד. אַמאָליקע יונגעלייט האָבען זיך געריבען אַרום עלטערע חסידים. די עלטערע חסידים האָבען זיי געגעבען און די יונגעלייט האָבען עפּעס גענומען, און דעם \"עפּעס\" האָבען זיי מנחיל געווען לדורותיהם.\nאָט דאָס איז אַ חסיד, און דאָס איז אַ חסיד'ישע מסיבה.\nה. (כ\"ק אדמו\"ר שליט\"א צוה לנגן, ואמר:)\nיעצט דאַרף זיין מהירות. די ד' ימים — בין יוכ\"פ לסוכות — זיינען דאָך כנגד די ד' אותיות פון שם הוי'<sup data-n=\"1761\">7</sup>, און איצטער — מוצאי יוכ\"פ — איז דער קוצו של יו\"ד, אָבער דאָס איז אַ אור מבהיק.\nמען דאַרף זינגען אַ פנימיות'דיגען ניגון וואָס — (והראה בידו הק') — זאָל דורכנעמען.\nו. (אחר ברכת המזון על הכוס — הכוס לא שתה בעצמו, כי אמר שקשה לו לשתות כעת יין, ונתן אחר ברהמ\"ז את הכוס לאחד מהמסובים שיעשה הברכה בפה\"ג וישתה — אמר:)",[["1758","4","ראה אודותו — לעיל ע' 12. וש\"נ]."],["1759","5","דעם לשון המאמר בדיוק זע די אויבענ­דערמאָנטע רשימה [סה\"מ ה'שי\"ת] ע' 167 [לקמן ע' 355]."],["1760","6","[קהלת ז, כד. וראה גם לעיל ע' 8]."],["1761","7","[ראה סה\"מ תרח\"ץ ע' סז. אגרות­-קודש ח\"א ע' קצד. ח\"ג ע' תפג ובהערה 8 שם. ספר השיחות תרפ\"ח­תרצ\"א ע' 25. תרצ\"ו­חורף ה'ש\"ת ע' 161]."]]],[4301620574,"עס וועט זיין אַ פרייליכער יאָהר. די התחלה פון דעם יו\"ד איז געווען בשמחה און די שמחה פון דעם יו\"ד<sup data-n=\"1762\">8</sup> זאָל נמשך ווערען אין די אַלע ד' אותיות.\n(אחר כך נתן כ\"ק אדמו\"ר בקבוק יין מהשולחן להרש. ל. שי' ואמר:) מען זאָל גיין פאַרבריינגען אין בית המדרש.\nז. כשיצאו מהחדר שרו את הניגון כי בשמחה תצאו וגם הלכו בריקוד בחדר הסמוך וכ\"ק אדמו\"ר שליט\"א הביט בפנים צהובות ושוחקות.",[["1762","8","ברשימה אחרת: די שמחה פון דעם קוצו של יו\"ד."]]],[4301620575,"<h3>חורף<sup data-n=\"1763\">1</sup></h3>\nא. איינער פון די תורה­נקודות­ווערטער וואָס הוד כ\"ק רבנו הזקן האָט מקבל געווען מהוד כ\"ק מורו מורנו הרב המגיד ממעזריטש שקיבל ממורו מורנו הבעש\"ט מה שקיבל ממורו הבעל ח\"י<sup data-n=\"1764\">2</sup>.\n— הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש גיט איבער, אין זמנים ידועים, להוד כ\"ק אאמו\"ר הרה\"ק ענינים וואָס הוד כ\"ק אביו אאזמו\"ר הרה\"ק צמח צדק האָט אים אין זמנים שונים איבערגעגעבען מיט געוויסע ביאורים. און דער וואָרט איז איינער פון זיי —\nאתפשטותא דמשה בכל דרא<sup data-n=\"1765\">3</sup>, יעדער איינצעלנער איד, איש אָדער אשה, איז אַ דור, וואָס ווען זיי קומען אין זמן פון חיי משפחה על פי תורה ווערן זיי גע­בענטשט פון דעם משה וואָס בדורם, וואָס ער איז כל מהותו ועצמותו טאַקע אַ אור עצמי, אָבער זיין אור עצמי איז דער מאור המאיר מאתפשטותא דמשה בכל אחד ואחת בשלש האהבות: אהבת השם אהבת התורה ואהבת ישראל.\nדער וואָרט, איז איינער פון די דיוקים­ווערטער, ווי ער רופט זיי בסגנונו המדויק, וואָס הוד כ\"ק אאמו\"ר הרה\"ק גיט מיר איבער אין געוויסע צייטען, און זאָגט דערביי:\nדאָס וואָס איך גיב דיר איבער זאָל אין דיר פועל זיין התרחבות העמקת ותוקף הדעת, זיין בכל תוקף עוז, אין אַלע זמנים און אין יעדער מקום ווי איך האָב דיר איבערגעגעבען.\nב. הוד כ\"ק אאמו\"ר הרה\"ק גיט מיר איבער אין אַ געוויסען זמן פאַרשידענע ענינים וואָס קומען בקבלה מנשיא לנשיא, צווישען זיי די תורה האמורה, און זאָגט מיר:\nאין דער יחידות וואָס איך האָב גע­האַט ביים טאַטען, ווי איך האָב דיר געזאָגט, האָט ער מיר געזאָגט: דער עבודה­סדר פון די ג' אהבות איז: אהבת ישראל, אהבת התורה און אהבת השם<sup data-n=\"1766\">4</sup>.",[["1763","1","נרשמה ע\"י כ\"ק אדמו\"ר זצוקללה\"ה נבג\"מ זי\"ע בחורף ה'שי\"ת — נעתקה מגוף כתי\"ק. נדפס עם מ\"מ והערות מכ\"ק אדמו\"ר נשיא דורנו בסה\"מ ה'שי\"ת ע' 160 ואילך. \"וכנראה שייכת ג\"כ לשיחת מוצאי יום הכיפורים דהאי שתא\" (סה\"מ שם ע' 150)."],["1764","2","מורנו הבעש\"ט רופט אחי' השילוני דער בעל ח\"י — חי' יחידה. דעם תואר האָט דער מיטעלער רבי מסביר געווען: אַ בעל אויף דעם אופן התגלות עצמי פון די מקיפים חי' יחידה (ספר השיחות קיץ ה' ש\"ת [ע' 159. וראה לעיל ע' 232 ובהערה 18])."],["1765","3","תיקוני זהר תיקון סט (קיב, א קיד, א). ועייג\"כ זח\"ג רטז, ב. רעג, א. ת\"ז ת\"ע (קלח, א)."],["1766","4","[ראה גם לעיל ע' 149)]."]]]]});
